import type { ISplit, ITransaction } from '../domain/types';
import { Frequency } from '../domain/types';

export interface IDetectedPattern {
    /** Normalized payee name used as the key. */
    payee: string;
    /** Account where the transactions were found. */
    accountId: string;
    /** Suggested repeating frequency. */
    suggestedFrequency: Frequency;
    /** Median amount (in cents) across matched occurrences. */
    suggestedAmount: number;
    /**
     * 0–1 confidence score.
     * 0.7+ = high confidence (safe to pre-select).
     * 0.4–0.69 = medium (show to user with caveat).
     * <0.4 = low (suppress unless user opts into low-confidence).
     */
    confidence: number;
    /** The most recent occurrence (used to populate the recurring form). */
    mostRecentTransaction: ITransaction;
    /** Splits from the most recent occurrence (preserves split structure). */
    mostRecentSplits: Array<ISplit>;
    /** Sample of dates from matched transactions. */
    sampleDates: Array<string>;
}

// ── Frequency thresholds (median days between occurrences) ──────────────────
interface IFrequencyBucket {
    frequency: Frequency;
    /** Expected interval in days (center). */
    center: number;
    /** Acceptable deviation ±days from center. */
    tolerance: number;
}

const FREQUENCY_BUCKETS: Array<IFrequencyBucket> = [
    { frequency: Frequency.Weekly, center: 7, tolerance: 2 },
    { frequency: Frequency.Biweekly, center: 14, tolerance: 3 },
    { frequency: Frequency.EveryFourWeeks, center: 28, tolerance: 3 },
    { frequency: Frequency.Monthly, center: 30, tolerance: 5 },
    { frequency: Frequency.Quarterly, center: 91, tolerance: 12 },
    { frequency: Frequency.Yearly, center: 365, tolerance: 20 }
];

// ── Helpers ──────────────────────────────────────────────────────────────────

function normalizePayee(payee: string): string {
    return payee.toLowerCase().trim().replace(/\s+/g, ' ');
}

function median(values: Array<number>): number {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 !== 0
        ? (sorted[mid] ?? 0)
        : ((sorted[mid - 1] ?? 0) + (sorted[mid] ?? 0)) / 2;
}

function stddev(values: Array<number>, mean: number): number {
    if (values.length < 2) return 0;
    const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
    return Math.sqrt(variance);
}

function daysBetween(dateA: string, dateB: string): number {
    return Math.round(
        Math.abs(new Date(dateB).getTime() - new Date(dateA).getTime()) / (1000 * 60 * 60 * 24)
    );
}

function classifyFrequency(medianDays: number): Frequency | null {
    for (const bucket of FREQUENCY_BUCKETS) {
        if (Math.abs(medianDays - bucket.center) <= bucket.tolerance) {
            return bucket.frequency;
        }
    }
    return null;
}

/**
 * Compute a confidence score [0, 1] based on:
 * - Interval consistency: low stddev relative to center = higher confidence
 * - Amount consistency: low coefficient of variation = higher confidence
 * - Occurrence count: more occurrences = higher confidence
 */
function computeConfidence(
    intervals: Array<number>,
    amounts: Array<number>,
    occurrences: number
): number {
    const medianInterval = median(intervals);
    if (medianInterval === 0) return 0;

    const intervalSd = stddev(intervals, medianInterval);
    const intervalCv = intervalSd / medianInterval; // coefficient of variation

    const medianAmount = median(amounts);
    const amountSd = stddev(amounts, medianAmount);
    const amountCv = medianAmount !== 0 ? amountSd / Math.abs(medianAmount) : 1;

    // More occurrences → higher floor
    const countScore = Math.min(1, (occurrences - 2) / 6); // 0 at 2 tx, 1 at 8+

    // Interval consistency (low CV = consistent = good)
    const intervalScore = Math.max(0, 1 - intervalCv * 2);

    // Amount consistency (CV < 0.1 = fixed rate, CV > 0.5 = highly variable)
    const amountScore = Math.max(0, 1 - amountCv * 2);

    return Math.min(1, countScore * 0.25 + intervalScore * 0.45 + amountScore * 0.3);
}

// ── Public API ───────────────────────────────────────────────────────────────

const MIN_OCCURRENCES = 3;
const MIN_CONFIDENCE = 0.35;

/**
 * Analyze a flat list of transactions and return detected recurring patterns.
 * Results are sorted by confidence descending.
 *
 * @param transactions - All transactions from a ledger (or filtered by account).
 * @param minConfidence - Minimum confidence threshold (default 0.35).
 */
export function detectRecurringPatterns(
    transactions: Array<ITransaction>,
    minConfidence = MIN_CONFIDENCE
): Array<IDetectedPattern> {
    // Group by normalized payee + accountId
    const groups = new Map<string, Array<ITransaction>>();

    for (const tx of transactions) {
        if (!tx.payee) continue;
        const key = `${tx.accountId}::${normalizePayee(tx.payee)}`;
        const group = groups.get(key) ?? [];
        group.push(tx);
        groups.set(key, group);
    }

    const results: Array<IDetectedPattern> = [];

    for (const [, group] of groups) {
        if (group.length < MIN_OCCURRENCES) continue;

        // Sort by date ascending
        const sorted = [...group].sort((a, b) => a.date.localeCompare(b.date));

        // Compute intervals
        const intervals: Array<number> = [];
        for (let i = 1; i < sorted.length; i++) {
            const prev = sorted[i - 1];
            const curr = sorted[i];
            if (prev && curr) {
                intervals.push(daysBetween(prev.date, curr.date));
            }
        }

        if (intervals.length === 0) continue;

        const medianInterval = median(intervals);
        const frequency = classifyFrequency(medianInterval);
        if (!frequency) continue; // No recognizable pattern

        const amounts = sorted.map(t => t.totalAmount);
        const confidence = computeConfidence(intervals, amounts, sorted.length);

        if (confidence < minConfidence) continue;

        const mostRecent = sorted[sorted.length - 1];
        if (!mostRecent) continue;

        results.push({
            payee: mostRecent.payee,
            accountId: mostRecent.accountId,
            suggestedFrequency: frequency,
            suggestedAmount: median(amounts),
            confidence,
            mostRecentTransaction: mostRecent,
            mostRecentSplits: mostRecent.splits ?? [],
            sampleDates: sorted.slice(-5).map(t => t.date)
        });
    }

    // Sort by confidence descending
    return results.sort((a, b) => b.confidence - a.confidence);
}

import { QIFParser } from '../../parsers/QIFParser';
import { computeSHA256 } from '../crypto/payload-cipher';
import type {
    ICorruptedAccountReport,
    ICorruptionReport,
    IExportMetadata
} from '../types/export-import.types';

export interface IDownloadedFilePackage {
    filename: string;
    encryptedContent: string;
    decryptedContent?: string;
}

/**
 * CorruptionDetector evaluates downloaded export package files for binary checksum mismatches,
 * QIF syntax errors, and split math discrepancies. Calculates penny-perfect reconciliation deltas.
 */
export const CorruptionDetector = {
    /**
     * Inspects export files against metadata and validates binary & parse integrity.
     */
    verifyExportIntegrity: async (
        metadata: IExportMetadata,
        files: Array<IDownloadedFilePackage>
    ): Promise<ICorruptionReport> => {
        const invalidChecksumFiles: Array<string> = [];
        const corruptedAccounts: Array<ICorruptedAccountReport> = [];

        const fileMap = new Map<string, IDownloadedFilePackage>();
        for (const file of files) {
            fileMap.set(file.filename, file);
        }

        // 1. Verify Ancillary Payload Checksum
        if (metadata.ancillaryFile) {
            const ancFile = fileMap.get(metadata.ancillaryFile.filename);
            if (!ancFile) {
                invalidChecksumFiles.push(metadata.ancillaryFile.filename);
            } else {
                const computedHash = await computeSHA256(ancFile.encryptedContent);
                if (computedHash.toLowerCase() !== metadata.ancillaryFile.sha256.toLowerCase()) {
                    invalidChecksumFiles.push(metadata.ancillaryFile.filename);
                }
            }
        }

        // 2. Verify Accounts Checksums & QIF Parse Integrity
        const parser = new QIFParser();

        for (const accMeta of metadata.accounts || []) {
            const qifFile = fileMap.get(accMeta.snakeCaseFilename);
            if (!qifFile) {
                invalidChecksumFiles.push(accMeta.snakeCaseFilename);
                corruptedAccounts.push({
                    accountId: accMeta.id,
                    accountName: accMeta.name,
                    filename: accMeta.snakeCaseFilename,
                    expectedBalanceCents: accMeta.balanceCents,
                    validTransactionsSumCents: 0,
                    discrepancyCents: accMeta.balanceCents,
                    corruptedTransactions: [
                        { reason: `File missing from export package: ${accMeta.snakeCaseFilename}` }
                    ]
                });
                continue;
            }

            // Verify Binary SHA-256 Checksum
            const computedHash = await computeSHA256(qifFile.encryptedContent);
            const checksumMatches = computedHash.toLowerCase() === accMeta.sha256.toLowerCase();
            if (!checksumMatches) {
                invalidChecksumFiles.push(accMeta.snakeCaseFilename);
            }

            // Verify Decrypted QIF Parse & Split Math
            if (qifFile.decryptedContent) {
                const parseResult = parser.parse(qifFile.decryptedContent);
                let validSumCents = 0;
                const corruptedTxs: Array<{ reason: string; lineNumber?: number }> = [];

                if (parseResult.errors.length > 0) {
                    for (const err of parseResult.errors) {
                        const corruptedItem: { reason: string; lineNumber?: number } = {
                            reason: err.message
                        };
                        if (err.line !== undefined) {
                            corruptedItem.lineNumber = err.line;
                        }
                        corruptedTxs.push(corruptedItem);
                    }
                }

                for (const tx of parseResult.transactions) {
                    validSumCents += tx.amount;
                }

                const discrepancyCents = accMeta.balanceCents - validSumCents;

                if (!checksumMatches || parseResult.errors.length > 0 || discrepancyCents !== 0) {
                    corruptedAccounts.push({
                        accountId: accMeta.id,
                        accountName: accMeta.name,
                        filename: accMeta.snakeCaseFilename,
                        expectedBalanceCents: accMeta.balanceCents,
                        validTransactionsSumCents: validSumCents,
                        discrepancyCents,
                        corruptedTransactions: corruptedTxs
                    });
                }
            }
        }

        const hasCorruption = invalidChecksumFiles.length > 0 || corruptedAccounts.length > 0;

        return {
            hasCorruption,
            invalidChecksumFiles,
            corruptedAccounts
        };
    }
};

import { environment } from '../../../environments/environment';
import { GDriveAuthError, notifyAuthFailure } from './errors';

const DRIVE_API_BASE: string = 'https://www.googleapis.com/drive/v3';
const UPLOAD_API_BASE: string = 'https://www.googleapis.com/upload/drive/v3';

/**
 * Get the environment-specific suffix for filenames
 */
function getEnvSuffix(): string {
    if (environment.appEnv === 'production') return '';
    return `-${environment.appEnv}`;
}

const DB_FILENAME: string = `path-logic-ledger${getEnvSuffix()}.db.enc`;
const LOCK_FILENAME: string = `sync-lock${getEnvSuffix()}.json`;

/**
 * Helper to handle GDrive API response errors
 */
async function handleResponseError(response: Response, defaultMessage: string): Promise<never> {
    let errorMessage = `${defaultMessage}: ${response.status} ${response.statusText}`;
    try {
        const errorData = await response.json();
        errorMessage += ` - ${JSON.stringify(errorData)}`;
    } catch {
        // Ignore parse error
    }

    if (response.status === 401 || response.status === 403) {
        notifyAuthFailure(response.status);
        throw new GDriveAuthError(errorMessage, response.status);
    }
    throw new Error(errorMessage);
}

export interface ILockStatus {
    clientId: string;
    deviceName: string;
    issuedAt: string;
    expiresAt: string;
    status: 'merging';
}

export interface IDriveFile {
    id: string;
    name: string;
    modifiedTime: string;
}

/** Timeout for all Drive API requests. Prevents indefinite hangs on stale tokens. */
const DRIVE_REQUEST_TIMEOUT_MS = 10_000;

/**
 * Fetch wrapper for all Google Drive API calls.
 * Applies a hard timeout via AbortController so stale/expired tokens
 * or network issues fail fast instead of hanging the UI indefinitely.
 */
async function driveApiFetch(url: string, init: RequestInit = {}): Promise<Response> {
    const controller = new AbortController();
    const timerId = setTimeout(() => controller.abort(), DRIVE_REQUEST_TIMEOUT_MS);
    try {
        return await fetch(url, { ...init, signal: controller.signal });
    } catch (err: unknown) {
        if (err instanceof DOMException && err.name === 'AbortError') {
            throw new Error(
                `Drive API request timed out after ${DRIVE_REQUEST_TIMEOUT_MS}ms: ${url}`
            );
        }
        throw err;
    } finally {
        clearTimeout(timerId);
    }
}

/**
 * Find the encrypted database file in appDataFolder
 */
export async function findDatabaseFile(accessToken: string): Promise<IDriveFile | null> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${DB_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list files');
    }

    const data: { files: Array<IDriveFile> } = (await response.json()) as {
        files: Array<IDriveFile>;
    };
    const files = data.files;
    return files && files.length > 0 ? (files[0] ?? null) : null;
}

/**
 * Delete both database and lock files from Drive (Factory Reset)
 */
export async function factoryResetDrive(accessToken: string): Promise<void> {
    const filesResponse = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=(name='${DB_FILENAME}' or name='${LOCK_FILENAME}')`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!filesResponse.ok) {
        await handleResponseError(filesResponse, 'Failed to list files for reset');
    }

    const { files } = (await filesResponse.json()) as { files: Array<IDriveFile> };

    for (const file of files) {
        const deleteResponse = await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
            method: 'DELETE',
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        });

        if (!deleteResponse.ok && deleteResponse.status !== 404) {
            await handleResponseError(deleteResponse, `Failed to delete file: ${file.name}`);
        }
    }
}

/**
 * Download the encrypted database from Drive
 */
export async function downloadDatabase(accessToken: string, fileId: string): Promise<Uint8Array> {
    const response: Response = await driveApiFetch(`${DRIVE_API_BASE}/files/${fileId}?alt=media`, {
        headers: {
            Authorization: `Bearer ${accessToken}`
        }
    });

    if (!response.ok) {
        await handleResponseError(response, 'Failed to download file');
    }

    const arrayBuffer: ArrayBuffer = await response.arrayBuffer();
    return new Uint8Array(arrayBuffer);
}

/**
 * Upload encrypted database to Drive (create or update)
 */
export async function uploadDatabase(
    accessToken: string,
    encryptedData: Uint8Array,
    existingFileId?: string
): Promise<string> {
    const metadata: { name: string; parents?: Array<string> } = {
        name: DB_FILENAME
    };

    if (!existingFileId) {
        metadata.parents = new Array<string>('appDataFolder');
    }

    const form: FormData = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([encryptedData as BlobPart]), DB_FILENAME);

    const url: string = existingFileId
        ? `${UPLOAD_API_BASE}/files/${existingFileId}?uploadType=multipart`
        : `${UPLOAD_API_BASE}/files?uploadType=multipart`;

    const method: string = existingFileId ? 'PATCH' : 'POST';

    const response: Response = await driveApiFetch(url, {
        method,
        headers: {
            Authorization: `Bearer ${accessToken}`
        },
        body: form
    });

    if (!response.ok) {
        await handleResponseError(response, 'Failed to upload file');
    }

    const result: { id: string } = (await response.json()) as { id: string };
    return result.id;
}

/**
 * Get current lock status from Drive
 */
export async function getLockStatus(accessToken: string): Promise<ILockStatus | null> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'&fields=files(id,name,modifiedTime)`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list lock files');
    }

    const data: { files: Array<{ id: string }> } = (await response.json()) as {
        files: Array<{ id: string }>;
    };
    if (data.files.length === 0) return null;

    const firstFile = data.files[0];
    if (!firstFile) return null;

    const fileId: string = firstFile.id;
    const fileResponse: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files/${fileId}?alt=media`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!fileResponse.ok) {
        await handleResponseError(fileResponse, 'Failed to download lock');
    }

    try {
        return (await fileResponse.json()) as ILockStatus;
    } catch {
        return null;
    }
}

/**
 * Acquire a sync lock on Drive
 */
export async function acquireLock(
    accessToken: string,
    clientId: string,
    deviceName: string
): Promise<boolean> {
    // 1. Check for existing lock
    const existingLock = await getLockStatus(accessToken);
    if (existingLock) {
        const now = new Date();
        const expiresAt = new Date(existingLock.expiresAt);

        // If lock is held by someone else and hasn't expired, we can't acquire it
        if (existingLock.clientId !== clientId && now < expiresAt) {
            return false;
        }
    }

    // 2. Upload new lock
    const now = new Date();
    const expiresAt = new Date(now.getTime() + 5 * 60 * 1000); // 5 minute TTL

    const lockStatus: ILockStatus = {
        clientId,
        deviceName,
        issuedAt: now.toISOString(),
        expiresAt: expiresAt.toISOString(),
        status: 'merging'
    };

    const metadata = {
        name: LOCK_FILENAME,
        parents: ['appDataFolder']
    };

    const searchResponse: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!searchResponse.ok) {
        await handleResponseError(searchResponse, 'Failed to search for locks');
    }

    const searchData: { files?: Array<{ id: string }> } = await searchResponse.json();
    if (searchData.files && Array.isArray(searchData.files)) {
        for (const file of searchData.files) {
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: { Authorization: `Bearer ${accessToken}` }
            });
        }
    }

    const form: FormData = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([JSON.stringify(lockStatus)], { type: 'application/json' }));

    const response: Response = await driveApiFetch(
        `${UPLOAD_API_BASE}/files?uploadType=multipart`,
        {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${accessToken}`
            },
            body: form
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to create lock');
    }

    // 3. Concurrency Check: Wait 500ms and re-verify we are the holder
    await new Promise(resolve => setTimeout(resolve, 500));
    const verifiedLock = await getLockStatus(accessToken);

    return verifiedLock?.clientId === clientId;
}

/**
 * Release a sync lock on Drive
 */
export async function releaseLock(accessToken: string): Promise<void> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list locks for release');
    }

    const data: { files?: Array<{ id: string }> } = await response.json();

    if (data.files && Array.isArray(data.files)) {
        for (const file of data.files) {
            // We could verify clientId here, but usually, if you're releasing, you know what you're doing.
            // For safety, let's just delete the file.
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: {
                    Authorization: `Bearer ${accessToken}`
                }
            });
        }
    }
}

/**
 * Forcibly release a lock (manual override)
 */
export async function forceReleaseLock(accessToken: string): Promise<void> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list locks for force release');
    }

    const data: { files?: Array<{ id: string }> } = await response.json();

    if (data.files && Array.isArray(data.files)) {
        for (const file of data.files) {
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: {
                    Authorization: `Bearer ${accessToken}`
                }
            });
        }
    }
}

