export interface IConsolidatedOutputPackage {
    targetFolderName: string;
    metadata: Partial<IExportMetadata>;
    accounts: Array<{
        account: IAccount;
        transactions: Array<ITransaction>;
    }>;
    ancillaryPayload: IAncillaryPayload;
    mergedAccountCount: number;
    mergedTransactionCount: number;
    sourceFoldersCombined: Array<string>;
}

/**
 * ExportConsolidator diffs and merges multiple exports created on the same day into a unified export package.
 * Latest export timestamp is assumed authoritative while non-duplicate historical records are preserved.
 */
export const ExportConsolidator = {
    /**
     * Consolidates multiple same-day export package contents into a single unified output package.
     */
    consolidateSameDayExports: (
        packages: Array<IExportPackageContent>,
        targetFolderName: string
    ): IConsolidatedOutputPackage => {
        if (!packages || packages.length === 0) {
            throw new Error('Cannot consolidate empty export package list');
        }

        // Sort chronologically by createdAt (oldest first, so newest overwrites in merge)
        const sortedPackages = [...packages].sort(
            (a, b) =>
                new Date(a.metadata.createdAt).getTime() - new Date(b.metadata.createdAt).getTime()
        );

        const mergedAccountMap = new Map<string, IAccount>();
        const accountTxHashMap = new Map<string, Map<string, ITransaction>>();

        const categoryMap = new Map<string, ICategory>();
        const payeeMap = new Map<string, IPayee>();
        const scheduleMap = new Map<string, IRecurringSchedule>();
        let mergedFeatureFlags: Record<string, boolean> = {};
        let mergedUserSettings: Record<string, unknown> = {};

        for (const pkg of sortedPackages) {
            // Merge Ancillary Settings
            for (const cat of pkg.ancillaryPayload.categories || []) {
                categoryMap.set(cat.id, { ...cat });
            }
            for (const payee of pkg.ancillaryPayload.payees || []) {
                payeeMap.set(payee.id, { ...payee });
            }
            for (const sched of pkg.ancillaryPayload.recurringSchedules || []) {
                scheduleMap.set(sched.id, { ...sched });
            }
            mergedFeatureFlags = { ...mergedFeatureFlags, ...pkg.ancillaryPayload.featureFlags };
            mergedUserSettings = { ...mergedUserSettings, ...pkg.ancillaryPayload.userSettings };

            // Merge Accounts & Transactions
            for (const accObj of pkg.accounts) {
                const acc = accObj.account;
                mergedAccountMap.set(acc.id, { ...acc });

                if (!accountTxHashMap.has(acc.id)) {
                    accountTxHashMap.set(acc.id, new Map<string, ITransaction>());
                }

                let txMap = accountTxHashMap.get(acc.id);
                if (!txMap) {
                    txMap = new Map<string, ITransaction>();
                    accountTxHashMap.set(acc.id, txMap);
                }
                for (const tx of accObj.transactions) {
                    const hash = generateImportHash(tx.date, tx.totalAmount, tx.payee);
                    // Store transaction indexed by deterministic hash (newest overwrites)
                    txMap.set(hash, { ...tx });
                }
            }
        }

        const consolidatedAccounts: Array<{
            account: IAccount;
            transactions: Array<ITransaction>;
        }> = [];
        let totalTxCount = 0;

        for (const [accId, account] of mergedAccountMap.entries()) {
            const txMap = accountTxHashMap.get(accId);
            const txList = txMap ? Array.from(txMap.values()) : [];
            // Sort transactions by date
            txList.sort((a, b) => a.date.localeCompare(b.date));

            totalTxCount += txList.length;
            consolidatedAccounts.push({
                account,
                transactions: txList
            });
        }

        const consolidatedAncillary: IAncillaryPayload = {
            categories: Array.from(categoryMap.values()),
            payees: Array.from(payeeMap.values()),
            recurringSchedules: Array.from(scheduleMap.values()),
            featureFlags: mergedFeatureFlags,
            userSettings: mergedUserSettings
        };

        const latestPkg = sortedPackages[sortedPackages.length - 1];

        return {
            targetFolderName,
            metadata: {
                exportId: `consolidated-${Date.now()}`,
                createdAt: new Date().toISOString(),
                appVersion: latestPkg?.metadata.appVersion || '0.1.0',
                coreVersion: latestPkg?.metadata.coreVersion || '0.1.0'
            },
            accounts: consolidatedAccounts,
            ancillaryPayload: consolidatedAncillary,
            mergedAccountCount: consolidatedAccounts.length,
            mergedTransactionCount: totalTxCount,
            sourceFoldersCombined: sortedPackages.map(p => p.folderName)
        };
    }
};

import type {
    IAccount,
    ICategory,
    IPayee,
    IRecurringSchedule,
    ITransaction
} from '../../domain/types';
import { QIFExporter } from '../../parsers/QIFExporter';
import { computeSHA256, decryptPayload, encryptPayload } from '../crypto/payload-cipher';
import { AncillarySerializer } from '../serializers/AncillarySerializer';
import type {
    IAncillaryPayload,
    IExportAccountMetadata,
    IExportMetadata
} from '../types/export-import.types';

export interface IExportRawPackage {
    metadata: IExportMetadata;
    files: Array<{
        filename: string;
        encryptedContent: string;
        mimeType: string;
    }>;
}

/**
 * Pure core helper function for generating a complete encrypted export package.
 */
export async function createExportPackage(
    accounts: Array<{ account: IAccount; transactions: Array<ITransaction> }>,
    ancillaryData: {
        categories: Array<ICategory>;
        payees: Array<IPayee>;
        recurringSchedules: Array<IRecurringSchedule>;
        featureFlags: Record<string, boolean>;
        userSettings: Record<string, unknown>;
    },
    passphrase: string,
    appVersion: string = '0.1.0'
): Promise<IExportRawPackage> {
    const exportId = `export-${Date.now()}`;
    const createdAt = new Date().toISOString();
    const files: Array<{ filename: string; encryptedContent: string; mimeType: string }> = [];
    const accountMetas: Array<IExportAccountMetadata> = [];

    let combinedHashes = '';

    // 1. Process Ledgers to QIF + Encrypt
    for (const item of accounts) {
        const snakeName = toSnakeCase(item.account.name);
        const qifFilename = `${snakeName}.qif.enc`;
        const qifText = QIFExporter.exportAccount(item.account, item.transactions);

        const encryptedQif = await encryptPayload(qifText, passphrase);
        const sha256 = await computeSHA256(encryptedQif);
        combinedHashes += sha256;

        files.push({
            filename: qifFilename,
            encryptedContent: encryptedQif,
            mimeType: 'text/plain'
        });

        const totalBalance = item.transactions.reduce((acc, tx) => acc + tx.totalAmount, 0);

        accountMetas.push({
            id: item.account.id,
            name: item.account.name,
            type: item.account.type,
            snakeCaseFilename: qifFilename,
            transactionCount: item.transactions.length,
            balanceCents: totalBalance,
            sha256
        });
    }

    // 2. Process Ancillary Settings (Sanitized & Encrypted)
    const ancillaryText = AncillarySerializer.serialize({
        categories: ancillaryData.categories,
        payees: ancillaryData.payees,
        recurringSchedules: ancillaryData.recurringSchedules,
        featureFlags: ancillaryData.featureFlags,
        userSettings: ancillaryData.userSettings
    });

    const encryptedAncillary = await encryptPayload(ancillaryText, passphrase);
    const ancillarySha256 = await computeSHA256(encryptedAncillary);
    combinedHashes += ancillarySha256;

    const ancillaryFilename = 'ancillary_settings.enc';
    files.push({
        filename: ancillaryFilename,
        encryptedContent: encryptedAncillary,
        mimeType: 'text/plain'
    });

    // 3. Generate Overall Metadata
    const overallChecksum = await computeSHA256(combinedHashes);

    const metadata: IExportMetadata = {
        exportId,
        createdAt,
        appVersion,
        coreVersion: '0.1.0',
        accounts: accountMetas,
        ancillaryFile: {
            filename: ancillaryFilename,
            sha256: ancillarySha256,
            algorithm: 'AES-GCM-256'
        },
        overallChecksum
    };

    files.push({
        filename: 'export_metadata.json',
        encryptedContent: JSON.stringify(metadata, null, 2),
        mimeType: 'application/json'
    });

    return { metadata, files };
}

/**
 * Decrypts ancillary settings file from an export package.
 */
export async function decryptAncillarySettings(
    encryptedBase64: string,
    passphrase: string
): Promise<IAncillaryPayload> {
    const plainText = await decryptPayload(encryptedBase64, passphrase);
    return AncillarySerializer.deserialize(plainText);
}

/**
 * Formats account name into snake_case string
 */
export function toSnakeCase(name: string): string {
    return name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
}

import type { Signal, WritableSignal } from '@angular/core';
import { computed, Injectable, signal } from '@angular/core';

/**
 * Cookie prefix for feature flags.
 * Must match the prefix used by the legacy @feature-flags package.
 */
const COOKIE_PREFIX: string = 'ff_';

/**
 * Custom event name for feature flag changes
 * (fallback for browsers without CookieStore API)
 */
const FLAG_CHANGE_EVENT: string = 'featureFlagChange';

/**
 * Event detail interface for flag changes
 */
interface IFlagChangeDetail {
    flag: string;
    enabled: boolean;
}

/**
 * Check if CookieStore API is available
 */
function hasCookieStoreAPI(): boolean {
    return typeof window !== 'undefined' && 'cookieStore' in window;
}

/**
 * Set a cookie with the given name and value
 */
function setCookie(name: string, value: string, days: number = 365): void {
    const expires: Date = new Date();
    expires.setTime(expires.getTime() + days * 24 * 60 * 60 * 1000);
    document.cookie = `${name}=${value};expires=${expires.toUTCString()};path=/;SameSite=Lax`;
}

/**
 * Delete a cookie by setting its expiration to the past
 */
function deleteCookie(name: string): void {
    document.cookie = `${name}=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/;SameSite=Lax`;
}

/**
 * Angular signal-based feature flag service.
 *
 * Replaces the React hooks (`useFeatureFlag`, `useAllFlags`) from
 * `@feature-flags/client` with Angular signals.
 *
 * Cookie persistence uses the same `ff_` prefix for backward compatibility.
 * Listens for cookie changes via CookieStore API (Chrome) or custom events (fallback).
 *
 * @example
 * ```typescript
 * // In a component
 * readonly featureFlags = inject(FeatureFlagService);
 * readonly devEnabled = this.featureFlags.isEnabled('dev');
 *
 * // In template
 * @if (devEnabled()) {
 *   <dev-tools />
 * }
 * ```
 */
@Injectable({ providedIn: 'root' })
export class FeatureFlagService {
    /** Internal writable flags map */
    private readonly _flags: WritableSignal<Record<string, boolean>> = signal<
        Record<string, boolean>
    >({});

    /** Read-only flags map (all flags and their current states) */
    readonly flags: Signal<Record<string, boolean>> = this._flags.asReadonly();

    constructor() {
        // Sync from cookies on init
        this.syncFromCookies();

        // Listen for cookie/flag changes
        this.setupChangeListeners();
    }

    /**
     * Get a computed signal for whether a specific flag is enabled.
     * Returns a cached computed signal (same reference on repeated calls).
     */
    isEnabled(flag: string): Signal<boolean> {
        return computed((): boolean => !!this._flags()[flag]);
    }

    /**
     * Toggle a feature flag on or off.
     * Updates both the cookie and the internal signal state.
     */
    toggle(flag: string, enabled: boolean): void {
        const cookieName: string = `${COOKIE_PREFIX}${flag}`;

        if (enabled) {
            setCookie(cookieName, 'true');
        } else {
            deleteCookie(cookieName);
        }

        // Update internal state
        this._flags.update(
            (current: Record<string, boolean>): Record<string, boolean> => ({
                ...current,
                [flag]: enabled
            })
        );

        // Emit custom event for cross-component sync (fallback for non-CookieStore browsers)
        if (!hasCookieStoreAPI()) {
            const event: CustomEvent<IFlagChangeDetail> = new CustomEvent<IFlagChangeDetail>(
                FLAG_CHANGE_EVENT,
                {
                    detail: { flag, enabled }
                }
            );
            window.dispatchEvent(event);
        }
    }

    /**
     * Read all `ff_*` cookies and populate the internal signal state.
     */
    private syncFromCookies(): void {
        if (typeof document === 'undefined') return;

        const allFlags: Record<string, boolean> = {};
        const cookies: Array<string> = document.cookie.split(';');

        for (const cookie of cookies) {
            const trimmedCookie: string = cookie.trim();
            const [name, value]: Array<string> = trimmedCookie.split('=');
            if (name?.startsWith(COOKIE_PREFIX)) {
                const flagName: string = name.substring(COOKIE_PREFIX.length);
                allFlags[flagName] = value === 'true';
            }
        }

        this._flags.set(allFlags);
    }

    /**
     * Set up listeners for cookie changes (CookieStore API or custom events).
     */
    private setupChangeListeners(): void {
        if (typeof window === 'undefined') return;

        if (hasCookieStoreAPI()) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (window as any).cookieStore.addEventListener('change', (event: any): void => {
                this._flags.update((current: Record<string, boolean>): Record<string, boolean> => {
                    const updated: Record<string, boolean> = { ...current };

                    for (const cookie of event.changed ?? []) {
                        if (cookie.name?.startsWith(COOKIE_PREFIX)) {
                            const flagName: string = cookie.name.substring(COOKIE_PREFIX.length);
                            updated[flagName] = cookie.value === 'true';
                        }
                    }

                    for (const cookie of event.deleted ?? []) {
                        if (cookie.name?.startsWith(COOKIE_PREFIX)) {
                            const flagName: string = cookie.name.substring(COOKIE_PREFIX.length);
                            updated[flagName] = false;
                        }
                    }

                    return updated;
                });
            });
        } else {
            window.addEventListener(FLAG_CHANGE_EVENT, (event: Event): void => {
                const customEvent: CustomEvent<IFlagChangeDetail> =
                    event as CustomEvent<IFlagChangeDetail>;
                this._flags.update(
                    (current: Record<string, boolean>): Record<string, boolean> => ({
                        ...current,
                        [customEvent.detail.flag]: customEvent.detail.enabled
                    })
                );
            });
        }
    }
}

