    private static mapAccount(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            name: row[1] as string,
            type: row[2] as string,
            institutionName: row[3] as string,
            isActive: row[4] as number,
            deletedAt: row[5] as string,
            isDeleted: row[6] as number,
            clientId: row[7] as string,
            createdAt: row[8] as string,
            updatedAt: row[9] as string
        };
    }

    private static mapPayee(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            name: row[1] as string,
            address: row[2] as string,
            city: row[3] as string,
            state: row[4] as string,
            zipCode: row[5] as string,
            latitude: row[6] as number,
            longitude: row[7] as number,
            website: row[8] as string,
            phone: row[9] as string,
            notes: row[10] as string,
            defaultCategoryId: row[11] as string,
            isDeleted: row[12] as number,
            clientId: row[13] as string,
            createdAt: row[14] as string,
            updatedAt: row[15] as string
        };
    }

    private static mapCategory(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            parentId: row[1] as string,
            name: row[2] as string,
            description: row[3] as string,
            isActive: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            createdAt: row[7] as string,
            updatedAt: row[8] as string
        };
    }

    private static mapSchedule(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            accountId: row[1] as string,
            payee: row[2] as string,
            totalAmount: row[3] as number,
            type: row[4] as string,
            frequency: row[5] as string,
            paymentMethod: row[6] as string,
            startDate: row[7] as string,
            endDate: row[8] as string,
            nextDueDate: row[9] as string,
            lastOccurredDate: row[10] as string,
            memo: row[11] as string,
            autoPost: row[12] as number,
            isActive: row[13] as number,
            isDeleted: row[14] as number,
            clientId: row[15] as string,
            createdAt: row[16] as string,
            updatedAt: row[17] as string
        };
    }

    private static mapRecurringSplit(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            scheduleId: row[1] as string,
            categoryId: row[2] as string,
            memo: row[3] as string,
            amount: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            updatedAt: row[7] as string
        };
    }

    // ── DB write helpers ──────────────────────────────────────────────────────

    private static insertItem(db: Database, table: string, item: IMergeable): void {
        const itemObj = item as unknown as Record<string, unknown>;
        const columns = Object.keys(itemObj).filter(k => typeof itemObj[k] !== 'undefined');
        const placeholders = columns.map(() => '?').join(', ');
        const values = columns.map(c => itemObj[c]) as Array<SqlValue>;
        db.run(`INSERT INTO ${table} (${columns.join(', ')}) VALUES(${placeholders})`, values);
    }

    private static updateItem(db: Database, table: string, item: IMergeable): void {
        const itemObj = item as unknown as Record<string, unknown>;
        const columns = Object.keys(itemObj).filter(
            k => k !== 'id' && typeof itemObj[k] !== 'undefined'
        );
        const setClause = columns.map(c => `${c} = ?`).join(', ');
        const values = columns.map(c => itemObj[c]) as Array<SqlValue>;
        values.push(item['id'] as SqlValue);
        db.run(`UPDATE ${table} SET ${setClause} WHERE id = ? `, values);
    }
}

import { Injectable, inject, signal } from '@angular/core';
import { Money } from '@core';
import { GeminiService } from '../gemini/gemini.service';
import { LedgerStore } from '../ledger-store/ledger.store';

export interface IMessage {
    sender: 'user' | 'assistant';
    text: string;
    timestamp: Date;
}

@Injectable({ providedIn: 'root' })
export class AiAssistantService {
    private readonly geminiService = inject(GeminiService);
    private readonly ledgerStore = inject(LedgerStore);

    readonly isOpen = signal<boolean>(false);
    readonly messages = signal<Array<IMessage>>([
        {
            sender: 'assistant',
            text: 'Hello! I am your Path Logic financial assistant. I have access to your accounts, transactions, and scheduled bills. How can I help you optimize your finances today?',
            timestamp: new Date()
        }
    ]);
    readonly isSending = signal<boolean>(false);

    toggle(): void {
        this.isOpen.update(open => !open);
    }

    open(): void {
        this.isOpen.set(true);
    }

    close(): void {
        this.isOpen.set(false);
    }

    clearChat(): void {
        this.messages.set([
            {
                sender: 'assistant',
                text: 'Hello! I am your Path Logic financial assistant. I have access to your accounts, transactions, and scheduled bills. How can I help you optimize your finances today?',
                timestamp: new Date()
            }
        ]);
    }

    async sendMessage(userText: string): Promise<void> {
        if (!userText.trim() || this.isSending()) return;

        // Add user message
        this.messages.update(msgs => [
            ...msgs,
            { sender: 'user', text: userText, timestamp: new Date() }
        ]);

        this.isSending.set(true);

        try {
            // Build Context
            const context = this.buildFinancialContext();
            const conversationHistory = this.messages()
                .slice(-10) // Limit history to last 10 messages
                .map(m => `${m.sender === 'user' ? 'User' : 'Assistant'}: ${m.text}`)
                .join('\n');

            const systemPrompt = `
You are a premium AI financial assistant embedded inside Path Logic, a local-first accounting application.
You are professional, analytical, concise, and helpful. You speak to the user about their exact financial data.

Client Financial Context:
=========================
${context}

Recent Chat History:
====================
${conversationHistory}

User Query:
===========
${userText}

Instruction:
Provide a concise, highly analytical, and direct response. Use markdown formatting (such as bullet points, bold text, or inline tables) where helpful. Always format dollar amounts using standard currency formatting. Keep the response to 2-3 short paragraphs maximum.
`;

            const reply = await this.geminiService.generateContent(systemPrompt);
            this.messages.update(msgs => [
                ...msgs,
                { sender: 'assistant', text: reply.trim(), timestamp: new Date() }
            ]);
        } catch (err: unknown) {
            console.error('Failed to get Gemini response:', err);
            const errMsg = err instanceof Error ? err.message : 'Unknown error';
            this.messages.update(msgs => [
                ...msgs,
                {
                    sender: 'assistant',
                    text: `Sorry, I encountered an error communicating with Gemini: ${errMsg}. Please ensure your API key in Settings is valid.`,
                    timestamp: new Date()
                }
            ]);
        } finally {
            this.isSending.set(false);
        }
    }

    private buildFinancialContext(): string {
        const accounts = this.ledgerStore.accounts();
        const transactions = this.ledgerStore.transactions();
        const schedules = this.ledgerStore.schedules();
        const categories = this.ledgerStore.categories();

        // 1. Summarize Accounts
        const accountSummary = accounts
            .map(
                a =>
                    `- ${a.name} (${a.type}): Cleared Bal: ${Money.formatCurrency(a.clearedBalance)}, Pending: ${Money.formatCurrency(a.pendingBalance)}`
            )
            .join('\n');

        // 2. Spending by Category (last 60 days)
        const sixtyDaysAgo = new Date();
        sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);
        const recentTxs = transactions.filter(t => new Date(t.date) >= sixtyDaysAgo);

        const categorySpends = new Map<string, number>();
        let totalExpenses = 0;
        let totalIncome = 0;

        for (const tx of recentTxs) {
            const isExpense = tx.totalAmount < 0;
            if (isExpense) {
                totalExpenses += Math.abs(tx.totalAmount);
            } else {
                totalIncome += tx.totalAmount;
            }

            for (const split of tx.splits) {
                if (split.categoryId) {
                    const catName =
                        categories.find(c => c.id === split.categoryId)?.name ?? 'Unknown';
                    const amount = split.amount;
                    categorySpends.set(catName, (categorySpends.get(catName) || 0) + amount);
                }
            }
        }

        const categorySummary = Array.from(categorySpends.entries())
            .sort((a, b) => a[1] - b[1]) // Sort expenses (most negative first)
            .slice(0, 8) // Top 8 categories
            .map(([name, amount]) => `- ${name}: ${Money.formatCurrency(amount)}`)
            .join('\n');

        // 3. Upcoming recurring bills / schedules
        const scheduleSummary = schedules
            .filter(s => s.isActive)
            .map(
                s =>
                    `- ${s.payee} (${s.frequency}): ${Money.formatCurrency(s.amount)} due on ${s.nextDueDate}`
            )
            .join('\n');

        return `
Accounts & Balances:
${accountSummary || 'No accounts configured.'}

Totals over the last 60 days:
- Total Expenses: ${Money.formatCurrency(totalExpenses)}
- Total Income: ${Money.formatCurrency(totalIncome)}

Top Spending Categories (Last 60 Days):
${categorySummary || 'No categorizations recorded.'}

Active Recurring Bills & Schedules:
${scheduleSummary || 'No scheduled bills configured.'}
`;
    }
}

export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
    address: string | null;
    /** City location. */
    city: string | null;
    /** State/Province. */
    state: string | null;
    /** Postal/Zip code. */
    zipCode: string | null;
    /** Coordinate for map visualization. */
    latitude: number | null;
    /** Coordinate for map visualization. */
    longitude: number | null;
    /** Official website or portal. */
    website: string | null;
    /** Contact phone number. */
    phone: string | null;
    /** Arbitrary notes about this payee. */
    notes: string | null;
    /** Default category ID suggested for new transactions. */
    defaultCategoryId: EntityId | null;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * A category for organizing transactions (e.g., "Groceries", "Rent").
 * Supports a hierarchical tree structure.
 */
export interface ICategory {
    /** Unique ID for the category. */
    id: EntityId;
    /** ID of the parent category (null if top-level). */
    parentId: EntityId | null;
    /** Name of the category (e.g., "Dining Out"). */
    name: string;
    /** Optional detailed description. */
    description: string | null;
    /** Whether the category is currently available for selection. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * An account containing a collection of transactions.
 */
export interface IAccount {
    /** Unique ID for the account. */
    id: EntityId;
    /** Human-readable name (e.g., "Main Checking"). */
    name: string;
    /** Type of account (e.g., checking, savings). */
    type: AccountType;
    /** Financial institution name. */
    institutionName: string;
    /** Sum of all Cleared/Reconciled transactions. */
    clearedBalance: Cents;
    /** Sum of all transactions (Cleared + Pending). */
    pendingBalance: Cents;
    /** Whether the account is currently in use. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
    /** Optional detailed information for loan accounts. */
    loanDetails?: ILoanDetails;
}

/**
 * Frequency interval for recurring scheduled items.
 */
export enum Frequency {
    Daily = 'daily',
    Weekly = 'weekly',
    Biweekly = 'biweekly',
    EveryFourWeeks = 'every_four_weeks',
    Monthly = 'monthly',
    TwiceAMonth = 'twice_a_month',
    Bimonthly = 'bimonthly',
    Quarterly = 'quarterly',
    Yearly = 'yearly'
}

/**
 * Payment methods for scheduled transactions.
 */
export enum PaymentMethod {
    DirectDebit = 'direct_debit',
    DirectDeposit = 'direct_deposit',
    WriteCheck = 'write_check',
    ElectronicTransfer = 'electronic_transfer',
    Other = 'other'
}

/**
 * A template for generating recurring transactions.
 */
export interface IRecurringSchedule {
    /** Unique ID for the schedule. */
    id: EntityId;
    /** The account where generated transactions will be posted. */
    accountId: EntityId;
    /** Default payee for generated transactions. */
    payee: string;
    /** Total amount for the transaction (parent). */
    amount: Cents;
    /** The type of schedule (Debit, Deposit, Paycheck). */
    type: ScheduleType;
    /** How often the transaction repeats. */
    frequency: Frequency;
    /** How the payment is processed. */
    paymentMethod: PaymentMethod;
    /** Date when the schedule begins. */
    startDate: ISODateString;
    /** Optional date when the schedule ends. */
    endDate: ISODateString | null;
    /** Calculated date of the next occurrence. */
    nextDueDate: ISODateString;
    /** Date when the last transaction was posted from this schedule. */
    lastOccurredDate: ISODateString | null;
    /** Splits for the generated transaction. */
    splits: Array<ISplit>;
    /** Optional memo for the transaction. */
    memo: string;
    /** Whether to automatically post the transaction to the ledger on the due date. */
    autoPost: boolean;
    /** Whether the schedule is active and generating projections. */
    isActive: boolean;
}

/**
 * Result of parsing a single split from an external source (e.g. QIF).
 */
export interface IParsedSplit {
    category: string | null;
    amount: Cents;
    memo: string | null;
}

/**
 * Result of parsing a single transaction from an external source (e.g. QIF).
 */
export interface IParsedTransaction {
    date: ISODateString;
    amount: Cents;
    payee: string;
    memo: string;
    checkNumber: string | null;
    category: string | null;
    splits: Array<IParsedSplit>;
    importHash: string;
}

import { KnownCategory } from '../domain/CategoryDefaults';
import { ErrorCode } from '../domain/ErrorCode';
import type { Cents, EntityId, ISODateString, ISplit, ITransaction } from '../domain/types';
import { TransactionStatus } from '../domain/types';
import type { Result } from '../shared/Result';
import type { IValidationResult } from './invariants';
import { validateSplitSum } from './invariants';

export interface IPaycheckParams {
    id: EntityId;
    accountId: EntityId;
    payeeId: EntityId;
    date: ISODateString;
    memo?: string;
    grossPay: Cents;
    federalTax?: Cents;
    stateTax?: Cents;
    localTax?: Cents;
    socialSecurity?: Cents;
    medicare?: Cents;
    healthInsurance?: Cents;
    visionInsurance?: Cents;
    dentalInsurance?: Cents;
    fourOhOneK?: Cents;
    hsa?: Cents;
    otherDeductions?: Array<{ memo: string; amount: Cents; categoryId?: EntityId }>;
}

export interface IMortgageParams {
    id: EntityId;
    accountId: EntityId;
    payeeId: EntityId;
    date: ISODateString;
    memo?: string;
    totalAmount: Cents;
    principal: Cents;
    interest: Cents;
    escrow?: Cents;
    propertyTax?: Cents;
    pmi?: Cents;
    otherFees?: Array<{ memo: string; amount: Cents; categoryId?: EntityId }>;
}

/**
 * Interface definition for the core transaction engine.
 * Decoupled for testing and dependency injection.
 */
export interface ITransactionEngine {
    autoBalanceSplits(transaction: ITransaction): ITransaction;
    validateTransaction(transaction: ITransaction): Result<void>;
    createPaycheck(params: IPaycheckParams): ITransaction;
    createMortgagePayment(params: IMortgageParams): ITransaction;
}

/**
 * Concrete implementation of the Penny-Perfect Core Engine logic.
 */
export class TransactionEngine implements ITransactionEngine {
    /**
     * Automatically balances the splits of a transaction to match the totalAmount.
     * Strategy: Adds discrepancy to the last split or creates a new one.
     */
    public autoBalanceSplits(transaction: ITransaction): ITransaction {
        const currentSum: number = transaction.splits.reduce(
            (s: number, sp: ISplit) => s + sp.amount,
            0
        );
        const discrepancy: number = transaction.totalAmount - currentSum;

        if (discrepancy === 0) return transaction;

        const updatedSplits: Array<ISplit> = [...transaction.splits];

        if (updatedSplits.length === 0) {
            updatedSplits.push({
                id: `${transaction.id}-split-auto`,
                categoryId: null,
                memo: 'Auto-balanced discrepancy',
                amount: discrepancy
            } satisfies ISplit);
        } else {
            const lastIndex: number = updatedSplits.length - 1;
            const lastSplit: ISplit | undefined = updatedSplits[lastIndex];
            if (lastSplit) {
                updatedSplits[lastIndex] = {
                    ...lastSplit,
                    amount: lastSplit.amount + discrepancy
                } satisfies ISplit;
            }
        }

        return {
            ...transaction,
            splits: updatedSplits,
            updatedAt: new Date().toISOString()
        } satisfies ITransaction;
    }

    /**
     * Runs all domain-level validation rules for a transaction.
     */
    public validateTransaction(transaction: ITransaction): Result<void> {
        // 1. Validate split sum invariant
        const validation: IValidationResult = validateSplitSum(transaction);
        if (!validation.valid) {
            return {
                success: false,
                error: {
                    code: ErrorCode.SplitSumMismatch,
                    message: validation.error || 'Split sum mismatch',
                    details: { discrepancy: validation.discrepancy }
                }
            } satisfies Result<void>;
        }

        // 2. Validate status rules
        if (transaction.status === TransactionStatus.Reconciled) {
            // Reconciled transactions are immutable at this level
        }

        return { success: true, value: undefined } satisfies Result<void>;
    }

    /**
     * Helper to create a granular paycheck transaction.
     */
    public createPaycheck(params: IPaycheckParams): ITransaction {
        const splits: Array<ISplit> = [];
        let netAmount: number = params.grossPay;

        // Add Gross Pay split
        splits.push({
            id: `${params.id}-gross`,
            categoryId: KnownCategory.GrossPay,
            memo: 'Gross Pay',
            amount: params.grossPay
        });

        const addDeduction = (
            amount: Cents | undefined,
            categoryId: string,
            memo: string
        ): void => {
            if (amount && amount !== 0) {
                // Deductions are stored as negative amounts in splits
                const deductionAmount: number = amount > 0 ? -amount : amount;
                splits.push({
                    id: `${params.id}-${categoryId.replace('cat-', '')}`,
                    categoryId,
                    memo,
                    amount: deductionAmount
                });
                netAmount += deductionAmount;
            }
        };

        addDeduction(params.federalTax, KnownCategory.FederalTax, 'Federal Income Tax');
        addDeduction(params.stateTax, KnownCategory.StateTax, 'State Income Tax');
        addDeduction(params.localTax, KnownCategory.LocalTax, 'Local Income Tax');
        addDeduction(params.socialSecurity, KnownCategory.SocialSecurity, 'Social Security');
        addDeduction(params.medicare, KnownCategory.Medicare, 'Medicare');
        addDeduction(params.healthInsurance, KnownCategory.HealthInsurance, 'Health Insurance');
        addDeduction(params.visionInsurance, KnownCategory.VisionInsurance, 'Vision Insurance');
        addDeduction(params.dentalInsurance, KnownCategory.DentalInsurance, 'Dental Insurance');
        addDeduction(params.fourOhOneK, KnownCategory.FourOhOneK, '401(k) Contribution');
        addDeduction(params.hsa, KnownCategory.HSA, 'HSA Contribution');

        if (params.otherDeductions) {
            params.otherDeductions.forEach((d, i) => {
                const deductionAmount: number = d.amount > 0 ? -d.amount : d.amount;
                splits.push({
                    id: `${params.id}-other-${i}`,
                    categoryId: d.categoryId || KnownCategory.Uncategorized,
                    memo: d.memo,
                    amount: deductionAmount
                });
                netAmount += deductionAmount;
            });
        }

        const now: string = new Date().toISOString();
        return {
            id: params.id,
            accountId: params.accountId,
            payeeId: params.payeeId,
            date: params.date,
            payee: 'Paycheck', // Default payee name
            memo: params.memo || '',
            totalAmount: netAmount, // Total is the net amount deposited
            status: TransactionStatus.Pending,
            splits,
            checkNumber: null,
            importHash: '',
            createdAt: now,
            updatedAt: now
        } satisfies ITransaction;
    }

    /**
     * Helper to create a granular mortgage payment transaction.
     */
    public createMortgagePayment(params: IMortgageParams): ITransaction {
        const splits: Array<ISplit> = [];

        splits.push({
            id: `${params.id}-principal`,
            categoryId: KnownCategory.MortgagePrincipal,
            memo: 'Principal',
            amount: params.principal
        });

        splits.push({
            id: `${params.id}-interest`,
            categoryId: KnownCategory.MortgageInterest,
            memo: 'Interest',
            amount: params.interest
        });

        if (params.escrow) {
            splits.push({
                id: `${params.id}-escrow`,
                categoryId: KnownCategory.Escrow,
                memo: 'Escrow',
                amount: params.escrow
            });
        }

        if (params.propertyTax) {
            splits.push({
                id: `${params.id}-prop-tax`,
                categoryId: KnownCategory.PropertyTax,
                memo: 'Property Tax',
                amount: params.propertyTax
            });
        }

        if (params.pmi) {
            splits.push({
                id: `${params.id}-pmi`,
                categoryId: KnownCategory.MortgagePMI,
                memo: 'PMI',
                amount: params.pmi
            });
        }

        if (params.otherFees) {
            params.otherFees.forEach((f, i) => {
                splits.push({
                    id: `${params.id}-fee-${i}`,
                    categoryId: f.categoryId || KnownCategory.Uncategorized,
                    memo: f.memo,
                    amount: f.amount
                });
            });
        }

        const now: string = new Date().toISOString();
        return {
            id: params.id,
            accountId: params.accountId,
            payeeId: params.payeeId,
            date: params.date,
            payee: 'Mortgage',
            memo: params.memo || '',
            totalAmount: params.totalAmount,
            status: TransactionStatus.Pending,
            splits,
            checkNumber: null,
            importHash: '',
            createdAt: now,
            updatedAt: now
        } satisfies ITransaction;
    }
}

import {
    ChangeDetectionStrategy,
    Component,
    computed,
    DestroyRef,
    ElementRef,
    HostListener,
    inject,
    signal
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { NavigationEnd, Router, RouterLink, RouterLinkActive } from '@angular/router';
import { type ITransaction, Money, TransactionStatus } from '@core';
import { filter } from 'rxjs';

import { AiAssistantService } from '../../../services/ai-assistant/ai-assistant.service';
import { AuthService } from '../../../services/auth/auth.service';
import { LedgerStore } from '../../../services/ledger-store/ledger.store';
import { ThemeService } from '../../../services/theme/theme.service';

import { BrandLogoComponent } from '../../ui/brand-logo/brand-logo.component';

/**
 * Interface for navigation items within the header.
 */
export interface INavItem {
    name: string;
    href: string;
    icon: string;
}

/**
 * Main application header component with navigation and user profile.
 */
@Component({
    selector: 'header',
    standalone: true,
    imports: [RouterLink, RouterLinkActive, BrandLogoComponent],
    templateUrl: './header.component.html',
    styleUrl: './header.component.css',
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class HeaderComponent {
    private readonly ledgerStore: LedgerStore = inject(LedgerStore);
    private readonly authService: AuthService = inject(AuthService);
    private readonly elementRef: ElementRef = inject(ElementRef);
    private readonly destroyRef: DestroyRef = inject(DestroyRef);
    private readonly router: Router = inject(Router);
    readonly themeService: ThemeService = inject(ThemeService);
    readonly aiAssistantService: AiAssistantService = inject(AiAssistantService);

    readonly showUserMenu = signal<boolean>(false);
    readonly showMobileMenu = signal<boolean>(false);

    toggleAiAssistant(): void {
        this.aiAssistantService.toggle();
    }

    toggleMobileMenu(): void {
        this.showMobileMenu.update(v => !v);
    }

    constructor() {
        // Close menus on any navigation
        this.router.events
            .pipe(
                filter(e => e instanceof NavigationEnd),
                takeUntilDestroyed(this.destroyRef)
            )
            .subscribe(() => {
                this.showUserMenu.set(false);
                this.showMobileMenu.set(false);
            });
    }

    /** Close any open menus when clicking outside the host element. */
    @HostListener('document:click', ['$event?.target'])
    onDocumentClick(target: EventTarget | null | undefined): void {
        if (!this.elementRef.nativeElement.contains(target)) {
            if (this.showUserMenu()) {
                this.showUserMenu.set(false);
            }
            if (this.showMobileMenu()) {
                this.showMobileMenu.set(false);
            }
        }
    }

    /** Close any open menus on Escape key. */
    @HostListener('document:keydown.escape')
    onEscape(): void {
        this.showUserMenu.set(false);
        this.showMobileMenu.set(false);
    }

    /**
     * List of navigation links shown in the header.
     */
    readonly navItems = new Array<INavItem>(
        { name: 'Overview', href: '/', icon: 'pi-home' } satisfies INavItem,
        { name: 'Accounts', href: '/accounts', icon: 'pi-credit-card' } satisfies INavItem,
        { name: 'Payees', href: '/payees', icon: 'pi-users' } satisfies INavItem,
        { name: 'Recurring', href: '/recurring', icon: 'pi-calendar' } satisfies INavItem,
        { name: 'Settings', href: '/settings', icon: 'pi-cog' } satisfies INavItem
    );

    readonly netBalance = computed((): number => {
        const txs: Array<ITransaction> = this.ledgerStore.transactions();
        const cleared: number = txs
            .filter((tx: ITransaction): boolean => tx.status === TransactionStatus.Cleared)
            .reduce((sum: number, tx: ITransaction): number => sum + tx.totalAmount, 0);
        const pending: number = txs
            .filter((tx: ITransaction): boolean => tx.status === TransactionStatus.Pending)
            .reduce((sum: number, tx: ITransaction): number => sum + tx.totalAmount, 0);
        return cleared + pending;
    });

    readonly formattedNetBalance = computed((): string => Money.formatCurrency(this.netBalance()));

    readonly userName = computed(
        (): string => this.authService.currentUser()?.displayName ?? 'User'
    );

    readonly userEmail = computed((): string => this.authService.currentUser()?.email ?? '');

    readonly userPhotoUrl = computed(
        (): string | null => this.authService.currentUser()?.photoURL ?? null
    );

    readonly userInitial = computed((): string => (this.userName().charAt(0) || 'U').toUpperCase());

    /**
     * Toggles the visibility of the user profile dropdown menu.
     */
    toggleUserMenu(): void {
        this.showUserMenu.update(v => !v);
    }

    /**
     * Initiates the sign-out flow and closes the menu.
     */
    handleSignOut(): void {
        this.showUserMenu.set(false);
        void this.authService.signOut();
    }

    /**
     * Toggles between dark and light modes.
     */
    toggleTheme(): void {
        const current = this.themeService.resolvedTheme();
        this.themeService.setTheme(current === 'dark' ? 'light' : 'dark');
    }
}

import { Injectable, inject, signal } from '@angular/core';
import { UserSettingsStore } from '../user-settings-store/user-settings.store';

export enum LlmProvider {
    Gemini = 'gemini',
    Anthropic = 'anthropic',
    OpenAI = 'openai'
}

export interface ILlmModelOption {
    value: string;
    label: string;
    isDefault?: boolean;
}

export interface INewerModelAlert {
    currentModel: string;
    newestModel: string;
    newestLabel: string;
    provider: LlmProvider;
}

interface IGeminiModelRaw {
    name: string;
    displayName?: string;
    supportedGenerationMethods?: Array<string>;
}

interface IOpenAiModelRaw {
    id: string;
}

/**
 * Multi-Provider LLM Service (BYOK model)
 * Supports Google Gemini, Anthropic Claude, and OpenAI client-side REST APIs.
 */
@Injectable({ providedIn: 'root' })
export class LlmService {
    private readonly userSettingsStore = inject(UserSettingsStore);

    readonly newerModelAlert = signal<INewerModelAlert | null>(null);

    /**
     * Gets the currently selected provider (defaults to Gemini).
     */
    selectedProvider(): LlmProvider {
        const p = this.userSettingsStore.getSetting('aiProvider');
        if (p === LlmProvider.Anthropic) return LlmProvider.Anthropic;
        if (p === LlmProvider.OpenAI) return LlmProvider.OpenAI;
        return LlmProvider.Gemini;
    }

    /**
     * Auto-detects the provider based on API key prefix.
     */
    autoDetectProvider(apiKey: string): LlmProvider {
        const trimmed = apiKey.trim();
        if (trimmed.startsWith('sk-ant-')) return LlmProvider.Anthropic;
        if (trimmed.startsWith('sk-')) return LlmProvider.OpenAI;
        if (trimmed.startsWith('AIzaSy')) return LlmProvider.Gemini;
        return this.selectedProvider();
    }

    /**
     * Gets the API key for the current active provider.
     */
    apiKey(): string {
        const provider = this.selectedProvider();
        if (provider === LlmProvider.Anthropic) {
            return this.userSettingsStore.getSetting('anthropicApiKey') ?? '';
        }
        if (provider === LlmProvider.OpenAI) {
            return this.userSettingsStore.getSetting('openaiApiKey') ?? '';
        }
        return (
            this.userSettingsStore.getSetting('geminiApiKey') ??
            this.userSettingsStore.getSetting('aiApiKey') ??
            ''
        );
    }

    /**
     * Checks if an API key is saved for the active provider.
     */
    hasKey(): boolean {
        return this.apiKey().trim().length > 0;
    }

    /**
     * Gets the selected model for the active provider.
     */
    selectedModel(): string {
        const provider = this.selectedProvider();
        const saved =
            this.userSettingsStore.getSetting('aiModel') ??
            this.userSettingsStore.getSetting('geminiModel');
        if (saved) return saved;

        switch (provider) {
            case LlmProvider.Anthropic:
                return 'claude-5-0-sonnet-latest';
            case LlmProvider.OpenAI:
                return 'gpt-4o-mini';
            case LlmProvider.Gemini:
            default:
                return 'gemini-3.5-flash';
        }
    }

    /**
     * Startup check: Detects if a newer model generation is available than selected.
     */
    async checkStartupNewerModel(): Promise<void> {
        const key = this.apiKey().trim();
        if (!key) {
            this.newerModelAlert.set(null);
            return;
        }

        const provider = this.selectedProvider();
        const models = await this.listModels(provider, key);
        if (models.length === 0) return;

        const defaultOption = models.find(m => m.isDefault) ?? models[0];
        if (!defaultOption) return;

        const newestModel = defaultOption.value;
        const currentSaved = this.selectedModel();

        const dismissed = this.userSettingsStore.getSetting('dismissedModelUpgrade');
        if (dismissed === newestModel) {
            this.newerModelAlert.set(null);
            return;
        }

        // Parse version comparison if currentSaved != newestModel
        if (currentSaved !== newestModel && this.isModelNewer(newestModel, currentSaved)) {
            this.newerModelAlert.set({
                currentModel: currentSaved,
                newestModel,
                newestLabel: defaultOption.label,
                provider
            });
        } else {
            this.newerModelAlert.set(null);
        }
    }

    /**
     * Helper to compare model version numbers.
     */
    private isModelNewer(newestModel: string, currentModel: string): boolean {
        const getVer = (name: string): number => {
            const match = name.match(/(\d+(?:\.\d+)?)/);
            return match && match[1] ? parseFloat(match[1]) : 0;
        };
        const newVer = getVer(newestModel);
        const curVer = getVer(currentModel);
        if (newVer > 0 && curVer > 0) return newVer > curVer;
        return newestModel !== currentModel;
    }

    /**
     * Upgrades the selected model to the newest generation.
     */
    async upgradeToNewestModel(newestModel: string): Promise<void> {
        await this.userSettingsStore.updateSetting('aiModel', newestModel);
        if (this.selectedProvider() === LlmProvider.Gemini) {
            await this.userSettingsStore.updateSetting('geminiModel', newestModel);
        }
        this.newerModelAlert.set(null);
    }

    /**
     * Dismisses the newer model upgrade notification.
     */
    async dismissModelUpgrade(newestModel: string): Promise<void> {
        await this.userSettingsStore.updateSetting('dismissedModelUpgrade', newestModel);
        this.newerModelAlert.set(null);
    }

    /**
     * Dynamic model discovery with smart default rules for all providers.
     */
    async listModels(provider: LlmProvider, key: string): Promise<Array<ILlmModelOption>> {
        const trimmedKey = key.trim();
        if (!trimmedKey) return [];

        switch (provider) {
            case LlmProvider.Gemini:
                return this.listGeminiModels(trimmedKey);
            case LlmProvider.Anthropic:
                return this.listClaudeModels();
            case LlmProvider.OpenAI:
                return this.listOpenAiModels(trimmedKey);
            default:
                return [];
        }
    }

    private async listGeminiModels(key: string): Promise<Array<ILlmModelOption>> {
        try {
            const url = `https://generativelanguage.googleapis.com/v1beta/models?key=${key}`;
            const response = await fetch(url);
            if (!response.ok) return this.fallbackGeminiModels();

            const data = await response.json();
            if (!data || !Array.isArray(data.models)) return this.fallbackGeminiModels();

            // 1. Exclude specialized non-text models (nano, banana, robotics, computer-use, tts, omni)
            const valid = (data.models as Array<IGeminiModelRaw>).filter(m => {
                const nameLower = m.name.toLowerCase();
                const displayNameLower = (m.displayName || '').toLowerCase();
                const supportsGen = m.supportedGenerationMethods?.includes('generateContent');
                if (!supportsGen) return false;
                if (!nameLower.includes('gemini')) return false;

                const isExcluded =
                    nameLower.includes('nano') ||
                    nameLower.includes('banana') ||
                    nameLower.includes('robotics') ||
                    nameLower.includes('computer-use') ||
                    nameLower.includes('computer_use') ||
                    nameLower.includes('tts') ||
                    nameLower.includes('custom-tools') ||
                    nameLower.includes('custom_tools') ||
                    nameLower.includes('omni') ||
                    nameLower.includes('audio') ||
                    nameLower.includes('embedding') ||
                    nameLower.includes('imagen') ||
                    displayNameLower.includes('banana') ||
                    displayNameLower.includes('robotics') ||
                    displayNameLower.includes('tts');

                return !isExcluded;
            });

            if (valid.length === 0) return this.fallbackGeminiModels();

            // 2. Parse versions & filter to latest generation (major >= 3 if available)
            const parseVersion = (name: string): number => {
                const match = name.match(/gemini-(\d+(?:\.\d+)?)/i);
                return match && match[1] ? parseFloat(match[1]) : 0;
            };

            const versions = valid.map(m => parseVersion(m.name));
            const maxVersion = Math.max(...versions, 0);

            const latestGenModels = valid.filter(m => {
                const ver = parseVersion(m.name);
                if (maxVersion >= 3) {
                    return ver >= 3.0;
                }
                return ver >= Math.floor(maxVersion);
            });

            const finalModels = latestGenModels.length > 0 ? latestGenModels : valid;

            // 3. Deduplicate by clean model name
            const seenValues = new Set<string>();
            const deduplicated: Array<IGeminiModelRaw> = [];
            for (const m of finalModels) {
                const val = m.name.replace(/^models\//, '');
                if (!seenValues.has(val)) {
                    seenValues.add(val);
                    deduplicated.push(m);
                }
            }

            // 4. Find newest Flash model for default selection
            const flashModels = deduplicated.filter(m => m.name.toLowerCase().includes('flash'));
            flashModels.sort((a, b) => parseVersion(b.name) - parseVersion(a.name));

            const newestFlashVal = flashModels[0]
                ? flashModels[0].name.replace(/^models\//, '')
                : 'gemini-3.6-flash';

            return deduplicated.map(m => {
                const val = m.name.replace(/^models\//, '');
                const opt: ILlmModelOption = {
                    value: val,
                    label: m.displayName || val
                };
                if (val === newestFlashVal) {
                    opt.isDefault = true;
                }
                return opt;
            });
        } catch {
            return this.fallbackGeminiModels();
        }
    }

    private fallbackGeminiModels(): Array<ILlmModelOption> {
        return [
            { value: 'gemini-3.6-flash', label: 'Gemini 3.6 Flash (Recommended)', isDefault: true },
            { value: 'gemini-3.5-flash', label: 'Gemini 3.5 Flash' },
            { value: 'gemini-3.1-pro-preview', label: 'Gemini 3.1 Pro Preview' },
            { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash Preview' }
        ];
    }

    private listClaudeModels(): Array<ILlmModelOption> {
        return [
            {
                value: 'claude-5-0-sonnet-latest',
                label: 'Claude 5 Sonnet (Recommended)',
                isDefault: true
            },
            { value: 'claude-4-sonnet-latest', label: 'Claude 4 Sonnet' },
            { value: 'claude-3-7-sonnet-latest', label: 'Claude 3.7 Sonnet' },
            { value: 'claude-3-5-sonnet-latest', label: 'Claude 3.5 Sonnet' },
            { value: 'claude-3-5-haiku-latest', label: 'Claude 3.5 Haiku (Fast)' }
        ];
    }

    private async listOpenAiModels(key: string): Promise<Array<ILlmModelOption>> {
        try {
            const response = await fetch('https://api.openai.com/v1/models', {
                headers: { Authorization: `Bearer ${key}` }
            });
            if (!response.ok) return this.fallbackOpenAiModels();

            const data = await response.json();
            if (!data || !Array.isArray(data.data)) return this.fallbackOpenAiModels();

            const valid = (data.data as Array<IOpenAiModelRaw>).filter(m => {
                const id = m.id.toLowerCase();
                const isText =
                    id.startsWith('gpt-4') ||
                    id.startsWith('gpt-5') ||
                    id.startsWith('o1') ||
                    id.startsWith('o3');
                const isExcluded =
                    id.includes('audio') ||
                    id.includes('realtime') ||
                    id.includes('whisper') ||
                    id.includes('dall-e') ||
                    id.includes('embedding') ||
                    id.includes('tts') ||
                    id.includes('instruct') ||
                    id.includes('search');
                return isText && !isExcluded;
            });

            if (valid.length === 0) return this.fallbackOpenAiModels();

            const seen = new Set<string>();
            const deduplicated: Array<IOpenAiModelRaw> = [];
            for (const m of valid) {
                if (!seen.has(m.id)) {
                    seen.add(m.id);
                    deduplicated.push(m);
                }
            }

            return deduplicated.map(m => {
                const opt: ILlmModelOption = {
                    value: m.id,
                    label: m.id
                };
                if (m.id === 'gpt-4o-mini') {
                    opt.isDefault = true;
                }
                return opt;
            });
        } catch {
            return this.fallbackOpenAiModels();
        }
    }

    private fallbackOpenAiModels(): Array<ILlmModelOption> {
        return [
            { value: 'gpt-4o-mini', label: 'GPT-4o Mini (Fast - Recommended)', isDefault: true },
            { value: 'gpt-4o', label: 'GPT-4o (Powerful)' },
            { value: 'o3-mini', label: 'o3-mini (Reasoning)' },
            { value: 'gpt-4-turbo', label: 'GPT-4 Turbo' }
        ];
    }

    async generateContent(prompt: string): Promise<string> {
        const key = this.apiKey().trim();
        if (!key) {
            throw new Error('API key is not configured for the active AI provider.');
        }

        const provider = this.selectedProvider();
        const model = this.selectedModel();

        switch (provider) {
            case LlmProvider.Anthropic:
                return this.generateClaudeContent(key, model, prompt);
            case LlmProvider.OpenAI:
                return this.generateOpenAiContent(key, model, prompt);
            case LlmProvider.Gemini:
            default:
                return this.generateGeminiContent(key, model, prompt);
        }
    }

    private async generateGeminiContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{ parts: [{ text: prompt }] }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Gemini API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.candidates?.[0]?.content?.parts?.[0]?.text;
        if (!text) throw new Error('Received empty response from Gemini API.');
        return text;
    }

    private async generateClaudeContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': key,
                'anthropic-version': '2023-06-01',
                'anthropic-dangerous-direct-browser-access': 'true'
            },
            body: JSON.stringify({
                model,
                max_tokens: 2048,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Claude API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.content?.[0]?.text;
        if (!text) throw new Error('Received empty response from Claude API.');
        return text;
    }

    private async generateOpenAiContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const response = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${key}`
            },
            body: JSON.stringify({
                model,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`OpenAI API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.choices?.[0]?.message?.content;
        if (!text) throw new Error('Received empty response from OpenAI API.');
        return text;
    }
}

import { Injectable, inject, signal } from '@angular/core';
import { UserSettingsStore } from '../user-settings-store/user-settings.store';

export enum LlmProvider {
    Gemini = 'gemini',
    Anthropic = 'anthropic',
    OpenAI = 'openai'
}

export interface ILlmModelOption {
    value: string;
    label: string;
    isDefault?: boolean;
}

export interface INewerModelAlert {
    currentModel: string;
    newestModel: string;
    newestLabel: string;
    provider: LlmProvider;
}

interface IGeminiModelRaw {
    name: string;
    displayName?: string;
    supportedGenerationMethods?: Array<string>;
}

interface IOpenAiModelRaw {
    id: string;
}

/**
 * Multi-Provider LLM Service (BYOK model)
 * Supports Google Gemini, Anthropic Claude, and OpenAI client-side REST APIs.
 */
@Injectable({ providedIn: 'root' })
export class LlmService {
    private readonly userSettingsStore = inject(UserSettingsStore);

    readonly newerModelAlert = signal<INewerModelAlert | null>(null);

    /**
     * Gets the currently selected provider (defaults to Gemini).
     */
    selectedProvider(): LlmProvider {
        const p = this.userSettingsStore.getSetting('aiProvider');
        if (p === LlmProvider.Anthropic) return LlmProvider.Anthropic;
        if (p === LlmProvider.OpenAI) return LlmProvider.OpenAI;
        return LlmProvider.Gemini;
    }

    /**
     * Auto-detects the provider based on API key prefix.
     */
    autoDetectProvider(apiKey: string): LlmProvider {
        const trimmed = apiKey.trim();
        if (trimmed.startsWith('sk-ant-')) return LlmProvider.Anthropic;
        if (trimmed.startsWith('sk-')) return LlmProvider.OpenAI;
        if (trimmed.startsWith('AIzaSy')) return LlmProvider.Gemini;
        return this.selectedProvider();
    }

    /**
     * Gets the API key for the current active provider.
     */
    apiKey(): string {
        const provider = this.selectedProvider();
        if (provider === LlmProvider.Anthropic) {
            return this.userSettingsStore.getSetting('anthropicApiKey') ?? '';
        }
        if (provider === LlmProvider.OpenAI) {
            return this.userSettingsStore.getSetting('openaiApiKey') ?? '';
        }
        return (
            this.userSettingsStore.getSetting('geminiApiKey') ??
            this.userSettingsStore.getSetting('aiApiKey') ??
            ''
        );
    }

    /**
     * Checks if an API key is saved for the active provider.
     */
    hasKey(): boolean {
        return this.apiKey().trim().length > 0;
    }

    /**
     * Gets the selected model for the active provider.
     */
    selectedModel(): string {
        const provider = this.selectedProvider();
        const saved =
            this.userSettingsStore.getSetting('aiModel') ??
            this.userSettingsStore.getSetting('geminiModel');
        if (saved) return saved;

        switch (provider) {
            case LlmProvider.Anthropic:
                return 'claude-5-0-sonnet-latest';
            case LlmProvider.OpenAI:
                return 'gpt-4o-mini';
            case LlmProvider.Gemini:
            default:
                return 'gemini-3.5-flash';
        }
    }

    /**
     * Startup check: Detects if a newer model generation is available than selected.
     */
    async checkStartupNewerModel(): Promise<void> {
        const key = this.apiKey().trim();
        if (!key) {
            this.newerModelAlert.set(null);
            return;
        }

        const provider = this.selectedProvider();
        const models = await this.listModels(provider, key);
        if (models.length === 0) return;

        const defaultOption = models.find(m => m.isDefault) ?? models[0];
        if (!defaultOption) return;

        const newestModel = defaultOption.value;
        const currentSaved = this.selectedModel();

        const dismissed = this.userSettingsStore.getSetting('dismissedModelUpgrade');
        if (dismissed === newestModel) {
            this.newerModelAlert.set(null);
            return;
        }

        // Parse version comparison if currentSaved != newestModel
        if (currentSaved !== newestModel && this.isModelNewer(newestModel, currentSaved)) {
            this.newerModelAlert.set({
                currentModel: currentSaved,
                newestModel,
                newestLabel: defaultOption.label,
                provider
            });
        } else {
            this.newerModelAlert.set(null);
        }
    }

    /**
     * Helper to compare model version numbers.
     */
    private isModelNewer(newestModel: string, currentModel: string): boolean {
        const getVer = (name: string): number => {
            const match = name.match(/(\d+(?:\.\d+)?)/);
            return match && match[1] ? parseFloat(match[1]) : 0;
        };
        const newVer = getVer(newestModel);
        const curVer = getVer(currentModel);
        if (newVer > 0 && curVer > 0) return newVer > curVer;
        return newestModel !== currentModel;
    }

    /**
     * Upgrades the selected model to the newest generation.
     */
    async upgradeToNewestModel(newestModel: string): Promise<void> {
        await this.userSettingsStore.updateSetting('aiModel', newestModel);
        if (this.selectedProvider() === LlmProvider.Gemini) {
            await this.userSettingsStore.updateSetting('geminiModel', newestModel);
        }
        this.newerModelAlert.set(null);
    }

    /**
     * Dismisses the newer model upgrade notification.
     */
    async dismissModelUpgrade(newestModel: string): Promise<void> {
        await this.userSettingsStore.updateSetting('dismissedModelUpgrade', newestModel);
        this.newerModelAlert.set(null);
    }

    /**
     * Dynamic model discovery with smart default rules for all providers.
     */
    async listModels(provider: LlmProvider, key: string): Promise<Array<ILlmModelOption>> {
        const trimmedKey = key.trim();
        if (!trimmedKey) return [];

        switch (provider) {
            case LlmProvider.Gemini:
                return this.listGeminiModels(trimmedKey);
            case LlmProvider.Anthropic:
                return this.listClaudeModels();
            case LlmProvider.OpenAI:
                return this.listOpenAiModels(trimmedKey);
            default:
                return [];
        }
    }

    private async listGeminiModels(key: string): Promise<Array<ILlmModelOption>> {
        try {
            const url = `https://generativelanguage.googleapis.com/v1beta/models?key=${key}`;
            const response = await fetch(url);
            if (!response.ok) return this.fallbackGeminiModels();

            const data = await response.json();
            if (!data || !Array.isArray(data.models)) return this.fallbackGeminiModels();

            // 1. Exclude specialized non-text models (nano, banana, robotics, computer-use, tts, omni)
            const valid = (data.models as Array<IGeminiModelRaw>).filter(m => {
                const nameLower = m.name.toLowerCase();
                const displayNameLower = (m.displayName || '').toLowerCase();
                const supportsGen = m.supportedGenerationMethods?.includes('generateContent');
                if (!supportsGen) return false;
                if (!nameLower.includes('gemini')) return false;

                const isExcluded =
                    nameLower.includes('nano') ||
                    nameLower.includes('banana') ||
                    nameLower.includes('robotics') ||
                    nameLower.includes('computer-use') ||
                    nameLower.includes('computer_use') ||
                    nameLower.includes('tts') ||
                    nameLower.includes('custom-tools') ||
                    nameLower.includes('custom_tools') ||
                    nameLower.includes('omni') ||
                    nameLower.includes('audio') ||
                    nameLower.includes('embedding') ||
                    nameLower.includes('imagen') ||
                    displayNameLower.includes('banana') ||
                    displayNameLower.includes('robotics') ||
                    displayNameLower.includes('tts');

                return !isExcluded;
            });

            if (valid.length === 0) return this.fallbackGeminiModels();

            // 2. Parse versions & filter to latest generation (major >= 3 if available)
            const parseVersion = (name: string): number => {
                const match = name.match(/gemini-(\d+(?:\.\d+)?)/i);
                return match && match[1] ? parseFloat(match[1]) : 0;
            };

            const versions = valid.map(m => parseVersion(m.name));
            const maxVersion = Math.max(...versions, 0);

            const latestGenModels = valid.filter(m => {
                const ver = parseVersion(m.name);
                if (maxVersion >= 3) {
                    return ver >= 3.0;
                }
                return ver >= Math.floor(maxVersion);
            });

            const finalModels = latestGenModels.length > 0 ? latestGenModels : valid;

            // 3. Deduplicate by clean model name
            const seenValues = new Set<string>();
            const deduplicated: Array<IGeminiModelRaw> = [];
            for (const m of finalModels) {
                const val = m.name.replace(/^models\//, '');
                if (!seenValues.has(val)) {
                    seenValues.add(val);
                    deduplicated.push(m);
                }
            }

            // 4. Find newest Flash model for default selection
            const flashModels = deduplicated.filter(m => m.name.toLowerCase().includes('flash'));
            flashModels.sort((a, b) => parseVersion(b.name) - parseVersion(a.name));

            const newestFlashVal = flashModels[0]
                ? flashModels[0].name.replace(/^models\//, '')
                : 'gemini-3.6-flash';

            return deduplicated.map(m => {
                const val = m.name.replace(/^models\//, '');
                const opt: ILlmModelOption = {
                    value: val,
                    label: m.displayName || val
                };
                if (val === newestFlashVal) {
                    opt.isDefault = true;
                }
                return opt;
            });
        } catch {
            return this.fallbackGeminiModels();
        }
    }

    private fallbackGeminiModels(): Array<ILlmModelOption> {
        return [
            { value: 'gemini-3.6-flash', label: 'Gemini 3.6 Flash (Recommended)', isDefault: true },
            { value: 'gemini-3.5-flash', label: 'Gemini 3.5 Flash' },
            { value: 'gemini-3.1-pro-preview', label: 'Gemini 3.1 Pro Preview' },
            { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash Preview' }
        ];
    }

    private listClaudeModels(): Array<ILlmModelOption> {
        return [
            {
                value: 'claude-5-0-sonnet-latest',
                label: 'Claude 5 Sonnet (Recommended)',
                isDefault: true
            },
            { value: 'claude-4-sonnet-latest', label: 'Claude 4 Sonnet' },
            { value: 'claude-3-7-sonnet-latest', label: 'Claude 3.7 Sonnet' },
            { value: 'claude-3-5-sonnet-latest', label: 'Claude 3.5 Sonnet' },
            { value: 'claude-3-5-haiku-latest', label: 'Claude 3.5 Haiku (Fast)' }
        ];
    }

    private async listOpenAiModels(key: string): Promise<Array<ILlmModelOption>> {
        try {
            const response = await fetch('https://api.openai.com/v1/models', {
                headers: { Authorization: `Bearer ${key}` }
            });
            if (!response.ok) return this.fallbackOpenAiModels();

            const data = await response.json();
            if (!data || !Array.isArray(data.data)) return this.fallbackOpenAiModels();

            const valid = (data.data as Array<IOpenAiModelRaw>).filter(m => {
                const id = m.id.toLowerCase();
                const isText =
                    id.startsWith('gpt-4') ||
                    id.startsWith('gpt-5') ||
                    id.startsWith('o1') ||
                    id.startsWith('o3');
                const isExcluded =
                    id.includes('audio') ||
                    id.includes('realtime') ||
                    id.includes('whisper') ||
                    id.includes('dall-e') ||
                    id.includes('embedding') ||
                    id.includes('tts') ||
                    id.includes('instruct') ||
                    id.includes('search');
                return isText && !isExcluded;
            });

            if (valid.length === 0) return this.fallbackOpenAiModels();

            const seen = new Set<string>();
            const deduplicated: Array<IOpenAiModelRaw> = [];
            for (const m of valid) {
                if (!seen.has(m.id)) {
                    seen.add(m.id);
                    deduplicated.push(m);
                }
            }

            return deduplicated.map(m => {
                const opt: ILlmModelOption = {
                    value: m.id,
                    label: m.id
                };
                if (m.id === 'gpt-4o-mini') {
                    opt.isDefault = true;
                }
                return opt;
            });
        } catch {
            return this.fallbackOpenAiModels();
        }
    }

    private fallbackOpenAiModels(): Array<ILlmModelOption> {
        return [
            { value: 'gpt-4o-mini', label: 'GPT-4o Mini (Fast - Recommended)', isDefault: true },
            { value: 'gpt-4o', label: 'GPT-4o (Powerful)' },
            { value: 'o3-mini', label: 'o3-mini (Reasoning)' },
            { value: 'gpt-4-turbo', label: 'GPT-4 Turbo' }
        ];
    }

    async generateContent(prompt: string): Promise<string> {
        const key = this.apiKey().trim();
        if (!key) {
            throw new Error('API key is not configured for the active AI provider.');
        }

        const provider = this.selectedProvider();
        const model = this.selectedModel();

        switch (provider) {
            case LlmProvider.Anthropic:
                return this.generateClaudeContent(key, model, prompt);
            case LlmProvider.OpenAI:
                return this.generateOpenAiContent(key, model, prompt);
            case LlmProvider.Gemini:
            default:
                return this.generateGeminiContent(key, model, prompt);
        }
    }

    private async generateGeminiContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{ parts: [{ text: prompt }] }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Gemini API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.candidates?.[0]?.content?.parts?.[0]?.text;
        if (!text) throw new Error('Received empty response from Gemini API.');
        return text;
    }

    private async generateClaudeContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': key,
                'anthropic-version': '2023-06-01',
                'anthropic-dangerous-direct-browser-access': 'true'
            },
            body: JSON.stringify({
                model,
                max_tokens: 2048,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Claude API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.content?.[0]?.text;
        if (!text) throw new Error('Received empty response from Claude API.');
        return text;
    }

    private async generateOpenAiContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const response = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${key}`
            },
            body: JSON.stringify({
                model,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`OpenAI API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.choices?.[0]?.message?.content;
        if (!text) throw new Error('Received empty response from OpenAI API.');
        return text;
    }
}

export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
    address: string | null;
    /** City location. */
    city: string | null;
    /** State/Province. */
    state: string | null;
    /** Postal/Zip code. */
    zipCode: string | null;
    /** Coordinate for map visualization. */
    latitude: number | null;
    /** Coordinate for map visualization. */
    longitude: number | null;
    /** Official website or portal. */
    website: string | null;
    /** Contact phone number. */
    phone: string | null;
    /** Arbitrary notes about this payee. */
    notes: string | null;
    /** Default category ID suggested for new transactions. */
    defaultCategoryId: EntityId | null;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * A category for organizing transactions (e.g., "Groceries", "Rent").
 * Supports a hierarchical tree structure.
 */
export interface ICategory {
    /** Unique ID for the category. */
    id: EntityId;
    /** ID of the parent category (null if top-level). */
    parentId: EntityId | null;
    /** Name of the category (e.g., "Dining Out"). */
    name: string;
    /** Optional detailed description. */
    description: string | null;
    /** Whether the category is currently available for selection. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * An account containing a collection of transactions.
 */
export interface IAccount {
    /** Unique ID for the account. */
    id: EntityId;
    /** Human-readable name (e.g., "Main Checking"). */
    name: string;
    /** Type of account (e.g., checking, savings). */
    type: AccountType;
    /** Financial institution name. */
    institutionName: string;
    /** Sum of all Cleared/Reconciled transactions. */
    clearedBalance: Cents;
    /** Sum of all transactions (Cleared + Pending). */
    pendingBalance: Cents;
    /** Whether the account is currently in use. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
    /** Optional detailed information for loan accounts. */
    loanDetails?: ILoanDetails;
}

/**
 * Frequency interval for recurring scheduled items.
 */
export enum Frequency {
    Daily = 'daily',
    Weekly = 'weekly',
    Biweekly = 'biweekly',
    EveryFourWeeks = 'every_four_weeks',
    Monthly = 'monthly',
    TwiceAMonth = 'twice_a_month',
    Bimonthly = 'bimonthly',
    Quarterly = 'quarterly',
    Yearly = 'yearly'
}

/**
 * Payment methods for scheduled transactions.
 */
export enum PaymentMethod {
    DirectDebit = 'direct_debit',
    DirectDeposit = 'direct_deposit',
    WriteCheck = 'write_check',
    ElectronicTransfer = 'electronic_transfer',
    Other = 'other'
}

/**
 * A template for generating recurring transactions.
 */
export interface IRecurringSchedule {
    /** Unique ID for the schedule. */
    id: EntityId;
    /** The account where generated transactions will be posted. */
    accountId: EntityId;
    /** Default payee for generated transactions. */
    payee: string;
    /** Total amount for the transaction (parent). */
    amount: Cents;
    /** The type of schedule (Debit, Deposit, Paycheck). */
    type: ScheduleType;
    /** How often the transaction repeats. */
    frequency: Frequency;
    /** How the payment is processed. */
    paymentMethod: PaymentMethod;
    /** Date when the schedule begins. */
    startDate: ISODateString;
    /** Optional date when the schedule ends. */
    endDate: ISODateString | null;
    /** Calculated date of the next occurrence. */
    nextDueDate: ISODateString;
    /** Date when the last transaction was posted from this schedule. */
    lastOccurredDate: ISODateString | null;
    /** Splits for the generated transaction. */
    splits: Array<ISplit>;
    /** Optional memo for the transaction. */
    memo: string;
    /** Whether to automatically post the transaction to the ledger on the due date. */
    autoPost: boolean;
    /** Whether the schedule is active and generating projections. */
    isActive: boolean;
}

/**
 * Result of parsing a single split from an external source (e.g. QIF).
 */
export interface IParsedSplit {
    category: string | null;
    amount: Cents;
    memo: string | null;
}

/**
 * Result of parsing a single transaction from an external source (e.g. QIF).
 */
export interface IParsedTransaction {
    date: ISODateString;
    amount: Cents;
    payee: string;
    memo: string;
    checkNumber: string | null;
    category: string | null;
    splits: Array<IParsedSplit>;
    importHash: string;
}

