import { type ResolvedTheme, ThemeService } from '../theme/theme.service';

/**
 * Service for dynamically updating the browser favicon
 * to represent the Path Logic brand logo emblem,
 * styled dynamically with colors matching the theme and environment.
 */
@Injectable({ providedIn: 'root' })
export class FaviconService {
    private readonly document = inject(DOCUMENT);
    private readonly themeService = inject(ThemeService);

    constructor() {
        // Automatically update the favicon when resolvedTheme changes
        effect(() => {
            const theme = this.themeService.resolvedTheme();
            this.updateFavicon(theme);
        });
    }

    private updateFavicon(theme: ResolvedTheme): void {
        const color = this.getFaviconColor(theme);
        const svg = getBrandLogoSvg(color, 'favicon-pl-cut');

        const base64Svg = btoa(svg);
        const dataUrl = `data:image/svg+xml;base64,${base64Svg}`;

        let link: HTMLLinkElement | null = this.document.querySelector("link[rel*='icon']");
        if (!link) {
            link = this.document.createElement('link');
            link.rel = 'icon';
            link.type = 'image/svg+xml';
            this.document.head.appendChild(link);
        } else {
            link.type = 'image/svg+xml';
        }

        link.href = dataUrl;
    }

    private getFaviconColor(theme: ResolvedTheme): string {
        return theme === 'dark' ? environment.theme.faviconDark : environment.theme.faviconLight;
    }
}

import { computed, Injectable, type Signal, signal } from '@angular/core';

@Injectable({
    providedIn: 'root'
})
export class FeatureFlagService {
    private flagsData = signal<Record<string, boolean>>({});

    /**
     * Initializes the flags usually from a backend or cookies
     */
    init(flags: Record<string, boolean>): void {
        this.flagsData.set(flags);
    }

    /**
     * Overrides a flag
     */
    setFlag(key: string, enabled: boolean): void {
        this.flagsData.update(deps => ({ ...deps, [key]: enabled }));
    }

    /**
     * Check if a feature flag is enabled
     */
    isEnabled(key: string): boolean {
        return !!this.flagsData()[key];
    }

    /**
     * Signal for checking flag state reactively
     */
    isFlagEnabledSignal(key: string): Signal<boolean> {
        return computed(() => !!this.flagsData()[key]);
    }

    /**
     * Toggles a flag
     */
    async toggleFlag(key: string, enabled: boolean, apiPath = '/api/flags/toggle'): Promise<void> {
        try {
            await fetch(apiPath, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ flag: key, enabled })
            });
            this.setFlag(key, enabled);
        } catch (e) {
            console.error('Failed to toggle feature flag', e);
        }
    }
}

