import type { Signal, WritableSignal } from '@angular/core';
import { computed, Injectable, signal } from '@angular/core';

/**
 * Cookie prefix for feature flags.
 * Must match the prefix used by the legacy @feature-flags package.
 */
const COOKIE_PREFIX: string = 'ff_';

/**
 * Custom event name for feature flag changes
 * (fallback for browsers without CookieStore API)
 */
const FLAG_CHANGE_EVENT: string = 'featureFlagChange';

/**
 * Event detail interface for flag changes
 */
interface IFlagChangeDetail {
    flag: string;
    enabled: boolean;
}

/**
 * Check if CookieStore API is available
 */
function hasCookieStoreAPI(): boolean {
    return typeof window !== 'undefined' && 'cookieStore' in window;
}

/**
 * Set a cookie with the given name and value
 */
function setCookie(name: string, value: string, days: number = 365): void {
    const expires: Date = new Date();
    expires.setTime(expires.getTime() + days * 24 * 60 * 60 * 1000);
    document.cookie = `${name}=${value};expires=${expires.toUTCString()};path=/;SameSite=Lax`;
}

/**
 * Delete a cookie by setting its expiration to the past
 */
function deleteCookie(name: string): void {
    document.cookie = `${name}=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/;SameSite=Lax`;
}

/**
 * Angular signal-based feature flag service.
 *
 * Replaces the React hooks (`useFeatureFlag`, `useAllFlags`) from
 * `@feature-flags/client` with Angular signals.
 *
 * Cookie persistence uses the same `ff_` prefix for backward compatibility.
 * Listens for cookie changes via CookieStore API (Chrome) or custom events (fallback).
 *
 * @example
 * ```typescript
 * // In a component
 * readonly featureFlags = inject(FeatureFlagService);
 * readonly devEnabled = this.featureFlags.isEnabled('dev');
 *
 * // In template
 * @if (devEnabled()) {
 *   <dev-tools />
 * }
 * ```
 */
@Injectable({ providedIn: 'root' })
export class FeatureFlagService {
    /** Internal writable flags map */
    private readonly _flags: WritableSignal<Record<string, boolean>> = signal<
        Record<string, boolean>
    >({});

    /** Read-only flags map (all flags and their current states) */
    readonly flags: Signal<Record<string, boolean>> = this._flags.asReadonly();

    constructor() {
        // Sync from cookies on init
        this.syncFromCookies();

        // Listen for cookie/flag changes
        this.setupChangeListeners();
    }

    /**
     * Get a computed signal for whether a specific flag is enabled.
     * Returns a cached computed signal (same reference on repeated calls).
     */
    isEnabled(flag: string): Signal<boolean> {
        return computed((): boolean => !!this._flags()[flag]);
    }

    /**
     * Toggle a feature flag on or off.
     * Updates both the cookie and the internal signal state.
     */
    toggle(flag: string, enabled: boolean): void {
        const cookieName: string = `${COOKIE_PREFIX}${flag}`;

        if (enabled) {
            setCookie(cookieName, 'true');
        } else {
            deleteCookie(cookieName);
        }

        // Update internal state
        this._flags.update(
            (current: Record<string, boolean>): Record<string, boolean> => ({
                ...current,
                [flag]: enabled
            })
        );

        // Emit custom event for cross-component sync (fallback for non-CookieStore browsers)
        if (!hasCookieStoreAPI()) {
            const event: CustomEvent<IFlagChangeDetail> = new CustomEvent<IFlagChangeDetail>(
                FLAG_CHANGE_EVENT,
                {
                    detail: { flag, enabled }
                }
            );
            window.dispatchEvent(event);
        }
    }

    /**
     * Read all `ff_*` cookies and populate the internal signal state.
     */
    private syncFromCookies(): void {
        if (typeof document === 'undefined') return;

        const allFlags: Record<string, boolean> = {};
        const cookies: Array<string> = document.cookie.split(';');

        for (const cookie of cookies) {
            const trimmedCookie: string = cookie.trim();
            const [name, value]: Array<string> = trimmedCookie.split('=');
            if (name?.startsWith(COOKIE_PREFIX)) {
                const flagName: string = name.substring(COOKIE_PREFIX.length);
                allFlags[flagName] = value === 'true';
            }
        }

        this._flags.set(allFlags);
    }

    /**
     * Set up listeners for cookie changes (CookieStore API or custom events).
     */
    private setupChangeListeners(): void {
        if (typeof window === 'undefined') return;

        if (hasCookieStoreAPI()) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (window as any).cookieStore.addEventListener('change', (event: any): void => {
                this._flags.update((current: Record<string, boolean>): Record<string, boolean> => {
                    const updated: Record<string, boolean> = { ...current };

                    for (const cookie of event.changed ?? []) {
                        if (cookie.name?.startsWith(COOKIE_PREFIX)) {
                            const flagName: string = cookie.name.substring(COOKIE_PREFIX.length);
                            updated[flagName] = cookie.value === 'true';
                        }
                    }

                    for (const cookie of event.deleted ?? []) {
                        if (cookie.name?.startsWith(COOKIE_PREFIX)) {
                            const flagName: string = cookie.name.substring(COOKIE_PREFIX.length);
                            updated[flagName] = false;
                        }
                    }

                    return updated;
                });
            });
        } else {
            window.addEventListener(FLAG_CHANGE_EVENT, (event: Event): void => {
                const customEvent: CustomEvent<IFlagChangeDetail> =
                    event as CustomEvent<IFlagChangeDetail>;
                this._flags.update(
                    (current: Record<string, boolean>): Record<string, boolean> => ({
                        ...current,
                        [customEvent.detail.flag]: customEvent.detail.enabled
                    })
                );
            });
        }
    }
}

import { Injectable } from '@angular/core';
import type { FirebaseApp } from 'firebase/app';
import { initializeApp } from 'firebase/app';
import type { Auth } from 'firebase/auth';
import {
    browserLocalPersistence,
    browserPopupRedirectResolver,
    initializeAuth
} from 'firebase/auth';

import { environment } from '../../../environments/environment';

/**
 * Firebase initialization service.
 * Since @angular/fire doesn't support Angular 21 yet, we use the Firebase JS SDK directly.
 *
 * IMPORTANT: We use initializeAuth() instead of getAuth() so we can explicitly set
 * browserPopupRedirectResolver. Without this, getRedirectResult() in the modular v9+
 * SDK returns null because it has no resolver to load the auth iframe from the authDomain.
 */
@Injectable({ providedIn: 'root' })
export class FirebaseService {
    readonly app: FirebaseApp;
    readonly auth: Auth;

    constructor() {
        this.app = initializeApp(environment.firebase);
        this.auth = initializeAuth(this.app, {
            persistence: browserLocalPersistence,
            popupRedirectResolver: browserPopupRedirectResolver
        });
    }
}

import { Injectable, inject } from '@angular/core';
import type { ILlmModelOption, LlmProvider } from '../llm/llm.service';
import { LlmService } from '../llm/llm.service';

/**
 * Service for communicating with AI LLM APIs (BYOK model).
 * Delegates to LlmService for multi-provider support (Gemini, Anthropic Claude, OpenAI).
 */
@Injectable({ providedIn: 'root' })
export class GeminiService {
    private readonly llmService = inject(LlmService);

    apiKey(): string {
        return this.llmService.apiKey();
    }

    hasKey(): boolean {
        return this.llmService.hasKey();
    }

    selectedModel(): string {
        return this.llmService.selectedModel();
    }

    selectedProvider(): LlmProvider {
        return this.llmService.selectedProvider();
    }

    async listModels(): Promise<Array<{ value: string; label: string; isDefault?: boolean }>> {
        const provider = this.llmService.selectedProvider();
        const key = this.llmService.apiKey();
        const models: Array<ILlmModelOption> = await this.llmService.listModels(provider, key);
        return models.map(m => {
            const opt: { value: string; label: string; isDefault?: boolean } = {
                value: m.value,
                label: m.label
            };
            if (m.isDefault !== undefined) {
                opt.isDefault = m.isDefault;
            }
            return opt;
        });
    }

    async generateContent(prompt: string): Promise<string> {
        return this.llmService.generateContent(prompt);
    }
}

import type { ErrorHandler } from '@angular/core';
import { inject, Injectable } from '@angular/core';

import { LoggerService } from '../../services/logger/logger.service';

/**
 * Custom Angular Global Error Handler.
 * Catches uncaught runtime exceptions and posts them to the local dev proxy logger.
 */
@Injectable()
export class GlobalErrorHandler implements ErrorHandler {
    private readonly logger = inject(LoggerService);

    handleError(error: unknown): void {
        const errObj = error instanceof Error ? error : new Error(String(error));
        const message = `Uncaught Exception: ${errObj.message}`;
        const stack = errObj.stack;

        // Remote log to dev proxy
        this.logger.logRemote('error', message, error, stack);

        // Re-log to standard console for developer tools
        console.error('Unhandled Error:', error);
    }
}

import type { WritableSignal } from '@angular/core';
import { inject, Injectable, signal } from '@angular/core';
import type { ITransaction } from '../../core/domain/types';
import { TransactionStatus } from '../../core/domain/types';
import { generateImportHash } from '../../core/engine/hashing';
import {
    CorruptionDetector,
    createExportPackage,
    decryptAncillarySettings,
    decryptPayload,
    ExportCleaner,
    ExportConsolidator,
    type IAncillaryPayload,
    type IConsolidatedOutputPackage,
    type ICorruptionReport,
    type IExportFolderSummary,
    type IExportMetadata,
    type IImportOptions,
    type IRecoveryAction,
    type IRetentionPolicy
} from '../../core/export-import';
import { QIFParser } from '../../core/parsers/QIFParser';
import {
    createExportPackageFolder,
    deleteExportPackageFolder,
    downloadExportFileContent,
    listExportPackageFolders,
    listFilesInPackageFolder,
    uploadExportFileToFolder
} from '../../lib/storage/GoogleDriveAdapter';
import { AuthService } from '../auth/auth.service';
import { FeatureFlagService } from '../feature-flag/feature-flag.service';
import { LedgerStore } from '../ledger-store/ledger.store';
import { SyncService } from '../sync/sync.service';
import { UserSettingsStore } from '../user-settings-store/user-settings.store';

@Injectable({ providedIn: 'root' })
export class ImportExportService {
    private readonly ledgerStore: LedgerStore = inject(LedgerStore);
    private readonly userSettingsStore: UserSettingsStore = inject(UserSettingsStore);
    private readonly featureFlagService: FeatureFlagService = inject(FeatureFlagService);
    private readonly authService: AuthService = inject(AuthService);
    private readonly syncService: SyncService = inject(SyncService);

    readonly isExporting: WritableSignal<boolean> = signal<boolean>(false);
    readonly isImporting: WritableSignal<boolean> = signal<boolean>(false);
    readonly isScanning: WritableSignal<boolean> = signal<boolean>(false);

    private getAccessToken(): string {
        const token = this.authService.accessToken();
        if (!token) {
            throw new Error('Google Drive access token not available. Please sign in.');
        }
        return token;
    }

    /**
     * Exports current ledger data and ancillary settings to a new GDrive package folder.
     */
    async exportToGDrive(passphrase: string = 'path-logic-key'): Promise<{ folderName: string }> {
        const accessToken = this.getAccessToken();

        this.isExporting.set(true);

        try {
            const accounts = this.ledgerStore.accounts();
            const accountData = accounts.map(acc => ({
                account: acc,
                transactions: this.ledgerStore.transactions().filter(tx => tx.accountId === acc.id)
            }));

            const ancillaryData = {
                categories: this.ledgerStore.categories(),
                payees: this.ledgerStore.payees(),
                recurringSchedules: this.ledgerStore.schedules(),
                featureFlags: this.featureFlagService.flags(),
                userSettings: this.userSettingsStore.settings() as unknown as Record<
                    string,
                    unknown
                >
            };

            const pkg = await createExportPackage(accountData, ancillaryData, passphrase);

            // Generate YYYYMMDD folder name
            const now = new Date();
            const dateStr = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}`;

            const folder = await createExportPackageFolder(accessToken, dateStr);

            for (const file of pkg.files) {
                await uploadExportFileToFolder(
                    accessToken,
                    folder.id,
                    file.filename,
                    file.mimeType,
                    file.encryptedContent
                );
            }

            return { folderName: folder.name };
        } finally {
            this.isExporting.set(false);
        }
    }

    /**
     * Scans GDrive appDataFolder for all available export packages and parses metadata.
     */
    async scanGDriveExports(): Promise<Array<IExportFolderSummary>> {
        const token = this.authService.accessToken();
        if (!token) return [];

        this.isScanning.set(true);

        try {
            const folders = await listExportPackageFolders(token);
            const result: Array<IExportFolderSummary> = [];

            for (const folder of folders) {
                const files = await listFilesInPackageFolder(token, folder.id);
                const metaFile = files.find(f => f.name === 'export_metadata.json');

                let metadata: IExportMetadata | undefined;
                if (metaFile) {
                    try {
                        const metaJson = await downloadExportFileContent(token, metaFile.id);
                        metadata = JSON.parse(metaJson) as IExportMetadata;
                    } catch {
                        // Ignore parse error
                    }
                }

                const folderSummary: IExportFolderSummary = {
                    folderId: folder.id,
                    folderName: folder.name
                };
                if (folder.modifiedTime) folderSummary.createdAt = folder.modifiedTime;
                if (metadata) folderSummary.metadata = metadata;

                result.push(folderSummary);
            }

            return result;
        } finally {
            this.isScanning.set(false);
        }
    }

    /**
     * Verifies binary checksums and parse integrity of a specific GDrive export folder.
     */
    async verifyExportFolder(
        folderId: string,
        passphrase: string = 'path-logic-key'
    ): Promise<{ metadata: IExportMetadata; report: ICorruptionReport }> {
        const accessToken = this.getAccessToken();

        const files = await listFilesInPackageFolder(accessToken, folderId);
        const metaFile = files.find(f => f.name === 'export_metadata.json');
        if (!metaFile) throw new Error('Missing export_metadata.json in package folder');

        const metaJson = await downloadExportFileContent(accessToken, metaFile.id);
        const metadata = JSON.parse(metaJson) as IExportMetadata;

        const downloadedFiles: Array<{
            filename: string;
            encryptedContent: string;
            decryptedContent?: string;
        }> = [];

        for (const file of files) {
            if (file.name === 'export_metadata.json') continue;

            const encryptedContent = await downloadExportFileContent(accessToken, file.id);
            let decryptedContent: string | undefined;

            try {
                decryptedContent = await decryptPayload(encryptedContent, passphrase);
            } catch {
                // Ignore decryption error for report
            }

            const item: {
                filename: string;
                encryptedContent: string;
                decryptedContent?: string;
            } = {
                filename: file.name,
                encryptedContent
            };
            if (decryptedContent !== undefined) {
                item.decryptedContent = decryptedContent;
            }

            downloadedFiles.push(item);
        }

        const report = await CorruptionDetector.verifyExportIntegrity(metadata, downloadedFiles);
        return { metadata, report };
    }

    /**
     * Executes granular package import into LedgerStore and UserSettingsStore.
     */
    async importGDriveExportPackage(
        folderId: string,
        options: IImportOptions,
        recoveryActions: Array<IRecoveryAction> = [],
        passphrase: string = 'path-logic-key'
    ): Promise<void> {
        const accessToken = this.getAccessToken();

        this.isImporting.set(true);

        try {
            const files = await listFilesInPackageFolder(accessToken, folderId);
            const metaFile = files.find(f => f.name === 'export_metadata.json');
            if (!metaFile) {
                throw new Error(
                    'Missing metadata file: export_metadata.json was not found in package folder.'
                );
            }

            const metaJson = await downloadExportFileContent(accessToken, metaFile.id);
            let metadata: IExportMetadata;
            try {
                metadata = JSON.parse(metaJson) as IExportMetadata;
            } catch {
                throw new Error(
                    'Corrupted metadata file: export_metadata.json contains invalid JSON data.'
                );
            }

            const recoveryMap = new Map<string, IRecoveryAction>();
            for (const act of recoveryActions) {
                recoveryMap.set(act.accountId, act);
            }

            // 1. Process Ancillary Data if selected
            if (metadata.ancillaryFile) {
                const ancFile = files.find(f => f.name === metadata.ancillaryFile.filename);
                if (ancFile) {
                    const encryptedText = await downloadExportFileContent(accessToken, ancFile.id);
                    const ancillaryPayload = await decryptAncillarySettings(
                        encryptedText,
                        passphrase
                    );

                    if (options.settings.featureFlags && ancillaryPayload.featureFlags) {
                        for (const [flag, val] of Object.entries(ancillaryPayload.featureFlags)) {
                            this.featureFlagService.toggle(flag, val);
                        }
                    }
                }
            }

            // 2. Process Account Purges if requested
            if (options.accountImportMode === 'overwrite_all') {
                for (const acc of this.ledgerStore.accounts()) {
                    await this.ledgerStore.purgeAccount(acc.id);
                }
            } else if (options.existingAccountIdsToDelete.length > 0) {
                for (const accId of options.existingAccountIdsToDelete) {
                    await this.ledgerStore.purgeAccount(accId);
                }
            }

            // 3. Process Account & QIF Imports
            const selectedSet = new Set(options.selectedAccountIdsToImport);
            const parser = new QIFParser();

            for (const accMeta of metadata.accounts || []) {
                if (!selectedSet.has(accMeta.id)) continue;

                const qifFile = files.find(f => f.name === accMeta.snakeCaseFilename);
                if (!qifFile) {
                    throw new Error(
                        `Missing account file: '${accMeta.snakeCaseFilename}' for account '${accMeta.name}' was not found in package folder.`
                    );
                }

                const encryptedText = await downloadExportFileContent(accessToken, qifFile.id);
                const decryptedQif = await decryptPayload(encryptedText, passphrase);
                const parseResult = parser.parse(decryptedQif);

                if (parseResult.errors && parseResult.errors.length > 0) {
                    const firstErr = parseResult.errors[0]?.message || 'Invalid QIF file format';
                    throw new Error(`QIF Parse Error in account '${accMeta.name}': ${firstErr}`);
                }

                // Check or create target account
                let targetAccount = this.ledgerStore.accounts().find(a => a.id === accMeta.id);
                if (!targetAccount) {
                    targetAccount = {
                        id: accMeta.id,
                        name: accMeta.name,
                        type: accMeta.type,
                        institutionName: 'Imported Institution',
                        clearedBalance: accMeta.balanceCents,
                        pendingBalance: accMeta.balanceCents,
                        isActive: true,
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString(),
                        deletedAt: null
                    };
                    await this.ledgerStore.addAccount(targetAccount);
                }

                const importedTxs: Array<ITransaction> = [];

                for (const pTx of parseResult.transactions) {
                    const payeeObj = await this.ledgerStore.getOrCreatePayee(
                        pTx.payee || 'Imported Payee'
                    );

                    importedTxs.push({
                        id: `imported-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
                        accountId: accMeta.id,
                        payeeId: payeeObj.id,
                        date: pTx.date,
                        payee: pTx.payee || 'Imported Payee',
                        memo: pTx.memo || '',
                        totalAmount: pTx.amount,
                        status: TransactionStatus.Cleared,
                        splits: pTx.splits.map((s, idx) => ({
                            id: `split-${idx}`,
                            categoryId: s.category || null,
                            memo: s.memo || '',
                            amount: s.amount
                        })),
                        checkNumber: pTx.checkNumber || null,
                        importHash: generateImportHash(pTx.date, pTx.amount, pTx.payee || ''),
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString()
                    });
                }

                // Check for Corruption Recovery Adjustment
                const recovery = recoveryMap.get(accMeta.id);
                if (recovery && recovery.reconciliationAdjustmentCents !== 0) {
                    const recPayee = await this.ledgerStore.getOrCreatePayee(
                        'Reconciliation Adjustment (Import Recovery)'
                    );
                    const nowIso = new Date().toISOString();

                    importedTxs.push({
                        id: `recovery-adj-${Date.now()}`,
                        accountId: accMeta.id,
                        payeeId: recPayee.id,
                        date: nowIso.split('T')[0] ?? '2026-08-08',
                        payee: 'Reconciliation Adjustment (Import Recovery)',
                        memo:
                            recovery.reconciliationMemo ||
                            'Automated reconciliation balancing entry for dropped corrupted records',
                        totalAmount: recovery.reconciliationAdjustmentCents,
                        status: TransactionStatus.Reconciled,
                        splits: [
                            {
                                id: 'split-0',
                                categoryId: null,
                                amount: recovery.reconciliationAdjustmentCents,
                                memo: 'Recovery adjustment'
                            }
                        ],
                        checkNumber: null,
                        importHash: generateImportHash(
                            nowIso.split('T')[0] ?? '2026-08-08',
                            recovery.reconciliationAdjustmentCents,
                            'Reconciliation Adjustment'
                        ),
                        createdAt: nowIso,
                        updatedAt: nowIso
                    });
                }

                for (const tx of importedTxs) {
                    await this.ledgerStore.addTransaction(tx);
                }
            }
            await this.syncService.flushPendingUpload().catch(err => {
                console.error(
                    '[ImportExportService] Failed to flush Drive upload post-import:',
                    err
                );
            });
        } finally {
            this.isImporting.set(false);
        }
    }

    /**
     * Consolidates same-day exports on Google Drive.
     */
    async consolidateSameDayExports(
        targetDateStr: string,
        passphrase: string = 'path-logic-key'
    ): Promise<IConsolidatedOutputPackage> {
        const accessToken = this.getAccessToken();

        const allFolders = await listExportPackageFolders(accessToken);
        const matchingFolders = allFolders.filter(f => f.name.startsWith(targetDateStr));

        if (matchingFolders.length < 2) {
            throw new Error(
                `At least 2 exports on ${targetDateStr} are required for consolidation.`
            );
        }

        const packageContents = [];
        for (const folder of matchingFolders) {
            const files = await listFilesInPackageFolder(accessToken, folder.id);
            const metaFile = files.find(f => f.name === 'export_metadata.json');
            if (!metaFile) continue;

            const metaJson = await downloadExportFileContent(accessToken, metaFile.id);
            const metadata = JSON.parse(metaJson) as IExportMetadata;

            let ancillaryPayload: IAncillaryPayload = {
                categories: [],
                payees: [],
                recurringSchedules: [],
                featureFlags: {},
                userSettings: {}
            };
            if (metadata.ancillaryFile) {
                const ancFile = files.find(f => f.name === metadata.ancillaryFile.filename);
                if (ancFile) {
                    const encryptedAnc = await downloadExportFileContent(accessToken, ancFile.id);
                    ancillaryPayload = await decryptAncillarySettings(encryptedAnc, passphrase);
                }
            }

            const parser = new QIFParser();
            const accounts = [];

            for (const accMeta of metadata.accounts || []) {
                const qifFile = files.find(f => f.name === accMeta.snakeCaseFilename);
                if (!qifFile) continue;

                const encryptedText = await downloadExportFileContent(accessToken, qifFile.id);
                const decryptedQif = await decryptPayload(encryptedText, passphrase);
                const parseResult = parser.parse(decryptedQif);

                const txList: Array<ITransaction> = [];
                for (const pTx of parseResult.transactions) {
                    txList.push({
                        id: `tx-${Math.random()}`,
                        accountId: accMeta.id,
                        payeeId: 'imported-payee',
                        date: pTx.date,
                        payee: pTx.payee || 'Payee',
                        memo: pTx.memo || '',
                        totalAmount: pTx.amount,
                        status: TransactionStatus.Cleared,
                        splits: pTx.splits.map((s, idx) => ({
                            id: `split-${idx}`,
                            categoryId: s.category || null,
                            memo: s.memo || '',
                            amount: s.amount
                        })),
                        checkNumber: pTx.checkNumber || null,
                        importHash: generateImportHash(pTx.date, pTx.amount, pTx.payee || ''),
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString()
                    });
                }

                accounts.push({
                    account: {
                        id: accMeta.id,
                        name: accMeta.name,
                        type: accMeta.type,
                        institutionName: 'Institution',
                        clearedBalance: accMeta.balanceCents,
                        pendingBalance: accMeta.balanceCents,
                        isActive: true,
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString(),
                        deletedAt: null
                    },
                    transactions: txList
                });
            }

            packageContents.push({
                folderName: folder.name,
                metadata,
                accounts,
                ancillaryPayload
            });
        }

        const consolidated = ExportConsolidator.consolidateSameDayExports(
            packageContents,
            targetDateStr
        );

        const accountData = consolidated.accounts.map(a => ({
            account: a.account,
            transactions: a.transactions
        }));

        const newPkg = await createExportPackage(
            accountData,
            consolidated.ancillaryPayload,
            passphrase
        );

        const newFolder = await createExportPackageFolder(
            accessToken,
            `${targetDateStr}_consolidated`
        );
        for (const file of newPkg.files) {
            await uploadExportFileToFolder(
                accessToken,
                newFolder.id,
                file.filename,
                file.mimeType,
                file.encryptedContent
            );
        }

        return consolidated;
    }

    /**
     * Purges old exports based on retention policy.
     */
    async cleanupExportsByPolicy(policy: IRetentionPolicy): Promise<Array<string>> {
        const accessToken = this.getAccessToken();

        const folders = await this.scanGDriveExports();
        const folderIdsToDelete = ExportCleaner.evaluateRetentionPolicy(folders, policy);

        for (const folderId of folderIdsToDelete) {
            await deleteExportPackageFolder(accessToken, folderId);
        }

        return folderIdsToDelete;
    }

    /**
     * Deletes a specific export folder by folder ID.
     */
    async deleteExportFolder(folderId: string): Promise<void> {
        const accessToken = this.getAccessToken();
        await deleteExportPackageFolder(accessToken, folderId);
    }
}

import { Injectable, NgZone, inject, signal } from '@angular/core';
import type { IPayee, IReconciliationMatch, ISODateString, ITransaction } from '@core';
import { KnownCategory, TransactionStatus } from '@core';
import { ReconciliationEngine } from '../../core/engine/ReconciliationEngine';
import { QIFParser } from '../../core/parsers/QIFParser';
import { LedgerStore } from '../ledger-store/ledger.store';
import { SyncService } from '../sync/sync.service';
import type {
    IImportProgress,
    IImportStats,
    ImportStage,
    ImportTier,
    ReconciliationDecision,
    WorkerOutboundMessage
} from './import.types';
import { IMPORT_TIER_THRESHOLDS } from './import.types';

export type { IImportProgress, IImportStats, ImportTier, ReconciliationDecision };

/** Lightweight transaction snapshot sent to the worker for reconciliation. */
interface IExistingTxSnapshot {
    id: string;
    date: string;
    totalAmount: number;
    importHash: string;
}

const IDLE_PROGRESS: IImportProgress = {
    stage: 'idle',
    pct: 0,
    processed: 0,
    total: 0,
    tier: 'small'
};

/**
 * ImportOrchestrationService — manages the full QIF import lifecycle.
 *
 * Responsibilities:
 * - Classify file size into a tier (small / medium / large)
 * - Run small imports inline (no worker overhead)
 * - Spawn a Web Worker for medium and large imports
 * - Emit reactive signals for progress and results
 * - Provide a cancel() method that terminates the worker
 */
@Injectable({ providedIn: 'root' })
export class ImportOrchestrationService {
    private readonly ledgerStore = inject(LedgerStore);
    private readonly syncService = inject(SyncService);
    private readonly zone = inject(NgZone);

    // ── Public reactive state ────────────────────────────────────────────────

    readonly progress = signal<IImportProgress>(IDLE_PROGRESS);
    readonly matches = signal<Array<IReconciliationMatch>>([]);
    readonly stats = signal<IImportStats | null>(null);
    readonly error = signal<string | null>(null);
    readonly unknownCategories = signal<Array<string>>([]);

    // ── Private ──────────────────────────────────────────────────────────────

    private worker: Worker | null = null;
    private currentAccountId: string = '';
    private pendingMatches: Array<IReconciliationMatch> | null = null;
    private pendingTier: ImportTier | null = null;
    private pendingStats: IImportStats | null = null;

    // ── Public API ───────────────────────────────────────────────────────────

    /**
     * Classify a file into an import tier based on its size.
     */
    classifyFile(file: File): ImportTier {
        if (file.size < IMPORT_TIER_THRESHOLDS.SMALL_MAX) return 'small';
        if (file.size < IMPORT_TIER_THRESHOLDS.MEDIUM_MAX) return 'medium';
        return 'large';
    }

    /**
     * Start an import. Automatically selects inline vs. worker strategy.
     */
    startImport(file: File, accountId: string): void {
        this.reset();
        this.currentAccountId = accountId;

        const tier = this.classifyFile(file);
        this.progress.set({ stage: 'reading', pct: 2, processed: 0, total: 0, tier });

        const reader = new FileReader();
        reader.onload = (e): void => {
            const content = e.target?.result as string;
            if (tier === 'small') {
                this.runInline(content, tier);
            } else {
                this.runInWorker(content, tier, accountId);
            }
        };
        reader.onerror = (): void => {
            this.setError('Failed to read file');
        };
        reader.readAsText(file);
    }

    /**
     * Cancel an in-progress worker import.
     */
    cancel(): void {
        if (this.worker) {
            this.worker.postMessage({ type: 'cancel' });
            this.worker.terminate();
            this.worker = null;
        }
        this.progress.update(p => ({ ...p, stage: 'cancelled', pct: 0 }));
    }

    /**
     * Reset all state back to idle.
     */
    reset(): void {
        this.cancel();
        this.progress.set(IDLE_PROGRESS);
        this.matches.set([]);
        this.stats.set(null);
        this.error.set(null);
        this.unknownCategories.set([]);
        this.currentAccountId = '';
        this.pendingMatches = null;
        this.pendingTier = null;
        this.pendingStats = null;
    }

    // ── Category Mapping ─────────────────────────────────────────────────────

    private getCategorySearchPaths(qifCategory: string): Array<string> {
        const isTransfer = qifCategory.startsWith('[') && qifCategory.endsWith(']');
        if (isTransfer) {
            return ['[TRANSFER]'];
        }

        const cleanName = qifCategory.replace(/[[\]]/g, '').trim();
        const paths = [cleanName];

        if (cleanName.includes(':')) {
            const parts = cleanName.split(':');
            const lastPart = parts[parts.length - 1];
            if (lastPart) {
                paths.push(lastPart.trim());
            }
        }

        return paths;
    }

    /**
     * Resolves pending unknown categories, saves them to aliases,
     * applies them to the pending matches, and completes the import.
     * If allowUnmapped is true, any unmapped categories/payees default to KnownCategory.Uncategorized.
     */
    async resolveUnknownCategories(
        mappings: Record<string, string>,
        allowUnmapped = false
    ): Promise<void> {
        if (!this.pendingMatches) return;

        // Process payee mappings and category alias mappings in memory
        const payeeMappings = new Map<string, string>();
        const payeeCategoryMappings = new Map<string, string>();
        const aliasMappings = new Map<string, string>();

        for (const [key, categoryId] of Object.entries(mappings)) {
            if (!categoryId || categoryId === KnownCategory.Uncategorized) continue;

            if (key.startsWith('Payee: ')) {
                const payeeName = key.replace(/^Payee:\s*/, '').trim();
                payeeMappings.set(payeeName.toLowerCase(), categoryId);
                payeeCategoryMappings.set(payeeName, categoryId);
            } else {
                aliasMappings.set(key, categoryId);
            }
        }

        // Bulk upsert payees and aliases in a single IndexedDB transaction
        await this.ledgerStore.bulkUpsertPayeesAndAliases(payeeCategoryMappings, aliasMappings);

        // Apply mappings to pending matches
        const mappedMatches = this.pendingMatches.map(match => {
            const applyCat = (catStr: string | null, payeeName: string): string | null => {
                if (catStr) {
                    const paths = this.getCategorySearchPaths(catStr);
                    for (const path of paths) {
                        if (path === '[TRANSFER]') return KnownCategory.InternalTransfer;

                        const exact = this.ledgerStore
                            .categories()
                            .find(c => c.name.toLowerCase() === path.toLowerCase());
                        if (exact && exact.id !== KnownCategory.Uncategorized) return exact.id;

                        const mappedId = mappings[path] || this.ledgerStore.getCategoryAlias(path);
                        if (mappedId && mappedId !== KnownCategory.Uncategorized) return mappedId;
                    }
                }

                // Try Payee mapping
                const pMappedId =
                    payeeMappings.get(payeeName.toLowerCase()) || mappings[`Payee: ${payeeName}`];
                if (pMappedId && pMappedId !== KnownCategory.Uncategorized) return pMappedId;

                const payee = this.ledgerStore
                    .payees()
                    .find(p => p.name.toLowerCase() === payeeName.toLowerCase());
                if (
                    payee?.defaultCategoryId &&
                    payee.defaultCategoryId !== KnownCategory.Uncategorized
                ) {
                    return payee.defaultCategoryId;
                }

                return allowUnmapped ? KnownCategory.Uncategorized : null;
            };

            const catId = applyCat(match.parsedTx.category, match.parsedTx.payee);

            return {
                ...match,
                parsedTx: {
                    ...match.parsedTx,
                    category: catId,
                    splits: (match.parsedTx.splits || []).map(s => ({
                        ...s,
                        category: applyCat(s.category, match.parsedTx.payee)
                    }))
                }
            };
        });

        const tier = this.pendingTier || 'small';
        const stats = this.pendingStats || {
            newCount: mappedMatches.filter(m => m.type === 'none').length,
            fuzzyCount: mappedMatches.filter(m => m.type === 'fuzzy').length,
            exactCount: mappedMatches.filter(m => m.type === 'exact').length,
            totalCount: mappedMatches.length
        };

        this.applyMappingsAndComplete(mappedMatches, tier, stats);
        this.unknownCategories.set([]);
        this.pendingMatches = null;
        this.pendingStats = null;
        this.pendingTier = null;
    }

    // ── Strategy: Inline (small files) ───────────────────────────────────────

    private runInline(content: string, tier: ImportTier): void {
        try {
            this.setStage('parsing', 30, 0, 0, tier);
            const parser = new QIFParser();
            const result = parser.parse(content);

            this.setStage('reconciling', 60, 0, result.transactions.length, tier);
            const existingTxs = this.getExistingTxSnapshots(this.currentAccountId);
            const matches = ReconciliationEngine.reconcile(result.transactions, existingTxs);

            this.finalize(matches, tier);
        } catch (err) {
            this.setError(err instanceof Error ? err.message : 'Parse failed');
        }
    }

    // ── Strategy: Web Worker (medium / large files) ───────────────────────────

    private runInWorker(content: string, tier: ImportTier, accountId: string): void {
        if (typeof Worker === 'undefined') {
            // Fallback: run inline if Workers not supported
            this.runInline(content, tier);
            return;
        }

        const existingTxs = this.getExistingTxSnapshots(accountId);

        try {
            this.worker = new Worker(new URL('../../workers/qif-import.worker', import.meta.url), {
                type: 'module'
            });
        } catch {
            // Worker bundle failed to load, fall back to inline
            this.runInline(content, tier);
            return;
        }

        this.worker.onmessage = (event: MessageEvent<WorkerOutboundMessage>): void => {
            // Re-enter NgZone so Angular's change detection picks up signal updates
            this.zone.run(() => {
                const msg = event.data;
                if (msg.type === 'progress') {
                    this.setStage(msg.stage, msg.pct, msg.processed, msg.total, tier);
                } else if (msg.type === 'done') {
                    // Yield the main thread to allow the UI to paint the new "Finalizing" state
                    // This creates a deliberate, premium loading state instead of freezing the UI
                    setTimeout(() => {
                        this.finalize(msg.matches, tier, msg.stats);
                        this.worker?.terminate();
                        this.worker = null;
                    }, 400);
                } else if (msg.type === 'error') {
                    this.setError(msg.message);
                    this.worker?.terminate();
                    this.worker = null;
                }
            });
        };

        this.worker.onerror = (err): void => {
            this.zone.run(() => {
                this.setError(err.message ?? 'Worker error');
                this.worker = null;
            });
        };

        this.worker.postMessage({ type: 'start', qifContent: content, existingTxs });
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    private getExistingTxSnapshots(accountId: string): Array<IExistingTxSnapshot> {
        return this.ledgerStore
            .transactions()
            .filter(tx => tx.accountId === accountId)
            .map(tx => ({
                id: tx.id,
                date: tx.date,
                totalAmount: tx.totalAmount,
                importHash: tx.importHash
            }));
    }

    private setStage(
        stage: ImportStage,
        pct: number,
        processed: number,
        total: number,
        tier: ImportTier
    ): void {
        this.progress.set({ stage, pct, processed, total, tier });
    }

    private finalize(
        matches: Array<IReconciliationMatch>,
        tier: ImportTier,
        incomingStats?: IImportStats
    ): void {
        const stats: IImportStats = incomingStats ?? {
            newCount: matches.filter(m => m.type === 'none').length,
            fuzzyCount: matches.filter(m => m.type === 'fuzzy').length,
            exactCount: matches.filter(m => m.type === 'exact').length,
            totalCount: matches.length
        };

        // Pre-cache exact matches and SQLite aliases to prevent O(N^2) synchronous freezes
        const categories = this.ledgerStore.categories();
        const categoryMap = new Map<string, string>();
        for (const c of categories) {
            categoryMap.set(c.name.toLowerCase(), c.id);
        }

        const aliasCache = new Map<string, string | null>();

        const resolveCategoryPath = (path: string): string | null => {
            if (path === '[TRANSFER]') return 'INTERNAL_TRANSFER_VIRTUAL_ID'; // Will map to KnownCategory.InternalTransfer

            const lowerPath = path.toLowerCase();
            const catId = categoryMap.get(lowerPath);
            if (catId && catId !== KnownCategory.Uncategorized) return catId;

            const cachedAlias = aliasCache.get(path);
            if (cachedAlias !== undefined) return cachedAlias;

            const aliasMatch = this.ledgerStore.getCategoryAlias(path);
            if (aliasMatch && aliasMatch !== KnownCategory.Uncategorized) {
                aliasCache.set(path, aliasMatch);
                return aliasMatch;
            }

            aliasCache.set(path, null);
            return null;
        };

        // Scan for unknown categories and uncategorized payees
        const unknowns = new Set<string>();
        const existingPayeeMap = new Map<string, IPayee>(
            this.ledgerStore.payees().map(p => [p.name.toLowerCase(), p])
        );

        for (const match of matches) {
            let hasValidCategory = false;

            const scanCategory = (cat: string | null): boolean => {
                if (!cat) return false;
                const paths = this.getCategorySearchPaths(cat);

                for (const path of paths) {
                    const mappedId = resolveCategoryPath(path);
                    if (mappedId) return true; // Found a valid non-uncategorized match!
                }

                // Unknown! Use the fully qualified path
                const firstPath = paths[0];
                if (firstPath) {
                    unknowns.add(firstPath);
                }
                return false;
            };

            if (match.parsedTx.category) {
                hasValidCategory = scanCategory(match.parsedTx.category);
            }
            for (const split of match.parsedTx.splits || []) {
                if (split.category) {
                    scanCategory(split.category);
                }
            }

            // If transaction has no valid category tag, check payee auto-categorization!
            if (!hasValidCategory && match.parsedTx.payee) {
                const pName = match.parsedTx.payee.trim();
                if (pName && pName.toLowerCase() !== 'opening balance') {
                    const existingPayee = existingPayeeMap.get(pName.toLowerCase());
                    const hasDefaultCat =
                        existingPayee?.defaultCategoryId &&
                        existingPayee.defaultCategoryId !== KnownCategory.Uncategorized;
                    if (!hasDefaultCat) {
                        unknowns.add(`Payee: ${pName}`);
                    }
                }
            }
        }

        if (unknowns.size > 0) {
            this.unknownCategories.set(Array.from(unknowns));
            this.pendingMatches = matches;
            this.pendingStats = stats;
            this.pendingTier = tier;
            this.progress.set({
                stage: 'mapping_categories',
                pct: 80,
                processed: stats.totalCount,
                total: stats.totalCount,
                tier
            });
            return;
        }

        // Apply any pre-existing mappings right away if there are no unknowns
        const mappedMatches = matches.map(match => {
            const applyCat = (catStr: string | null): string | null => {
                if (!catStr) return null;
                const paths = this.getCategorySearchPaths(catStr);

                for (const path of paths) {
                    const mappedId = resolveCategoryPath(path);
                    if (mappedId === 'INTERNAL_TRANSFER_VIRTUAL_ID') {
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        return (window as any).KnownCategory?.InternalTransfer || '[TRANSFER]';
                    }
                    if (mappedId) return mappedId;
                }

                return null;
            };

            return {
                ...match,
                parsedTx: {
                    ...match.parsedTx,
                    category: applyCat(match.parsedTx.category),
                    splits: (match.parsedTx.splits || []).map(s => ({
                        ...s,
                        category: applyCat(s.category)
                    }))
                }
            };
        });

        this.applyMappingsAndComplete(mappedMatches, tier, stats);
    }

    /**
     * Commits all matched/parsed transactions directly.
     * Used primarily by onboarding wizards (new accounts) where no reconciliation is needed.
     */
    async commitImport(accountId: string): Promise<void> {
        const matches = this.matches();
        if (matches.length === 0) return;

        const now = new Date().toISOString() as ISODateString;
        const txsToImport: Array<ITransaction> = [];
        const newPayees = new Map<string, IPayee>();
        const currentPayees = new Map(this.ledgerStore.payees().map(p => [p.name, p]));

        const categories = this.ledgerStore.categories();
        const mapCategory = (cat: string | null | undefined): string => {
            if (!cat) return KnownCategory.Uncategorized;

            // If already a valid category ID in our store, return it
            if (categories.some(c => c.id === cat && c.id !== KnownCategory.Uncategorized)) {
                return cat;
            }

            // Clean: remove brackets and take the last part after ':'
            const cleanNameRaw = cat.replace(/[[\]]/g, '').trim();
            let cleanName = cleanNameRaw;
            if (cleanNameRaw.includes(':')) {
                const parts = cleanNameRaw.split(':');
                const lastPart = parts[parts.length - 1];
                if (lastPart) {
                    cleanName = lastPart.trim();
                }
            }

            const match = categories.find(
                c =>
                    c.name.toLowerCase() === cleanName.toLowerCase() &&
                    c.id !== KnownCategory.Uncategorized
            );
            return match ? match.id : KnownCategory.Uncategorized;
        };

        matches.forEach((match, idx) => {
            const parsed = match.parsedTx;
            let payee = currentPayees.get(parsed.payee) || newPayees.get(parsed.payee);
            if (!payee) {
                payee = {
                    id: `payee-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
                    name: parsed.payee,
                    address: null,
                    city: null,
                    state: null,
                    zipCode: null,
                    latitude: null,
                    longitude: null,
                    website: null,
                    phone: null,
                    notes: null,
                    defaultCategoryId: null,
                    createdAt: now,
                    updatedAt: now
                };
                newPayees.set(parsed.payee, payee);
            }

            txsToImport.push({
                id: `tx-import-${Date.now()}-${idx}`,
                accountId,
                payeeId: payee.id,
                date: parsed.date,
                payee: parsed.payee,
                memo: parsed.memo,
                totalAmount: parsed.amount,
                status: TransactionStatus.Cleared,
                checkNumber: parsed.checkNumber,
                importHash: parsed.importHash,
                splits:
                    parsed.splits && parsed.splits.length > 0
                        ? parsed.splits.map((s, sIdx) => ({
                              id: `split-import-${Date.now()}-${idx}-${sIdx}`,
                              amount: s.amount,
                              memo: s.memo || '',
                              categoryId: mapCategory(s.category)
                          }))
                        : [
                              {
                                  id: `split-import-${Date.now()}-${idx}`,
                                  amount: parsed.amount,
                                  memo: parsed.memo,
                                  categoryId: mapCategory(parsed.category)
                              }
                          ],
                createdAt: now,
                updatedAt: now
            });
        });

        if (newPayees.size > 0 || txsToImport.length > 0) {
            await this.ledgerStore.applyReconciliationBatch(
                Array.from(newPayees.values()),
                txsToImport,
                []
            );
            void this.syncService.flushPendingUpload().catch(err => {
                console.error(
                    '[ImportOrchestration] Failed to flush Drive upload post-import:',
                    err
                );
            });
        }
    }

    private applyMappingsAndComplete(
        matches: Array<IReconciliationMatch>,
        tier: ImportTier,
        stats: IImportStats
    ): void {
        this.matches.set(matches);
        this.stats.set(stats);
        this.progress.set({
            stage: 'done',
            pct: 100,
            processed: stats.totalCount,
            total: stats.totalCount,
            tier
        });
    }

    private setError(message: string): void {
        this.error.set(message);
        this.progress.update(p => ({ ...p, stage: 'error', pct: 0 }));
    }
}

