    type IReconciliationMatch,
    ReconciliationEngine
} from '../../lib/sync/ReconciliationEngine';

/**
 * Sync status values:
 *   synced        — local and Drive are in sync
 *   uploading     — writing local snapshot to Drive
 *   downloading   — fetching Drive snapshot (new device or Drive is newer)
 *   merging       — merge engine running after download
 *   pending-local — no Drive token; data is local-only
 *   error         — Drive operation failed
 */
export type SyncStatus =
    | 'synced'
    | 'uploading'
    | 'downloading'
    | 'merging'
    | 'pending-local'
    | 'error';

/**
 * Angular signal-based ledger store.
 * Replaces the Zustand `useLedgerStore` with Angular signals.
 *
 * All state is reactive via signals. Mutations happen through methods
 * that write to SQLite, then immediately commit to IndexedDB, then
 * set isDirty to trigger background Drive upload.
 */
@Injectable({ providedIn: 'root' })
export class LedgerStore {
    // --- State signals ---
    readonly transactions: WritableSignal<Array<ITransaction>> = signal<Array<ITransaction>>([]);
    readonly accounts: WritableSignal<Array<IAccount>> = signal<Array<IAccount>>([]);
    readonly trashedAccounts: WritableSignal<Array<IAccount>> = signal<Array<IAccount>>([]);
    readonly payees: WritableSignal<Array<IPayee>> = signal<Array<IPayee>>([]);
    readonly categories: WritableSignal<Array<ICategory>> = signal<Array<ICategory>>([]);
    readonly schedules: WritableSignal<Array<IRecurringSchedule>> = signal<
        Array<IRecurringSchedule>
    >([]);
    readonly isLoading: WritableSignal<boolean> = signal<boolean>(false);
    readonly isInitialized: WritableSignal<boolean> = signal<boolean>(false);
    readonly authError: WritableSignal<boolean> = signal<boolean>(false);
    readonly isDirty: WritableSignal<boolean> = signal<boolean>(false);
    readonly syncStatus: WritableSignal<SyncStatus> = signal<SyncStatus>('synced');
    readonly syncError: WritableSignal<string | null> = signal<string | null>(null);
    readonly hasLocalFallback: WritableSignal<boolean> = signal<boolean>(false);
    readonly lockStatus: WritableSignal<ILockStatus | null> = signal<ILockStatus | null>(null);
    /** Number of transactions merged from Drive in the last background sync. */
    readonly mergeCount: WritableSignal<number> = signal<number>(0);
    /** Transactions with true conflicts (both sides changed since last sync). */
    readonly syncConflicts: WritableSignal<Array<ITransactionConflict>> = signal<
        Array<ITransactionConflict>
    >([]);

    /**
     * Firebase UID — set by SyncService after auth resolves.
     * Used by commitToLocal() for encryption.
     */
    userId: string | null = null;

    // --- Database initialization ---

    async initialize(): Promise<void> {
        this.isLoading.set(true);
        try {
            await initDatabase();
            this.refreshAllFromDb();
            this.isInitialized.set(true);
        } catch (error: unknown) {
            console.error('Failed to initialize database:', error);
        } finally {
            this.isLoading.set(false);
        }
    }

    async loadFromEncryptedData(data: Uint8Array): Promise<void> {
        this.isLoading.set(true);
        try {
            await loadDatabase(data);
            this.refreshAllFromDb();
            this.isInitialized.set(true);
        } catch (error: unknown) {
            console.error('Failed to load encrypted data:', error);
        } finally {
            this.isLoading.set(false);
        }
    }

    // --- Transaction CRUD ---

    async addTransaction(tx: ITransaction): Promise<void> {
        insertTransaction(tx);
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async addTransactions(txs: Array<ITransaction>): Promise<void> {
        insertTransactions(txs);
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async updateTransaction(tx: ITransaction): Promise<void> {
        updateTransaction(tx);
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async removeTransaction(txId: string): Promise<void> {
        deleteTransaction(txId);
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    // --- Transfers ---

    async recordTransfer(
        fromAccountId: string,
        toAccountId: string,
        amount: number,
        date: ISODateString,
        memo: string
    ): Promise<void> {
        const fromAccount = this.accounts().find(a => a.id === fromAccountId);
        const toAccount = this.accounts().find(a => a.id === toAccountId);
        if (!fromAccount || !toAccount) throw new Error('Transfer accounts not found');

        const now = new Date().toISOString() as ISODateString;
        const transferId = `transfer-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        const fromTxId = `tx-${Date.now()}-1`;
        const toTxId = `tx-${Date.now()}-2`;

        // Ensure transfer payee exists
        const payeeName = 'Transfer';
        let transferPayee = this.payees().find(p => p.name === payeeName);
        if (!transferPayee) {
            transferPayee = await this.getOrCreatePayee(payeeName);
        }

        const fromTx: ITransaction = {
            id: fromTxId,
            accountId: fromAccountId,
            payeeId: transferPayee.id,
            date,
            payee: `Transfer to ${toAccount.name}`,
            memo,
            totalAmount: -amount,
            status: TransactionStatus.Cleared,
            splits: [
                {
                    id: `split-${fromTxId}`,
                    categoryId: null,
                    memo,
                    amount: -amount
                }
            ],
            checkNumber: null,
            importHash: `manual-transfer-${fromTxId}`,
            linkedTransferId: transferId,
            createdAt: now,
            updatedAt: now
        };

        const toTx: ITransaction = {
            id: toTxId,
            accountId: toAccountId,
            payeeId: transferPayee.id,
            date,
            payee: `Transfer from ${fromAccount.name}`,
            memo,
            totalAmount: amount,
            status: TransactionStatus.Cleared,
            splits: [
                {
                    id: `split-${toTxId}`,
                    categoryId: null,
                    memo,
                    amount: amount
                }
            ],
            checkNumber: null,
            importHash: `manual-transfer-${toTxId}`,
            linkedTransferId: transferId,
            createdAt: now,
            updatedAt: now
        };

        const transferRecord: ITransfer = {
            id: transferId,
            date,
            amount,
            fromAccountId,
            toAccountId,
            fromTransactionId: fromTxId,
            toTransactionId: toTxId,
            fromAccountNameSnapshot: fromAccount.name,
            toAccountNameSnapshot: toAccount.name,
            memo,
            createdAt: now,
            updatedAt: now,
            deletedAt: null
        };

        insertTransaction(fromTx);
        insertTransaction(toTx);
        insertTransfer(transferRecord);

        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async applyReconciliationBatch(
        newPayees: Array<IPayee>,
        txsToImport: Array<ITransaction>,
        txsToUpdate: Array<ITransaction>
    ): Promise<void> {
        applyReconciliationBatch(newPayees, txsToImport, txsToUpdate);
        this.payees.set(getAllPayees());
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    // --- Account CRUD ---

    async addAccount(account: IAccount): Promise<void> {
        insertAccount(account);
        this.accounts.set(getAllAccounts());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async updateAccount(account: IAccount): Promise<void> {
        updateAccount(account);
        this.accounts.set(getAllAccounts());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async removeAccount(accountId: string): Promise<void> {
        softDeleteAccountCascade(accountId);
        this.accounts.set(getAllAccounts());
        this.trashedAccounts.set(getTrashedAccounts());
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async restoreAccount(accountId: string): Promise<void> {
        restoreAccountCascade(accountId);
        this.accounts.set(getAllAccounts());
        this.trashedAccounts.set(getTrashedAccounts());
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async purgeAccount(accountId: string): Promise<void> {
        purgeAccountCascade(accountId);
        this.accounts.set(getAllAccounts());
        this.trashedAccounts.set(getTrashedAccounts());
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async emptyTrash(): Promise<void> {
        purgeAllTrashedAccounts();
        this.accounts.set(getAllAccounts());
        this.trashedAccounts.set(getTrashedAccounts());
        this.transactions.set(getAllTransactions());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    // --- Payee ---

    async getOrCreatePayee(name: string): Promise<IPayee> {
        // Check signal cache first
        const existing: IPayee | undefined = this.payees().find(
            (p: IPayee): boolean => p.name === name
        );
        if (existing) return existing;

        // Check DB
        const dbPayee: IPayee | null = getPayeeByName(name);
        if (dbPayee) {
            this.payees.set(getAllPayees());
            return dbPayee;
        }

        // Create new
        const now: ISODateString = new Date().toISOString() as ISODateString;
        const newPayee: IPayee = {
            id: `payee-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
            name,
            address: null,
            city: null,
            state: null,
            zipCode: null,
            latitude: null,
            longitude: null,
            website: null,
            phone: null,
            notes: null,
            defaultCategoryId: null,
            createdAt: now,
            updatedAt: now
        };

        insertPayee(newPayee);
        this.payees.set(getAllPayees());
        this.isDirty.set(true);
        return newPayee;
    }

    // --- Category ---

    async createCategory(name: string, parentId: string | null = null): Promise<ICategory> {
        const now = new Date().toISOString() as ISODateString;
        const newCat: ICategory = {
            id: `category-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
            parentId,
            name,
            description: null,
            isActive: true,
            createdAt: now,
            updatedAt: now
        };

        insertCategory(newCat);
        this.categories.set(getAllCategories());
        await this.commitToLocal();
        this.isDirty.set(true);
        return newCat;
    }

    // --- Category Aliases ---

    getCategoryAlias(alias: string): string | null {
        return getCategoryAlias(alias);
    }

    async upsertCategoryAlias(alias: string, categoryId: string): Promise<void> {
        upsertCategoryAlias(alias, categoryId);
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async updatePayee(payee: IPayee): Promise<void> {
        updatePayee(payee);
        this.payees.set(getAllPayees());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async bulkUpsertPayeesAndAliases(
        payeeCategoryMappings: Map<string, string>,
        aliasMappings: Map<string, string>
    ): Promise<void> {
        const now = new Date().toISOString() as ISODateString;
        const currentPayees = [...this.payees()];
        const payeeMap = new Map<string, IPayee>(currentPayees.map(p => [p.name.toLowerCase(), p]));

        for (const [payeeName, categoryId] of payeeCategoryMappings) {
            const existing = payeeMap.get(payeeName.toLowerCase());
            if (existing) {
                if (existing.defaultCategoryId !== categoryId) {
                    existing.defaultCategoryId = categoryId;
                    existing.updatedAt = now;
                    updatePayee(existing);
                }
            } else {
                const newPayee: IPayee = {
                    id: `payee-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
                    name: payeeName,
                    address: null,
                    city: null,
                    state: null,
                    zipCode: null,
                    latitude: null,
                    longitude: null,
                    website: null,
                    phone: null,
                    notes: null,
                    defaultCategoryId: categoryId,
                    createdAt: now,
                    updatedAt: now
                };
                insertPayee(newPayee);
                payeeMap.set(payeeName.toLowerCase(), newPayee);
            }
        }

        for (const [alias, categoryId] of aliasMappings) {
            upsertCategoryAlias(alias, categoryId);
        }

        this.payees.set(getAllPayees());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    // --- Recurring Schedules ---

    async addSchedule(schedule: IRecurringSchedule): Promise<void> {
        insertRecurringSchedule(schedule);
        this.schedules.set(getAllRecurringSchedules());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async updateSchedule(schedule: IRecurringSchedule): Promise<void> {
        updateRecurringSchedule(schedule);
        this.schedules.set(getAllRecurringSchedules());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    async removeSchedule(scheduleId: string): Promise<void> {
        deleteRecurringSchedule(scheduleId);
        this.schedules.set(getAllRecurringSchedules());
        await this.commitToLocal();
        this.isDirty.set(true);
    }

    // --- Sync helpers ---

    exportForSync(): Uint8Array {
        return exportDatabase();
    }

    async reconcileTransactions(
        parsedTxs: Array<IParsedTransaction>,
        accountId: string
    ): Promise<Array<IReconciliationMatch>> {
        const db = getDb();
        if (!db) throw new Error('Database not initialized');
        return ReconciliationEngine.reconcile(db, parsedTxs, accountId);
    }

    /**
     * Resolve a specific conflict by choosing one side.
     * Called by the ConflictResolutionModal after the user makes a choice.
     *
     * @param id         Transaction ID
     * @param keepMine   true = keep local version, false = apply remote version
     */
    async resolveConflict(id: string, keepMine: boolean): Promise<void> {
        if (!keepMine) {
            // Apply the remote version — it's already in syncConflicts
            const conflict = this.syncConflicts().find(c => c.id === id);
            if (conflict) {
                const now = new Date().toISOString();
                const tx: ITransaction = {
                    id: conflict.id,
                    accountId: conflict.theirs.accountId,
                    payeeId: conflict.theirs.payeeId,
                    date: conflict.theirs.date as ISODateString,
                    payee: conflict.theirs.payee,
                    memo: conflict.theirs.memo ?? '',
                    totalAmount: conflict.theirs.totalAmount,
                    status: conflict.theirs.status as ITransaction['status'],
                    splits: [],
                    checkNumber: conflict.theirs.checkNumber,
                    importHash: conflict.theirs.importHash ?? '',
                    createdAt: now as ISODateString,
                    updatedAt: now as ISODateString
                };
                await this.updateTransaction(tx);
            }
        }
        // Remove this conflict from the list (whether kept mine or applied theirs)
        this.syncConflicts.update(c => c.filter(x => x.id !== id));
    }

    reset(): void {
        resetDatabase();
        this.transactions.set([]);
        this.accounts.set([]);
        this.payees.set([]);
        this.categories.set([]);
        this.schedules.set([]);
        this.isInitialized.set(false);
        this.isDirty.set(false);
        this.syncStatus.set('synced');
        this.syncError.set(null);
        this.authError.set(false);
        this.hasLocalFallback.set(false);
        this.mergeCount.set(0);
        this.syncConflicts.set([]);
    }

    // --- Private helpers ---

    /**
     * Immediately commits the current SQL.js state to IndexedDB.
     * Called after every mutation as the local write-through step.
     * Non-fatal: if encryption or IndexedDB fails, we log and continue
     * (the SQL.js in-memory state is still correct).
     */
    async commitToLocal(): Promise<void> {
        if (!this.userId) return; // not yet initialized with auth context
        try {
            const dbExport = exportDatabase();
            const encrypted = await encryptDatabase(dbExport, this.userId);
            await saveLocalSnapshot(encrypted);
        } catch (err: unknown) {
            console.error('[LedgerStore] commitToLocal failed (non-fatal):', err);
        }
    }

    private refreshAllFromDb(): void {
        this.transactions.set(getAllTransactions());
        this.accounts.set(getAllAccounts());
        this.trashedAccounts.set(getTrashedAccounts());
        this.payees.set(getAllPayees());
        this.categories.set(getAllCategories());
        this.schedules.set(getAllRecurringSchedules());
    }
}

import { Injectable, inject, signal } from '@angular/core';
import { UserSettingsStore } from '../user-settings-store/user-settings.store';

export enum LlmProvider {
    Gemini = 'gemini',
    Anthropic = 'anthropic',
    OpenAI = 'openai'
}

export interface ILlmModelOption {
    value: string;
    label: string;
    isDefault?: boolean;
}

export interface INewerModelAlert {
    currentModel: string;
    newestModel: string;
    newestLabel: string;
    provider: LlmProvider;
}

interface IGeminiModelRaw {
    name: string;
    displayName?: string;
    supportedGenerationMethods?: Array<string>;
}

interface IOpenAiModelRaw {
    id: string;
}

/**
 * Multi-Provider LLM Service (BYOK model)
 * Supports Google Gemini, Anthropic Claude, and OpenAI client-side REST APIs.
 */
@Injectable({ providedIn: 'root' })
export class LlmService {
    private readonly userSettingsStore = inject(UserSettingsStore);

    readonly newerModelAlert = signal<INewerModelAlert | null>(null);

    /**
     * Gets the currently selected provider (defaults to Gemini).
     */
    selectedProvider(): LlmProvider {
        const p = this.userSettingsStore.getSetting('aiProvider');
        if (p === LlmProvider.Anthropic) return LlmProvider.Anthropic;
        if (p === LlmProvider.OpenAI) return LlmProvider.OpenAI;
        return LlmProvider.Gemini;
    }

    /**
     * Auto-detects the provider based on API key prefix.
     */
    autoDetectProvider(apiKey: string): LlmProvider {
        const trimmed = apiKey.trim();
        if (trimmed.startsWith('sk-ant-')) return LlmProvider.Anthropic;
        if (trimmed.startsWith('sk-')) return LlmProvider.OpenAI;
        if (trimmed.startsWith('AIzaSy')) return LlmProvider.Gemini;
        return this.selectedProvider();
    }

    /**
     * Gets the API key for the current active provider.
     */
    apiKey(): string {
        const provider = this.selectedProvider();
        if (provider === LlmProvider.Anthropic) {
            return this.userSettingsStore.getSetting('anthropicApiKey') ?? '';
        }
        if (provider === LlmProvider.OpenAI) {
            return this.userSettingsStore.getSetting('openaiApiKey') ?? '';
        }
        return (
            this.userSettingsStore.getSetting('geminiApiKey') ??
            this.userSettingsStore.getSetting('aiApiKey') ??
            ''
        );
    }

    /**
     * Checks if an API key is saved for the active provider.
     */
    hasKey(): boolean {
        return this.apiKey().trim().length > 0;
    }

    /**
     * Gets the selected model for the active provider.
     */
    selectedModel(): string {
        const provider = this.selectedProvider();
        const saved =
            this.userSettingsStore.getSetting('aiModel') ??
            this.userSettingsStore.getSetting('geminiModel');
        if (saved) return saved;

        switch (provider) {
            case LlmProvider.Anthropic:
                return 'claude-5-0-sonnet-latest';
            case LlmProvider.OpenAI:
                return 'gpt-4o-mini';
            case LlmProvider.Gemini:
            default:
                return 'gemini-3.5-flash';
        }
    }

    /**
     * Startup check: Detects if a newer model generation is available than selected.
     */
    async checkStartupNewerModel(): Promise<void> {
        const key = this.apiKey().trim();
        if (!key) {
            this.newerModelAlert.set(null);
            return;
        }

        const provider = this.selectedProvider();
        const models = await this.listModels(provider, key);
        if (models.length === 0) return;

        const defaultOption = models.find(m => m.isDefault) ?? models[0];
        if (!defaultOption) return;

        const newestModel = defaultOption.value;
        const currentSaved = this.selectedModel();

        const dismissed = this.userSettingsStore.getSetting('dismissedModelUpgrade');
        if (dismissed === newestModel) {
            this.newerModelAlert.set(null);
            return;
        }

        // Parse version comparison if currentSaved != newestModel
        if (currentSaved !== newestModel && this.isModelNewer(newestModel, currentSaved)) {
            this.newerModelAlert.set({
                currentModel: currentSaved,
                newestModel,
                newestLabel: defaultOption.label,
                provider
            });
        } else {
            this.newerModelAlert.set(null);
        }
    }

    /**
     * Helper to compare model version numbers.
     */
    private isModelNewer(newestModel: string, currentModel: string): boolean {
        const getVer = (name: string): number => {
            const match = name.match(/(\d+(?:\.\d+)?)/);
            return match && match[1] ? parseFloat(match[1]) : 0;
        };
        const newVer = getVer(newestModel);
        const curVer = getVer(currentModel);
        if (newVer > 0 && curVer > 0) return newVer > curVer;
        return newestModel !== currentModel;
    }

    /**
     * Upgrades the selected model to the newest generation.
     */
    async upgradeToNewestModel(newestModel: string): Promise<void> {
        await this.userSettingsStore.updateSetting('aiModel', newestModel);
        if (this.selectedProvider() === LlmProvider.Gemini) {
            await this.userSettingsStore.updateSetting('geminiModel', newestModel);
        }
        this.newerModelAlert.set(null);
    }

    /**
     * Dismisses the newer model upgrade notification.
     */
    async dismissModelUpgrade(newestModel: string): Promise<void> {
        await this.userSettingsStore.updateSetting('dismissedModelUpgrade', newestModel);
        this.newerModelAlert.set(null);
    }

    /**
     * Dynamic model discovery with smart default rules for all providers.
     */
    async listModels(provider: LlmProvider, key: string): Promise<Array<ILlmModelOption>> {
        const trimmedKey = key.trim();
        if (!trimmedKey) return [];

        switch (provider) {
            case LlmProvider.Gemini:
                return this.listGeminiModels(trimmedKey);
            case LlmProvider.Anthropic:
                return this.listClaudeModels();
            case LlmProvider.OpenAI:
                return this.listOpenAiModels(trimmedKey);
            default:
                return [];
        }
    }

    private async listGeminiModels(key: string): Promise<Array<ILlmModelOption>> {
        try {
            const url = `https://generativelanguage.googleapis.com/v1beta/models?key=${key}`;
            const response = await fetch(url);
            if (!response.ok) return this.fallbackGeminiModels();

            const data = await response.json();
            if (!data || !Array.isArray(data.models)) return this.fallbackGeminiModels();

            // 1. Exclude specialized non-text models (nano, banana, robotics, computer-use, tts, omni)
            const valid = (data.models as Array<IGeminiModelRaw>).filter(m => {
                const nameLower = m.name.toLowerCase();
                const displayNameLower = (m.displayName || '').toLowerCase();
                const supportsGen = m.supportedGenerationMethods?.includes('generateContent');
                if (!supportsGen) return false;
                if (!nameLower.includes('gemini')) return false;

                const isExcluded =
                    nameLower.includes('nano') ||
                    nameLower.includes('banana') ||
                    nameLower.includes('robotics') ||
                    nameLower.includes('computer-use') ||
                    nameLower.includes('computer_use') ||
                    nameLower.includes('tts') ||
                    nameLower.includes('custom-tools') ||
                    nameLower.includes('custom_tools') ||
                    nameLower.includes('omni') ||
                    nameLower.includes('audio') ||
                    nameLower.includes('embedding') ||
                    nameLower.includes('imagen') ||
                    displayNameLower.includes('banana') ||
                    displayNameLower.includes('robotics') ||
                    displayNameLower.includes('tts');

                return !isExcluded;
            });

            if (valid.length === 0) return this.fallbackGeminiModels();

            // 2. Parse versions & filter to latest generation (major >= 3 if available)
            const parseVersion = (name: string): number => {
                const match = name.match(/gemini-(\d+(?:\.\d+)?)/i);
                return match && match[1] ? parseFloat(match[1]) : 0;
            };

            const versions = valid.map(m => parseVersion(m.name));
            const maxVersion = Math.max(...versions, 0);

            const latestGenModels = valid.filter(m => {
                const ver = parseVersion(m.name);
                if (maxVersion >= 3) {
                    return ver >= 3.0;
                }
                return ver >= Math.floor(maxVersion);
            });

            const finalModels = latestGenModels.length > 0 ? latestGenModels : valid;

            // 3. Deduplicate by clean model name
            const seenValues = new Set<string>();
            const deduplicated: Array<IGeminiModelRaw> = [];
            for (const m of finalModels) {
                const val = m.name.replace(/^models\//, '');
                if (!seenValues.has(val)) {
                    seenValues.add(val);
                    deduplicated.push(m);
                }
            }

            // 4. Find newest Flash model for default selection
            const flashModels = deduplicated.filter(m => m.name.toLowerCase().includes('flash'));
            flashModels.sort((a, b) => parseVersion(b.name) - parseVersion(a.name));

            const newestFlashVal = flashModels[0]
                ? flashModels[0].name.replace(/^models\//, '')
                : 'gemini-3.6-flash';

            return deduplicated.map(m => {
                const val = m.name.replace(/^models\//, '');
                const opt: ILlmModelOption = {
                    value: val,
                    label: m.displayName || val
                };
                if (val === newestFlashVal) {
                    opt.isDefault = true;
                }
                return opt;
            });
        } catch {
            return this.fallbackGeminiModels();
        }
    }

    private fallbackGeminiModels(): Array<ILlmModelOption> {
        return [
            { value: 'gemini-3.6-flash', label: 'Gemini 3.6 Flash (Recommended)', isDefault: true },
            { value: 'gemini-3.5-flash', label: 'Gemini 3.5 Flash' },
            { value: 'gemini-3.1-pro-preview', label: 'Gemini 3.1 Pro Preview' },
            { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash Preview' }
        ];
    }

    private listClaudeModels(): Array<ILlmModelOption> {
        return [
            {
                value: 'claude-5-0-sonnet-latest',
                label: 'Claude 5 Sonnet (Recommended)',
                isDefault: true
            },
            { value: 'claude-4-sonnet-latest', label: 'Claude 4 Sonnet' },
            { value: 'claude-3-7-sonnet-latest', label: 'Claude 3.7 Sonnet' },
            { value: 'claude-3-5-sonnet-latest', label: 'Claude 3.5 Sonnet' },
            { value: 'claude-3-5-haiku-latest', label: 'Claude 3.5 Haiku (Fast)' }
        ];
    }

    private async listOpenAiModels(key: string): Promise<Array<ILlmModelOption>> {
        try {
            const response = await fetch('https://api.openai.com/v1/models', {
                headers: { Authorization: `Bearer ${key}` }
            });
            if (!response.ok) return this.fallbackOpenAiModels();

            const data = await response.json();
            if (!data || !Array.isArray(data.data)) return this.fallbackOpenAiModels();

            const valid = (data.data as Array<IOpenAiModelRaw>).filter(m => {
                const id = m.id.toLowerCase();
                const isText =
                    id.startsWith('gpt-4') ||
                    id.startsWith('gpt-5') ||
                    id.startsWith('o1') ||
                    id.startsWith('o3');
                const isExcluded =
                    id.includes('audio') ||
                    id.includes('realtime') ||
                    id.includes('whisper') ||
                    id.includes('dall-e') ||
                    id.includes('embedding') ||
                    id.includes('tts') ||
                    id.includes('instruct') ||
                    id.includes('search');
                return isText && !isExcluded;
            });

            if (valid.length === 0) return this.fallbackOpenAiModels();

            const seen = new Set<string>();
            const deduplicated: Array<IOpenAiModelRaw> = [];
            for (const m of valid) {
                if (!seen.has(m.id)) {
                    seen.add(m.id);
                    deduplicated.push(m);
                }
            }

            return deduplicated.map(m => {
                const opt: ILlmModelOption = {
                    value: m.id,
                    label: m.id
                };
                if (m.id === 'gpt-4o-mini') {
                    opt.isDefault = true;
                }
                return opt;
            });
        } catch {
            return this.fallbackOpenAiModels();
        }
    }

    private fallbackOpenAiModels(): Array<ILlmModelOption> {
        return [
            { value: 'gpt-4o-mini', label: 'GPT-4o Mini (Fast - Recommended)', isDefault: true },
            { value: 'gpt-4o', label: 'GPT-4o (Powerful)' },
            { value: 'o3-mini', label: 'o3-mini (Reasoning)' },
            { value: 'gpt-4-turbo', label: 'GPT-4 Turbo' }
        ];
    }

    async generateContent(prompt: string): Promise<string> {
        const key = this.apiKey().trim();
        if (!key) {
            throw new Error('API key is not configured for the active AI provider.');
        }

        const provider = this.selectedProvider();
        const model = this.selectedModel();

        switch (provider) {
            case LlmProvider.Anthropic:
                return this.generateClaudeContent(key, model, prompt);
            case LlmProvider.OpenAI:
                return this.generateOpenAiContent(key, model, prompt);
            case LlmProvider.Gemini:
            default:
                return this.generateGeminiContent(key, model, prompt);
        }
    }

    private async generateGeminiContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{ parts: [{ text: prompt }] }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Gemini API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.candidates?.[0]?.content?.parts?.[0]?.text;
        if (!text) throw new Error('Received empty response from Gemini API.');
        return text;
    }

    private async generateClaudeContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': key,
                'anthropic-version': '2023-06-01',
                'anthropic-dangerous-direct-browser-access': 'true'
            },
            body: JSON.stringify({
                model,
                max_tokens: 2048,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Claude API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.content?.[0]?.text;
        if (!text) throw new Error('Received empty response from Claude API.');
        return text;
    }

    private async generateOpenAiContent(
        key: string,
        model: string,
        prompt: string
    ): Promise<string> {
        const response = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${key}`
            },
            body: JSON.stringify({
                model,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`OpenAI API error (${response.status}): ${errText}`);
        }

        const data = await response.json();
        const text = data.choices?.[0]?.message?.content;
        if (!text) throw new Error('Received empty response from OpenAI API.');
        return text;
    }
}

import { Injectable } from '@angular/core';

import { environment } from '../../../environments/environment';

export interface IRemoteLogEntry {
    level: 'debug' | 'log' | 'info' | 'warn' | 'error';
    message: string;
    details?: unknown;
    stack?: string;
    timestamp: string;
}

@Injectable({
    providedIn: 'root'
})
export class LoggerService {
    private isInitialized = false;

    constructor() {
        this.init();
    }

    /**
     * Initializes console wrapping ONLY if environment.enableRemoteLogging is strictly true.
     */
    init(): void {
        const win = window as unknown as Record<string, boolean>;
        if (
            this.isInitialized ||
            win['__PATH_LOGIC_LOGGER_INITIALIZED__'] ||
            !environment.enableRemoteLogging
        ) {
            return;
        }

        this.isInitialized = true;
        win['__PATH_LOGIC_LOGGER_INITIALIZED__'] = true;
        const endpoint = environment.remoteLogEndpoint || '/api/log';

        const originalLog = console.log;
        const originalInfo = console.info;
        const originalWarn = console.warn;
        const originalError = console.error;
        const originalDebug = console.debug;

        const sendRemoteLog = (
            level: IRemoteLogEntry['level'],
            args: Array<unknown>,
            stack?: string
        ): void => {
            const message = args
                .map(a =>
                    typeof a === 'object' ? (a instanceof Error ? a.message : 'Object') : String(a)
                )
                .join(' ');

            const payload: IRemoteLogEntry = {
                level,
                message,
                timestamp: new Date().toISOString()
            };

            if (args.length > 1) {
                payload.details = args.slice(1);
            }
            if (stack) {
                payload.stack = stack;
            }

            // Fire-and-forget fetch to avoid blocking the main UI thread
            fetch(endpoint, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            }).catch(() => {
                // Silently swallow proxy fetch errors if dev server endpoint is unreachable
            });
        };

        console.log = (...args: Array<unknown>): void => {
            originalLog.apply(console, args);
            sendRemoteLog('log', args);
        };

        console.info = (...args: Array<unknown>): void => {
            originalInfo.apply(console, args);
            sendRemoteLog('info', args);
        };

        console.warn = (...args: Array<unknown>): void => {
            originalWarn.apply(console, args);
            sendRemoteLog('warn', args);
        };

        console.error = (...args: Array<unknown>): void => {
            originalError.apply(console, args);
            sendRemoteLog('error', args);
        };

        console.debug = (...args: Array<unknown>): void => {
            originalDebug.apply(console, args);
            sendRemoteLog('debug', args);
        };
    }

    /**
     * Helper to manually post remote log events.
     */
    logRemote(
        level: IRemoteLogEntry['level'],
        message: string,
        details?: unknown,
        stack?: string
    ): void {
        if (!environment.enableRemoteLogging) return;

        const endpoint = environment.remoteLogEndpoint || '/api/log';
        const payload: IRemoteLogEntry = {
            level,
            message,
            timestamp: new Date().toISOString()
        };

        if (details !== undefined) {
            payload.details = details;
        }
        if (stack) {
            payload.stack = stack;
        }

        fetch(endpoint, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        }).catch(() => void 0);
    }
}

import { isPlatformBrowser } from '@angular/common';
import { inject, Injectable, PLATFORM_ID } from '@angular/core';
import posthog, { type PostHogConfig } from 'posthog-js';

/**
 * Singleton service wrapping the PostHog SDK.
 * Provides SSR safety by checking the platform before any PostHog call.
 */
@Injectable({ providedIn: 'root' })
export class PostHogService {
    private readonly platformId = inject(PLATFORM_ID);
    private initialized = false;

    /**
     * The posthog instance. Returns a no-op proxy on the server to ensure SSR safety.
     */
    get posthog(): typeof posthog {
        if (isPlatformBrowser(this.platformId) && this.initialized) {
            return posthog;
        }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return new Proxy({} as typeof posthog, { get: () => () => undefined }) as any;
    }

    init(apiKey: string, options: Partial<PostHogConfig>): void {
        if (isPlatformBrowser(this.platformId) && !this.initialized) {
            posthog.init(apiKey, options);
            this.initialized = true;
        }
    }
}

import type { WritableSignal } from '@angular/core';
import { DestroyRef, inject, Injectable, signal } from '@angular/core';
import type { TimerHandle } from '@core';

import { environment } from '../../../environments/environment';
import { AuthService } from '../auth/auth.service';
import { LedgerStore } from '../ledger-store/ledger.store';

const IDLE_TIMEOUT_MS: number = 10 * 60 * 1000; // 10 minutes to logout
const WARNING_TIMEOUT_MS: number = 5 * 60 * 1000; // 5 minutes to show overlay

/**
 * Angular service replacing the React `useSecurityManager` hook.
 * Manages idle timeouts, security overlays, and beforeunload guards.
 */
@Injectable({ providedIn: 'root' })
export class SecurityManagerService {
    private readonly destroyRef: DestroyRef = inject(DestroyRef);
    private readonly ledgerStore: LedgerStore = inject(LedgerStore);
    private readonly authService: AuthService = inject(AuthService);

    readonly isIdle: WritableSignal<boolean> = signal<boolean>(false);

    private idleTimer: TimerHandle | null = null;
    private logoutTimer: TimerHandle | null = null;
    private activityListener: (() => void) | null = null;
    private beforeUnloadListener: ((e: BeforeUnloadEvent) => void) | null = null;

    /**
     * Call from the AppShell component's constructor to start monitoring.
     */
    startMonitoring(): void {
        console.log('[SecurityManager] startMonitoring, environment.e2e:', environment.e2e);
        this.setupActivityListeners();
        this.setupBeforeUnloadGuard();
        this.resetTimers();

        this.destroyRef.onDestroy((): void => {
            this.cleanup();
        });
    }

    /**
     * Reset idle timers (called on user activity or "Resume Session").
     */
    resetTimers(): void {
        if (this.idleTimer) clearTimeout(this.idleTimer);
        if (this.logoutTimer) clearTimeout(this.logoutTimer);

        if (this.isIdle()) {
            this.isIdle.set(false);
        }

        // Do not activate idle timers in E2E mode
        if (environment.e2e) {
            return;
        }

        // Warning overlay after 5 minutes
        this.idleTimer = setTimeout((): void => {
            if (this.authService.currentUser()) {
                console.log('[SecurityManager] Session idle: showing overlay');
                this.isIdle.set(true);
            }
        }, WARNING_TIMEOUT_MS);

        // Auto-logout after 10 minutes
        this.logoutTimer = setTimeout((): void => {
            if (this.authService.currentUser()) {
                console.log('[SecurityManager] Session timeout: logging out');
                void this.authService.signOut();
            }
        }, IDLE_TIMEOUT_MS);
    }

    private setupActivityListeners(): void {
        const events: Array<string> = ['mousedown', 'keydown', 'scroll', 'touchstart'];

        const handleActivity = (): void => {
            if (!this.isIdle()) {
                this.resetTimers();
            }
        };

        this.activityListener = handleActivity;
        events.forEach((event: string): void => window.addEventListener(event, handleActivity));

        this.destroyRef.onDestroy((): void => {
            events.forEach((event: string): void =>
                window.removeEventListener(event, handleActivity)
            );
        });
    }

    private setupBeforeUnloadGuard(): void {
        this.beforeUnloadListener = (e: BeforeUnloadEvent): void => {
            if (this.ledgerStore.isDirty() || this.ledgerStore.authError()) {
                e.preventDefault();
            }
        };

        window.addEventListener('beforeunload', this.beforeUnloadListener);

        this.destroyRef.onDestroy((): void => {
            if (this.beforeUnloadListener) {
                window.removeEventListener('beforeunload', this.beforeUnloadListener);
            }
        });
    }

    private cleanup(): void {
        if (this.idleTimer) clearTimeout(this.idleTimer);
        if (this.logoutTimer) clearTimeout(this.logoutTimer);
    }
}

import type { WritableSignal } from '@angular/core';
import { inject, Injectable, signal } from '@angular/core';

import { decryptDatabase, encryptDatabase } from '../../lib/crypto/encryption';
import { GDriveAuthError } from '../../lib/storage/errors';
import {
    acquireLock,
    downloadDatabase,
    findDatabaseFile,
    forceReleaseLock,
    getLockStatus,
    type IDriveFile,
    releaseLock,
    uploadDatabase
} from '../../lib/storage/GoogleDriveAdapter';
import {
    getLastDriveSyncTime,
    loadLocalSnapshot,
    saveLastDriveSyncTime,
    saveLocalSnapshot
} from '../../lib/storage/LocalPersistenceAdapter';
import { getDb } from '../../lib/storage/SQLiteAdapter';
import type { IMergeResult } from '../../lib/sync/MergeEngine';
import { SQLiteMergeEngine } from '../../lib/sync/MergeEngine';
import { AuthService } from '../auth/auth.service';
import { LedgerStore } from '../ledger-store/ledger.store';
import { PostHogService } from '../posthog/posthog.service';

interface ISyncStatus {
    inProgress: boolean;
    lastSyncTime: number;
}

const SYNC_DEBOUNCE_MS: number = 2000;

/**
 * SyncService — Local-First Architecture
 *
 * IndexedDB is the primary data store. Google Drive is the background
 * cloud backup. The app is always instantly usable from local storage.
 *
 * ## Startup sequence (called from AppComponent):
 *
 *   1. initFromLocal(userId)
 *      → Load IndexedDB snapshot → decrypt → SQL.js → app is usable
 *      → Returns true if local data existed, false if new device
 *
 *   2a. If local data existed:
 *      → syncFromDrive() runs in the BACKGROUND (no await)
 *      → Downloads Drive version, compares timestamps
 *      → If Drive is newer: merge + update IndexedDB
 *      → If local is newer: upload local to Drive
 *
 *   2b. If NO local data (new device):
 *      → syncFromDrive() runs with await (blocking)
 *      → Shows "Syncing your Ledger" screen
 *      → Downloads Drive data, writes to IndexedDB, app becomes usable
 *
 * ## Write path (every mutation):
 *   LedgerStore.mutate() → SQL.js → commitToLocal() (IndexedDB, immediate)
 *                        → isDirty = true → auto-save → saveToDrive() (background)
 */
@Injectable({ providedIn: 'root' })
export class SyncService {
    private syncInProgress: boolean = false;
    private lastSyncTime: number = 0;

    readonly isSyncing: WritableSignal<boolean> = signal<boolean>(false);

    private readonly ledgerStore: LedgerStore = inject(LedgerStore);
    private readonly authService: AuthService = inject(AuthService);
    private readonly posthogService: PostHogService = inject(PostHogService);

    // ── Startup: Step 1 — Load from IndexedDB ────────────────────────────────

    /**
     * Load the local IndexedDB snapshot and hydrate the store.
     * This is always the FIRST step on startup — instant, no network.
     *
     * Sets userId on the LedgerStore so commitToLocal() can encrypt.
     *
     * @returns true if local data was found and loaded, false if new device.
     */
    async initFromLocal(userId: string): Promise<boolean> {
        this.ledgerStore.userId = userId;
        this.ledgerStore.isLoading.set(true);

        try {
            const snapshot = await loadLocalSnapshot();

            if (snapshot) {
                const decrypted = await decryptDatabase(snapshot.encryptedData, userId);
                await this.ledgerStore.loadFromEncryptedData(decrypted);
                this.ledgerStore.hasLocalFallback.set(true);
                console.info(
                    `[Sync] Loaded local snapshot (version: ${new Date(snapshot.version).toISOString()})`
                );
                return true;
            } else {
                console.info('[Sync] No local snapshot — new device or first install.');
                return false;
            }
        } catch (err: unknown) {
            console.error('[Sync] Failed to load local snapshot:', err);
            return false;
        } finally {
            this.ledgerStore.isLoading.set(false);
        }
    }

    // ── Startup: Step 2 — Background Drive sync ───────────────────────────────

    /**
     * Background Drive sync — compares local version with Drive and
     * reconciles differences. Safe to call without await after initFromLocal().
     *
     * If no Drive token is available, sets authError and returns.
     * The sync-pending banner will prompt the user to re-authenticate.
     */
    async syncFromDrive(): Promise<void> {
        const accessToken = this.authService.accessToken();
        const userId = this.authService.userId();

        if (!accessToken || !userId) {
            // No Drive token — local-only mode
            this.ledgerStore.authError.set(true);
            this.ledgerStore.syncStatus.set('pending-local');

            // Ensure the DB is initialized even without Drive
            if (!this.ledgerStore.isInitialized()) {
                await this.ledgerStore.initialize();
            }
            return;
        }

        this.isSyncing.set(true);

        try {
            const driveFile: IDriveFile | null = await findDatabaseFile(accessToken);

            if (!driveFile) {
                // No Drive file — this is a fresh install or Drive was cleared.
                // Upload local state (if any) or just mark as synced.
                if (this.ledgerStore.isInitialized()) {
                    await this.uploadToDrive(accessToken, userId, null);
                } else {
                    // Truly fresh start — no local AND no Drive
                    await this.ledgerStore.initialize();
                    this.ledgerStore.syncStatus.set('synced');
                    this.posthogService.posthog.capture('data_loaded_from_drive', {
                        source: 'fresh_start',
                        is_returning_user: false
                    });
                }
                return;
            }

            // Drive file exists — compare timestamps against the last successful Drive sync time on this device
            const lastSyncTime = getLastDriveSyncTime();
            const driveModifiedMs = new Date(driveFile.modifiedTime ?? 0).getTime();

            if (driveModifiedMs > lastSyncTime) {
                // Drive is newer than our last sync timestamp — download, decrypt, merge
                await this.downloadAndMerge(accessToken, userId, driveFile);
            } else {
                // Local is up to date with or newer than Drive — upload if dirty
                if (this.ledgerStore.isDirty()) {
                    await this.uploadToDrive(accessToken, userId, driveFile.id);
                } else {
                    this.ledgerStore.syncStatus.set('synced');
                }
            }
        } catch (error: unknown) {
            if (error instanceof GDriveAuthError) {
                this.ledgerStore.authError.set(true);
                this.ledgerStore.syncStatus.set('pending-local');
            } else {
                console.error('[Sync] syncFromDrive failed:', error);
                this.ledgerStore.syncStatus.set('error');
                this.ledgerStore.syncError.set(
                    error instanceof Error ? error.message : 'Unknown sync error'
                );
            }
        } finally {
            this.isSyncing.set(false);
        }
    }

    // ── Mutations: Save dirty state to Drive ──────────────────────────────────

    private debouncedSaveTimer: ReturnType<typeof setTimeout> | null = null;

    /**
     * Save current database to Drive (debounced, with lock + merge).
     * Called by AppComponent's auto-save effect after mutations.
     *
     * @param forceImmediate If true, bypasses the SYNC_DEBOUNCE_MS rate limit check.
     */
    async saveToDrive(forceImmediate = false): Promise<void> {
        const accessToken: string | null = this.authService.accessToken();
        const userId: string | null = this.authService.userId();
        if (!accessToken || !userId) return;

        const now: number = Date.now();
        if (!forceImmediate && now - this.lastSyncTime < SYNC_DEBOUNCE_MS) {
            if (this.debouncedSaveTimer === null) {
                const remaining = SYNC_DEBOUNCE_MS - (now - this.lastSyncTime);
                this.debouncedSaveTimer = setTimeout(() => {
                    this.debouncedSaveTimer = null;
                    void this.saveToDrive(true);
                }, remaining);
            }
            return;
        }

        if (this.syncInProgress) return;

        this.syncInProgress = true;
        this.isSyncing.set(true);
        this.ledgerStore.syncStatus.set('uploading');

        try {
            const clientId: string = this.getClientId();

            const lockAcquired: boolean = await acquireLock(
                accessToken,
                clientId,
                navigator.userAgent
            );
            if (!lockAcquired) {
                console.warn('[Sync] Could not acquire lock — another device is syncing');
                this.ledgerStore.syncStatus.set('error');
                this.ledgerStore.syncError.set('Another device is currently syncing');
                return;
            }

            try {
                // Check for remote changes and merge before uploading
                const driveFile: IDriveFile | null = await findDatabaseFile(accessToken);
                if (driveFile) {
                    const remoteEncrypted = await downloadDatabase(accessToken, driveFile.id);
                    const remoteDecrypted = await decryptDatabase(remoteEncrypted, userId);

                    const localDb = getDb();
                    if (localDb) {
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        const SQL: any = (localDb as any).constructor;
                        // SQL is the Database class itself — instantiate directly
                        const remoteDb = new SQL(remoteDecrypted);
                        try {
                            const lastSyncTime = getLastDriveSyncTime();
                            const mergeResult: IMergeResult =
                                await SQLiteMergeEngine.mergeRemoteIntoLocal(
                                    remoteDb,
                                    localDb,
                                    lastSyncTime
                                );
                            if (mergeResult.mergedCount > 0 || mergeResult.conflicts.length > 0) {
                                this.ledgerStore.syncStatus.set('merging');
                                await this.ledgerStore.loadFromEncryptedData(
                                    new Uint8Array(localDb.export())
                                );
                                this.ledgerStore.mergeCount.set(mergeResult.mergedCount);
                                if (mergeResult.conflicts.length > 0) {
                                    this.ledgerStore.syncConflicts.set(mergeResult.conflicts);
                                }
                            }
                        } finally {
                            remoteDb.close();
                        }
                    }
                }

                // Export, encrypt, upload
                await this.uploadToDrive(accessToken, userId, driveFile?.id ?? null);
                this.lastSyncTime = Date.now();
            } finally {
                await releaseLock(accessToken);
            }
        } catch (error: unknown) {
            if (error instanceof GDriveAuthError) {
                this.ledgerStore.authError.set(true);
                this.ledgerStore.syncStatus.set('pending-local');
            } else {
                console.error('[Sync] Failed to save to Drive:', error);
                this.ledgerStore.syncStatus.set('error');
                this.ledgerStore.syncError.set(
                    error instanceof Error ? error.message : 'Unknown error'
                );
                this.posthogService.posthog.capture('sync_failed', {
                    operation: 'save',
                    error_message: error instanceof Error ? error.message : 'Unknown error'
                });
            }
        } finally {
            this.syncInProgress = false;
            this.isSyncing.set(false);
        }
    }

    // ── Utility methods ───────────────────────────────────────────────────────

    async refreshLockStatus(): Promise<void> {
        const accessToken = this.authService.accessToken();
        if (!accessToken) return;
        try {
            const status = await getLockStatus(accessToken);
            this.ledgerStore.lockStatus.set(status);
        } catch (error) {
            console.error('[Sync] Failed to refresh lock status:', error);
        }
    }

    async forceReleaseSyncLock(): Promise<void> {
        const accessToken = this.authService.accessToken();
        if (!accessToken) return;
        try {
            await forceReleaseLock(accessToken);
            this.ledgerStore.lockStatus.set(null);
            this.ledgerStore.syncError.set(null);
        } catch (error) {
            console.error('[Sync] Failed to force release lock:', error);
        }
    }

    async flushPendingUpload(): Promise<void> {
        if (this.debouncedSaveTimer !== null) {
            clearTimeout(this.debouncedSaveTimer);
            this.debouncedSaveTimer = null;
        }
        return this.saveToDrive(true);
    }

    getSyncStatus(): ISyncStatus {
        return { inProgress: this.syncInProgress, lastSyncTime: this.lastSyncTime };
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    private async downloadAndMerge(
        accessToken: string,
        userId: string,
        driveFile: IDriveFile
    ): Promise<void> {
        this.ledgerStore.syncStatus.set('downloading');

        const encryptedData = await downloadDatabase(accessToken, driveFile.id);
        const decryptedData = await decryptDatabase(encryptedData, userId);

        if (!this.ledgerStore.isInitialized()) {
            // New device — load Drive data directly (no merge needed)
            await this.ledgerStore.loadFromEncryptedData(decryptedData);
            await saveLocalSnapshot(encryptedData, Date.now());
            this.ledgerStore.hasLocalFallback.set(true);
            this.ledgerStore.syncStatus.set('synced');
            this.ledgerStore.isDirty.set(false);
            saveLastDriveSyncTime(Date.now());
            this.posthogService.posthog.capture('data_loaded_from_drive', {
                source: 'drive',
                is_returning_user: true
            });
            return;
        }

        // Existing device — merge Drive into local
        this.ledgerStore.syncStatus.set('merging');
        const localDb = getDb();
        if (localDb) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const SQL: any = (localDb as any).constructor;
            // SQL is the Database class itself — instantiate directly
            const remoteDb = new SQL(decryptedData);
            try {
                const lastSyncTime = getLastDriveSyncTime();
                const mergeResult: IMergeResult = await SQLiteMergeEngine.mergeRemoteIntoLocal(
                    remoteDb,
                    localDb,
                    lastSyncTime
                );
                if (mergeResult.mergedCount > 0 || mergeResult.conflicts.length > 0) {
                    await this.ledgerStore.loadFromEncryptedData(new Uint8Array(localDb.export()));
                    this.ledgerStore.mergeCount.set(mergeResult.mergedCount);
                    if (mergeResult.conflicts.length > 0) {
                        this.ledgerStore.syncConflicts.set(mergeResult.conflicts);
                    }
                    this.posthogService.posthog.capture('data_merged_from_drive', {
                        merge_count: mergeResult.mergedCount,
                        conflict_count: mergeResult.conflicts.length
                    });
                }
            } finally {
                remoteDb.close();
            }
        }

        // Upload merged result back to Drive
        await this.uploadToDrive(accessToken, userId, driveFile.id);
    }

    private async uploadToDrive(
        accessToken: string,
        userId: string,
        driveFileId: string | null
    ): Promise<void> {
        this.ledgerStore.syncStatus.set('uploading');
        const dbExport = this.ledgerStore.exportForSync();
        const encrypted = await encryptDatabase(dbExport, userId);
        await uploadDatabase(accessToken, encrypted, driveFileId ?? undefined);
        const now = Date.now();
        await saveLocalSnapshot(encrypted, now);
        saveLastDriveSyncTime(now);
        this.ledgerStore.hasLocalFallback.set(true);
        this.ledgerStore.syncStatus.set('synced');
        this.ledgerStore.isDirty.set(false);
        this.ledgerStore.syncError.set(null);
    }

    private getClientId(): string {
        let clientId = localStorage.getItem('path-logic-client-id');
        if (!clientId) {
            clientId = `client-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
            localStorage.setItem('path-logic-client-id', clientId);
        }
        return clientId;
    }
}

import { DOCUMENT } from '@angular/common';
import { effect, inject, Injectable, signal } from '@angular/core';

export type ThemePreference = 'system' | 'light' | 'dark';
export type ResolvedTheme = 'light' | 'dark';

const STORAGE_KEY = 'pl.theme.preference';

/**
 * ThemeService — manages the three-state theme toggle.
 *
 * ## States
 *   - `system` (default): follows `prefers-color-scheme`. Reacts to OS
 *     theme changes in real time via a `matchMedia` change listener.
 *   - `light`: always light, regardless of OS setting.
 *   - `dark`: always dark, regardless of OS setting.
 *
 * ## Persistence
 *   Uses `localStorage` directly (not IndexedDB / UserSettingsStore) so
 *   the preference is always available synchronously at bootstrap — before
 *   the SQLite database has been initialized. This avoids the
 *   "Database not initialized" error on cold starts.
 *
 * ## Implementation
 *   Sets `data-theme="light" | "dark"` on `<html>`. CSS custom properties
 *   in `styles.css` respond to this attribute. This approach (Option B) is
 *   independent of PrimeNG's own theming system.
 */
@Injectable({ providedIn: 'root' })
export class ThemeService {
    private readonly document = inject(DOCUMENT);

    /** The user's saved preference: system | light | dark */
    readonly preference = signal<ThemePreference>('system');

    /** The currently applied resolved theme (always light or dark) */
    readonly resolvedTheme = signal<ResolvedTheme>('dark');

    private osMediaQuery: MediaQueryList | null = null;
    private osChangeHandler: ((e: MediaQueryListEvent) => void) | null = null;

    constructor() {
        this.initialize();

        // Re-apply whenever preference signal changes
        effect(() => {
            this.applyTheme(this.preference());
        });
    }

    /** Sets the user's theme preference and persists it to localStorage. */
    setTheme(preference: ThemePreference): void {
        try {
            localStorage.setItem(STORAGE_KEY, preference);
        } catch {
            // localStorage may be unavailable in some private browsing modes
        }
        this.preference.set(preference);
    }

    private initialize(): void {
        let saved: ThemePreference | null = null;
        try {
            saved = localStorage.getItem(STORAGE_KEY) as ThemePreference | null;
        } catch {
            // Ignore — fall back to system
        }
        // Validate the stored value is still a known preference
        const valid: Array<ThemePreference> = ['system', 'light', 'dark'];
        this.preference.set(
            valid.includes(saved as ThemePreference) ? (saved as ThemePreference) : 'system'
        );
    }

    private applyTheme(preference: ThemePreference): void {
        // Clean up any existing OS listener before setting up a new state
        this.teardownOsListener();

        const resolved = this.resolve(preference);
        this.setDataTheme(resolved);

        // When set to 'system', listen for real-time OS changes
        if (preference === 'system') {
            this.setupOsListener();
        }
    }

    private resolve(preference: ThemePreference): ResolvedTheme {
        if (preference === 'system') {
            return this.getOsTheme();
        }
        return preference;
    }

    private getOsTheme(): ResolvedTheme {
        const mq = this.document.defaultView?.matchMedia?.('(prefers-color-scheme: dark)');
        return mq?.matches ? 'dark' : 'light';
    }

    private setDataTheme(theme: ResolvedTheme): void {
        this.document.documentElement.setAttribute('data-theme', theme);
        this.resolvedTheme.set(theme);
    }

    private setupOsListener(): void {
        const view = this.document.defaultView;
        if (!view || typeof view.matchMedia !== 'function') return;

        this.osMediaQuery = view.matchMedia('(prefers-color-scheme: dark)');
        this.osChangeHandler = (e: MediaQueryListEvent): void => {
            this.setDataTheme(e.matches ? 'dark' : 'light');
        };
        this.osMediaQuery.addEventListener('change', this.osChangeHandler);
    }

    private teardownOsListener(): void {
        if (this.osMediaQuery && this.osChangeHandler) {
            this.osMediaQuery.removeEventListener('change', this.osChangeHandler);
            this.osMediaQuery = null;
            this.osChangeHandler = null;
        }
    }
}

import type { WritableSignal } from '@angular/core';
import { effect, inject, Injectable, signal } from '@angular/core';

import {
    getAllUserSettings,
    getUserSetting,
    setUserSetting
} from '../../lib/storage/SQLiteAdapter';
import { LedgerStore } from '../ledger-store/ledger.store';

/**
 * Angular signal-based user settings store.
 * Replaces the Zustand `useUserStore`.
 *
 * Provides a reactive wrapper around the SQLite user_settings table.
 */
@Injectable({ providedIn: 'root' })
export class UserSettingsStore {
    readonly settings: WritableSignal<Record<string, string>> = signal<Record<string, string>>({});
    readonly isLoading: WritableSignal<boolean> = signal<boolean>(false);

    private readonly ledgerStore = inject(LedgerStore);

    constructor() {
        effect(() => {
            if (this.ledgerStore.isInitialized()) {
                try {
                    const all = getAllUserSettings();
                    this.settings.set(all);
                } catch (err) {
                    console.error('Failed to pre-load settings from DB:', err);
                }
            }
        });
    }

    getSetting(key: string, defaultValue?: string): string | undefined {
        const current: Record<string, string> = this.settings();
        if (current[key] !== undefined) return current[key];

        // Try DB
        try {
            const value: string | null = getUserSetting(key);
            if (value !== null) {
                return value;
            }
        } catch {
            // Database might not be initialized yet on app startup
        }

        return defaultValue;
    }

    async updateSetting(key: string, value: string): Promise<void> {
        this.settings.update(
            (s: Record<string, string>): Record<string, string> => ({
                ...s,
                [key]: value
            })
        );

        try {
            setUserSetting(key, value);
            await this.ledgerStore.commitToLocal();
        } catch (err: unknown) {
            console.error('Failed to update setting in DB:', err);
        }
    }
}

