import { CommonModule } from '@angular/common';
import {
    ChangeDetectionStrategy,
    Component,
    computed,
    effect,
    inject,
    input,
    output,
    signal,
    viewChild
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';

import type { IAccount, ISODateString } from '@core';
import { AccountType, TypeGuards } from '@core';
import { Button } from 'primeng/button';
import { Dialog } from 'primeng/dialog';
import { Step, StepList, StepPanel, StepPanels, Stepper } from 'primeng/stepper';
import { CategoryMappingDialogComponent } from '../../ledger/category-mapping-dialog/category-mapping-dialog.component';

import { ImportOrchestrationService } from '../../../services/import/import-orchestration.service';
import { PostHogService } from '../../../services/posthog/posthog.service';
import { LoanDetailsFormComponent } from '../loan-details-form/loan-details-form.component';

/**
 * Wizard step types.
 */
type WizardStep = 'select-type' | 'enter-details' | 'import-data' | 'creating';

/**
 * Account type option for the wizard.
 */
interface IAccountTypeOption {
    type: AccountType;
    icon: string;
    label: string;
    description: string;
}

const PRIMARY_TYPES: Array<IAccountTypeOption> = [
    {
        type: AccountType.Checking,
        icon: 'pi-building-columns',
        label: 'Checking',
        description: 'Daily spending & income'
    },
    {
        type: AccountType.Savings,
        icon: 'pi-money-bill',
        label: 'Savings',
        description: 'Long-term goals'
    },
    {
        type: AccountType.Credit,
        icon: 'pi-credit-card',
        label: 'Credit Card',
        description: 'Track spending & debt'
    },
    {
        type: AccountType.Cash,
        icon: 'pi-wallet',
        label: 'Cash',
        description: 'Physical currency'
    }
];

const LOAN_TYPES: Array<IAccountTypeOption> = [
    {
        type: AccountType.Mortgage,
        icon: 'pi-home',
        label: 'Mortgage',
        description: 'Home loan & equity'
    },
    {
        type: AccountType.AutoLoan,
        icon: 'pi-car',
        label: 'Auto Loan',
        description: 'Vehicle financing'
    },
    {
        type: AccountType.PersonalLoan,
        icon: 'pi-receipt',
        label: 'Personal Loan',
        description: 'Unsecured debt'
    }
];

/**
 * Styling and theming for account types.
 */
const TYPE_THEMING: Record<
    string,
    { accentBg: string; borderHover: string; iconText: string; iconBg: string; iconBorder: string }
> = {
    [AccountType.Checking]: {
        accentBg: 'bg-teal-500',
        borderHover: 'border-teal-500/30 hover:border-teal-500',
        iconText: 'text-teal-600 dark:text-teal-400',
        iconBg: 'bg-teal-500/10',
        iconBorder: 'border-teal-500/20'
    },
    [AccountType.Savings]: {
        accentBg: 'bg-blue-500',
        borderHover: 'border-blue-500/30 hover:border-blue-500',
        iconText: 'text-blue-600 dark:text-blue-400',
        iconBg: 'bg-blue-500/10',
        iconBorder: 'border-blue-500/20'
    },
    [AccountType.Credit]: {
        accentBg: 'bg-purple-500',
        borderHover: 'border-purple-500/30 hover:border-purple-500',
        iconText: 'text-purple-600 dark:text-purple-400',
        iconBg: 'bg-purple-500/10',
        iconBorder: 'border-purple-500/20'
    },
    [AccountType.Cash]: {
        accentBg: 'bg-green-500',
        borderHover: 'border-green-500/30 hover:border-green-500',
        iconText: 'text-green-600 dark:text-green-400',
        iconBg: 'bg-green-500/10',
        iconBorder: 'border-green-500/20'
    },
    [AccountType.Mortgage]: {
        accentBg: 'bg-amber-500',
        borderHover: 'border-amber-500/30 hover:border-amber-500',
        iconText: 'text-amber-600 dark:text-amber-400',
        iconBg: 'bg-amber-500/10',
        iconBorder: 'border-amber-500/20'
    },
    [AccountType.AutoLoan]: {
        accentBg: 'bg-amber-500',
        borderHover: 'border-amber-500/30 hover:border-amber-500',
        iconText: 'text-amber-600 dark:text-amber-400',
        iconBg: 'bg-amber-500/10',
        iconBorder: 'border-amber-500/20'
    },
    [AccountType.PersonalLoan]: {
        accentBg: 'bg-amber-500',
        borderHover: 'border-amber-500/30 hover:border-amber-500',
        iconText: 'text-amber-600 dark:text-amber-400',
        iconBg: 'bg-amber-500/10',
        iconBorder: 'border-amber-500/20'
    }
};

/**
 * Dialog for creating a new account.
 * Guides the user through type selection, configuration, and optional initial data import.
 */
@Component({
    selector: 'new-account-dialog',
    standalone: true,
    imports: [
        CommonModule,
        FormsModule,
        LoanDetailsFormComponent,
        Stepper,
        StepList,
        StepPanels,
        Step,
        StepPanel,
        Button,
        Dialog,
        CategoryMappingDialogComponent
    ],
    templateUrl: './new-account-dialog.component.html',
    styleUrls: ['./new-account-dialog.component.css'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class NewAccountDialogComponent {
    private readonly posthogService = inject(PostHogService);
    readonly importService = inject(ImportOrchestrationService);
    private readonly router = inject(Router);

    /** Reference to the embedded loan-details-form for triggering submit from the dialog footer. */
    readonly loanFormRef = viewChild(LoanDetailsFormComponent);

    // Inputs
    readonly isOpen = input.required<boolean>();

    // Outputs
    readonly closed = output();
    readonly accountCreated = output<IAccount>();

    // State
    readonly step = signal<WizardStep>('select-type');
    readonly selectedType = signal<AccountType | null>(null);
    readonly showLoans = signal<boolean>(false);
    readonly accountName = signal<string>('');
    readonly institutionName = signal<string>('');
    readonly initialBalance = signal<string>('');
    readonly error = signal<string | null>(null);

    /** The newly-created account — populated after handleCreate() succeeds */
    readonly createdAccount = signal<IAccount | null>(null);

    /** Tracks drag-over state for the drop zone */
    readonly isDropZoneActive = signal<boolean>(false);
    readonly isNavigating = signal<boolean>(false);
    readonly loanShouldImport = signal<boolean>(false);

    // Computed
    readonly stepValue = computed(() => {
        switch (this.step()) {
            case 'select-type':
                return 1;
            case 'enter-details':
                return 2;
            case 'creating':
                return 2;
            case 'import-data':
                return 3;
            default:
                return 1;
        }
    });

    readonly primaryTypes = signal(PRIMARY_TYPES);
    readonly loanTypes = signal(LOAN_TYPES);

    readonly selectedOption = computed(() => {
        const type = this.selectedType();
        if (!type) return null;
        return [...PRIMARY_TYPES, ...LOAN_TYPES].find(opt => opt.type === type) || null;
    });

    readonly theming = computed(() => {
        const type = this.selectedType();
        if (!type || !TYPE_THEMING[type]) {
            return {
                accentBg: 'bg-primary',
                borderHover: 'border-primary/30',
                iconText: 'text-primary',
                iconBg: 'bg-primary/10',
                iconBorder: 'border-primary/20'
            };
        }
        return TYPE_THEMING[type];
    });

    readonly isLoan = computed(() => {
        const type = this.selectedType();
        return type ? TypeGuards.isLoanAccount(type) : false;
    });

    readonly importProgress = this.importService.progress;
    readonly importStats = this.importService.stats;
    readonly importDone = computed(() => this.importService.progress().stage === 'done');

    /** Whether the standard (non-loan) form has enough data to create an account. */
    readonly isFormValid = computed(() => {
        return this.accountName().trim().length > 0;
    });

    /** Whether the loan form is valid — bridges to the child loanForm's FormGroup validity. */
    readonly isLoanFormValid = computed(() => {
        const ref = this.loanFormRef();
        return ref ? ref.isValid() : false;
    });

    constructor() {
        // Reset state when closing
        effect(() => {
            if (!this.isOpen()) {
                this.step.set('select-type');
                this.selectedType.set(null);
                this.accountName.set('');
                this.institutionName.set('');
                this.initialBalance.set('');
                this.error.set(null);
                this.createdAccount.set(null);
            } else {
                this.importService.reset();
            }
        });
    }

    handleTypeSelect(type: AccountType): void {
        this.selectedType.set(type);
        this.step.set('enter-details');
        this.error.set(null);

        const defaultNames: Record<string, string> = {
            [AccountType.Checking]: 'Main Checking',
            [AccountType.Savings]: 'Savings',
            [AccountType.Credit]: 'Credit Card',
            [AccountType.Cash]: 'Cash'
        };
        const defaultName = defaultNames[type];
        if (defaultName) {
            this.accountName.set(defaultName);
        }
    }

    async handleCreate(goToImport = false): Promise<void> {
        if (!this.accountName().trim()) {
            this.error.set('Account name is required');
            return;
        }

        this.error.set(null);
        this.step.set('creating');

        try {
            const type = this.selectedType();
            if (!type) {
                this.error.set('Account type is required');
                this.step.set('select-type');
                return;
            }
            const now = new Date().toISOString() as ISODateString;
            let val = parseFloat(this.initialBalance() || '0');

            if (this.selectedType() === AccountType.Credit) {
                val = -Math.abs(val);
            } else {
                val = Math.abs(val);
            }

            const balanceCents = Math.round(val * 100);

            const newAccount: IAccount = {
                id: `acc-${Date.now()}`,
                name: this.accountName().trim(),
                type: type,
                institutionName: this.institutionName().trim(),
                clearedBalance: balanceCents,
                pendingBalance: balanceCents,
                isActive: true,
                deletedAt: null,
                createdAt: now,
                updatedAt: now
            };

            this.createdAccount.set(newAccount);
            this.accountCreated.emit(newAccount);
            this.posthogService.posthog.capture('account_created', {
                account_type: type,
                has_institution_name: !!this.institutionName().trim(),
                has_initial_balance: !!this.initialBalance(),
                will_import: goToImport
            });

            if (goToImport) {
                this.importService.reset();
                this.step.set('import-data');
            } else {
                this.closed.emit();
            }
        } catch {
            this.error.set('Failed to create account');
            this.step.set('enter-details');
        }
    }

    // ── Import step helpers ───────────────────────────────────────────────────

    onDropZoneDragOver(event: DragEvent): void {
        event.preventDefault();
        this.isDropZoneActive.set(true);
    }

    onDropZoneDragLeave(): void {
        this.isDropZoneActive.set(false);
    }

    onDropZoneDrop(event: DragEvent): void {
        event.preventDefault();
        this.isDropZoneActive.set(false);
        const file = event.dataTransfer?.files[0];
        if (file) this.startImportFromFile(file);
    }

    onImportFileSelected(event: Event): void {
        const input = event.target as HTMLInputElement;
        const file = input.files?.[0];
        if (file) this.startImportFromFile(file);
        input.value = '';
    }

    private startImportFromFile(file: File): void {
        const accountId = this.createdAccount()?.id ?? '';
        this.importService.startImport(file, accountId);
    }

    skipImport(): void {
        this.importService.reset();
        this.closed.emit();
    }

    async finishAfterImport(): Promise<void> {
        this.isNavigating.set(true);
        const accountId = this.createdAccount()?.id;

        if (accountId) {
            try {
                await this.importService.commitImport(accountId);
            } catch (err) {
                console.error('Failed to commit imported transactions:', err);
            }
        }

        setTimeout(() => {
            if (accountId) {
                void this.router.navigate(['/accounts', accountId]).then(() => {
                    this.closed.emit();
                    this.isNavigating.set(false);
                });
            } else {
                this.closed.emit();
                this.isNavigating.set(false);
            }
        }, 50);
    }

    handleCancel(): void {
        this.closed.emit();
    }

    getTypeTheming(type: AccountType): {
        accentBg: string;
        borderHover: string;
        iconText: string;
        iconBg: string;
        iconBorder: string;
    } {
        return (
            TYPE_THEMING[type] || {
                accentBg: 'bg-primary',
                borderHover: 'border-primary/30',
                iconText: 'text-primary',
                iconBg: 'bg-primary/10',
                iconBorder: 'border-primary/20'
            }
        );
    }

    onStepValueChange(value: number | undefined): void {
        if (value === undefined) return;
        if (value === 1) {
            this.step.set('select-type');
        } else if (value === 2) {
            this.step.set('enter-details');
        } else if (value === 3) {
            this.step.set('import-data');
        }
    }

    submitLoanForm(shouldImport: boolean): void {
        this.loanShouldImport.set(shouldImport);
        void this.loanFormRef()?.handleSubmit();
    }

    handleLoanSubmitted(newAccount: IAccount): void {
        this.createdAccount.set(newAccount);
        this.accountCreated.emit(newAccount);
        this.posthogService.posthog.capture('account_created', {
            account_type: newAccount.type,
            has_institution_name: !!newAccount.institutionName?.trim(),
            has_initial_balance: true,
            will_import: this.loanShouldImport()
        });

        if (this.loanShouldImport()) {
            this.importService.reset();
            this.step.set('import-data');
        } else {
            this.closed.emit();
        }
    }

    // Lucide Icons
}

import { CommonModule } from '@angular/common';
import {
    ChangeDetectionStrategy,
    Component,
    forwardRef,
    inject,
    input,
    signal
} from '@angular/core';
import type { ControlValueAccessor } from '@angular/forms';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import type { IPayee } from '@core';
import { AutoCompleteModule } from 'primeng/autocomplete';
import { LedgerStore } from '../../../services/ledger-store/ledger.store';

@Component({
    selector: 'payee-autocomplete',
    standalone: true,
    imports: [CommonModule, FormsModule, AutoCompleteModule],
    template: `
        <p-autoComplete
            [ariaLabel]="ariaLabel()"
            [attr.aria-label]="ariaLabel()"
            [inputId]="inputId()"
            [(ngModel)]="value"
            (ngModelChange)="onValueChange($event)"
            [suggestions]="filteredPayees()"
            (completeMethod)="filterPayees($event)"
            optionLabel="name"
            [name]="name()"
            [placeholder]="placeholder()"
            [styleClass]="styleClass()"
            [inputStyleClass]="inputStyleClass()"
            [forceSelection]="false"
            [dropdown]="false"
            appendTo="body"
        >
            <ng-template let-payee pTemplate="item">
                <div class="flex items-center gap-2 px-1">
                    @if (payee.isNew) {
                        <i class="pi pi-plus-circle text-primary text-xs"></i>
                        <span class="text-sm font-bold text-primary">Add '{{ payee.name }}'</span>
                    } @else {
                        <i class="pi pi-building text-surface-400 text-xs"></i>
                        <span class="text-sm">{{ payee.name }}</span>
                    }
                </div>
            </ng-template>
        </p-autoComplete>
    `,
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => PayeeAutocompleteComponent),
            multi: true
        }
    ],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class PayeeAutocompleteComponent implements ControlValueAccessor {
    private ledgerStore = inject(LedgerStore);

    readonly ariaLabel = input<string>('Payee');
    readonly name = input<string>('payee');
    readonly inputId = input<string>('');
    readonly placeholder = input<string>('');
    readonly styleClass = input<string>('w-full h-full');
    readonly inputStyleClass = input<string>(
        'w-full h-full text-sm font-medium px-3 bg-surface-0/60 border border-surface-200/60 text-surface-900 rounded-sm focus:outline-none focus:ring-1 focus:ring-primary shadow backdrop-blur-sm'
    );

    readonly payees = this.ledgerStore.payees;
    readonly filteredPayees = signal<Array<IPayee | { name: string; isNew: boolean }>>([]);

    value: unknown = null;
    disabled = false;

    onChange: (val: unknown) => void = () => {
        // Placeholder for ControlValueAccessor callback
    };

    onTouched: () => void = () => {
        // Placeholder for ControlValueAccessor callback
    };

    writeValue(val: unknown): void {
        this.value = val;
    }

    registerOnChange(fn: (val: unknown) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        this.disabled = isDisabled;
    }

    onValueChange(val: unknown): void {
        this.value = val;
        this.onChange(val);
        this.onTouched();
    }

    filterPayees(event: { query?: string; originalEvent?: Event }): void {
        const query = (event.query || '').toLowerCase();
        const matches = this.payees().filter(p => p.name.toLowerCase().includes(query));

        const exactMatch = matches.find(p => p.name.toLowerCase() === query);
        if (!exactMatch && query.length > 0 && event.query) {
            matches.unshift({ name: event.query, isNew: true } as unknown as IPayee);
        }

        this.filteredPayees.set(matches);
    }
}

import { CommonModule } from '@angular/common';
import {
    ChangeDetectionStrategy,
    Component,
    effect,
    inject,
    input,
    model,
    output,
    signal
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import type { IPayee, ISODateString } from '@core';
import { ButtonModule } from 'primeng/button';
import { DialogModule } from 'primeng/dialog';

import { LedgerStore } from '../../../services/ledger-store/ledger.store';

/**
 * Dialog for creating or editing a payee record.
 * Supports both "add" (no initial payee) and "edit" (pre-populated) modes.
 */
@Component({
    selector: 'payee-edit-dialog',
    standalone: true,
    imports: [CommonModule, FormsModule, DialogModule, ButtonModule],
    templateUrl: './payee-edit-dialog.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class PayeeEditDialogComponent {
    private readonly ledgerStore = inject(LedgerStore);

    /** Two-way binding for dialog visibility */
    readonly isOpen = model<boolean>(false);

    /**
     * Pass an existing payee to edit, or null/undefined to create a new one.
     * The component deep-copies the data to avoid mutating the store directly.
     */
    readonly payeeToEdit = input<IPayee | null>(null);

    /** Emitted when a payee has been saved (added or updated). */
    readonly saved = output<IPayee>();

    // Form state (as signals for OnPush)
    readonly name = signal<string>('');
    readonly address = signal<string>('');
    readonly city = signal<string>('');
    readonly state = signal<string>('');
    readonly zipCode = signal<string>('');
    readonly phone = signal<string>('');
    readonly website = signal<string>('');
    readonly notes = signal<string>('');
    readonly isSaving = signal<boolean>(false);
    readonly error = signal<string | null>(null);

    readonly isEditMode = signal<boolean>(false);

    constructor() {
        // Populate form when the payeeToEdit input changes
        effect(() => {
            const p = this.payeeToEdit();
            this.isEditMode.set(!!p);
            this.name.set(p?.name ?? '');
            this.address.set(p?.address ?? '');
            this.city.set(p?.city ?? '');
            this.state.set(p?.state ?? '');
            this.zipCode.set(p?.zipCode ?? '');
            this.phone.set(p?.phone ?? '');
            this.website.set(p?.website ?? '');
            this.notes.set(p?.notes ?? '');
            this.error.set(null);
        });
    }

    get dialogHeader(): string {
        return this.isEditMode() ? 'Edit Payee' : 'Add Payee';
    }

    async handleSave(): Promise<void> {
        const name = this.name().trim();
        if (!name) {
            this.error.set('Payee name is required.');
            return;
        }

        this.isSaving.set(true);
        this.error.set(null);

        try {
            const now = new Date().toISOString() as ISODateString;
            const existing = this.payeeToEdit();

            const payee: IPayee = {
                id:
                    existing?.id ??
                    `payee-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
                name,
                address: this.address().trim() || null,
                city: this.city().trim() || null,
                state: this.state().trim() || null,
                zipCode: this.zipCode().trim() || null,
                latitude: existing?.latitude ?? null,
                longitude: existing?.longitude ?? null,
                phone: this.phone().trim() || null,
                website: this.website().trim() || null,
                notes: this.notes().trim() || null,
                defaultCategoryId: existing?.defaultCategoryId ?? null,
                createdAt: existing?.createdAt ?? now,
                updatedAt: now
            };

            if (this.isEditMode()) {
                await this.ledgerStore.updatePayee(payee);
            } else {
                // Use getOrCreatePayee for the add path so we don't dupe by name
                await this.ledgerStore.getOrCreatePayee(name);
                // Then update with the full data
                const created = this.ledgerStore.payees().find(p => p.name === name);
                if (created) {
                    const withDetails: IPayee = { ...created, ...payee, id: created.id };
                    await this.ledgerStore.updatePayee(withDetails);
                    this.saved.emit(withDetails);
                    this.isOpen.set(false);
                    return;
                }
            }

            this.saved.emit(payee);
            this.isOpen.set(false);
        } catch (err) {
            this.error.set(err instanceof Error ? err.message : 'Failed to save payee.');
        } finally {
            this.isSaving.set(false);
        }
    }

    handleCancel(): void {
        this.isOpen.set(false);
    }
}

import { CommonModule } from '@angular/common';
import type { OnInit } from '@angular/core';
import { Component, computed, inject, input, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';

import { AppShellComponent } from '../../../components/layout/app-shell/app-shell.component';
import type { IPayee } from '../../../core/domain/types';
import { LedgerStore } from '../../../services/ledger-store/ledger.store';

@Component({
    selector: 'payee-form',
    standalone: true,
    imports: [CommonModule, FormsModule, RouterModule, AppShellComponent],
    templateUrl: './payee-form.component.html'
})
export class PayeeFormComponent implements OnInit {
    private readonly route = inject(ActivatedRoute);
    private readonly router = inject(Router);
    readonly ledgerStore = inject(LedgerStore);

    // Optional input if embedded in a desktop modal
    readonly initialPayee = input<IPayee | null | undefined>(null);

    // Form signals
    readonly payeeId = signal<string | null>(null);
    readonly name = signal<string>('');
    readonly defaultCategoryId = signal<string>('');
    readonly notes = signal<string>('');
    readonly isSubmitting = signal<boolean>(false);
    readonly errorMessage = signal<string | null>(null);

    // Computed states
    readonly isEditMode = computed(() => !!this.payeeId());
    readonly categories = computed(() => this.ledgerStore.categories());

    ngOnInit(): void {
        const raw = this.initialPayee;
        const inputPayee =
            typeof raw === 'function'
                ? (raw as () => IPayee | null | undefined)()
                : (raw as unknown as IPayee | null);
        if (inputPayee) {
            this.loadPayee(inputPayee);
            return;
        }

        // Check route params
        this.route.paramMap.subscribe(params => {
            const id = params.get('id');
            if (id) {
                this.payeeId.set(id);
                const existing = this.ledgerStore.payees().find(p => p.id === id);
                if (existing) {
                    this.loadPayee(existing);
                }
            }
        });

        // Check query params for initial values
        this.route.queryParams.subscribe(qParams => {
            if (!this.payeeId()) {
                if (qParams['name']) {
                    this.name.set(qParams['name']);
                }
                if (qParams['defaultCategoryId']) {
                    this.defaultCategoryId.set(qParams['defaultCategoryId']);
                }
            }
        });
    }

    loadPayee(payee: IPayee): void {
        this.payeeId.set(payee.id);
        this.name.set(payee.name || '');
        this.defaultCategoryId.set(payee.defaultCategoryId || '');
        this.notes.set(payee.notes || '');
    }

    async handleSave(): Promise<void> {
        const trimmedName = this.name().trim();
        if (!trimmedName) {
            this.errorMessage.set('Name is required');
            return;
        }

        this.isSubmitting.set(true);
        this.errorMessage.set(null);

        try {
            const currentId = this.payeeId();
            const now = new Date().toISOString();
            if (currentId) {
                const existing = this.ledgerStore.payees().find(p => p.id === currentId);
                const updatedPayee: IPayee = {
                    id: currentId,
                    name: trimmedName,
                    defaultCategoryId: this.defaultCategoryId().trim() || null,
                    notes: this.notes().trim() || null,
                    address: existing?.address || null,
                    city: existing?.city || null,
                    state: existing?.state || null,
                    zipCode: existing?.zipCode || null,
                    latitude: existing?.latitude || null,
                    longitude: existing?.longitude || null,
                    website: existing?.website || null,
                    phone: existing?.phone || null,
                    createdAt: existing?.createdAt || now,
                    updatedAt: now
                };
                await this.ledgerStore.updatePayee(updatedPayee);
            } else {
                const created = await this.ledgerStore.getOrCreatePayee(trimmedName);
                if (this.defaultCategoryId().trim() || this.notes().trim()) {
                    await this.ledgerStore.updatePayee({
                        ...created,
                        defaultCategoryId: this.defaultCategoryId().trim() || null,
                        notes: this.notes().trim() || null,
                        updatedAt: now
                    });
                }
            }

            void this.router.navigate(['/payees']);
        } catch (err: unknown) {
            console.error('Failed to save payee:', err);
            this.errorMessage.set('Failed to save payee. Please check your data and try again.');
        } finally {
            this.isSubmitting.set(false);
        }
    }

    handleCancel(): void {
        void this.router.navigate(['/payees']);
    }
}

