export interface IPaycheckFormState {
    grossPay: number;
    federalTax?: number;
    stateTax?: number;
    localTax?: number;
    socialSecurity?: number;
    medicare?: number;
    healthInsurance?: number;
    visionInsurance?: number;
    dentalInsurance?: number;
    fourOhOneK?: number;
    hsa?: number;
    otherDeductions?: Array<{ memo: string; amount: number; categoryId?: string }>;
