    selector: 'settings-page',
    standalone: true,
    imports: [
        CommonModule,
        AppShellComponent,
        FeatureFlagToggleComponent,
        ExportDialogComponent,
        ImportDialogComponent,
        ExportManagerDialogComponent
    ],
