/* ── Today Divider ─────────────────────────────────────────────────── */

/**
 * Absolutely-positioned divider that marks the boundary between past
 * and future transactions. Aligned to the first future row's Y offset
 * via translateY in the template.
 *
 * Height is 0 so it doesn't shift row layout — the visual sits on top
 * of the row boundary via negative translate.
 */
.today-divider {
    height: 0;
    overflow: visible;
    transform-origin: top left;
    /* Shift up by half the label height so the line sits between rows */
    margin-top: -10px;
}

