app/src/app/core/parsers/QIFExporter.ts.defaultValue:
{
    /**
     * Exports an account and its transactions to QIF format.
     */
    exportAccount: (account: IAccount, transactions: Array<ITransaction>): string => {
        const lines: Array<string> = [];

        // 1. Account Header
        lines.push('!Account');
        lines.push(`N${account.name}`);
        lines.push(`T${mapAccountType(account.type)}`);
        lines.push('^');

        // 2. Transaction Header
        lines.push(`!Type:${mapAccountType(account.type)}`);

        // 3. Transactions
        for (const tx of transactions) {
            lines.push(`D${formatDate(tx.date)}`);
            lines.push(`T${(tx.totalAmount / 100).toFixed(2)}`);
            lines.push(`P${tx.payee}`);

            if (tx.memo) {
                lines.push(`M${tx.memo}`);
            }

            if (tx.checkNumber) {
                lines.push(`N${tx.checkNumber}`);
            }

            // Splits
            if (tx.splits.length > 1) {
                for (const split of tx.splits) {
                    lines.push(`S${split.categoryId || ''}`);
                    lines.push(`E${split.memo || ''}`);
                    lines.push(`$${(split.amount / 100).toFixed(2)}`);
                }
            } else if (tx.splits[0]) {
                // Single category
                lines.push(`L${tx.splits[0].categoryId || ''}`);
            }

            lines.push('^');
        }

        return lines.join('\n');
    }
}

app/src/app/core/engine/ReconciliationEn.defaultValue:
{
    /**
     * Matches a list of parsed transactions against an existing set of transactions.
     *
     * @param parsedTransactions Transactions from an external source (e.g. QIF).
     * @param existingTransactions Existing transactions in the specific account.
     * @param options Configuration for matching sensitivity.
     */
    reconcile: (
        parsedTransactions: Array<IParsedTransaction>,
        existingTransactions: Array<
            ITransaction | { id: string; date: string; totalAmount: number; importHash: string }
        >,
        options: { fuzzyDateRangeDays: number } = { fuzzyDateRangeDays: 5 }
    ): Array<IReconciliationMatch> => {
        const results: Array<IReconciliationMatch> = [];

        for (const parsed of parsedTransactions) {
            // 1. Exact match by importHash
            const exactMatch = existingTransactions.find(tx => tx.importHash === parsed.importHash);
            if (exactMatch) {
                results.push({
                    type: 'exact',
                    parsedTx: parsed,
                    existingTxId: exactMatch.id,
                    confidence: 1.0
                });
                continue;
            }

            // 2. Fuzzy match by Date (within range) and Amount (exact)
            // This handles manual entries vs cleared bank transactions.
            const fuzzyMatch = existingTransactions.find(tx => {
                const txDate = new Date(tx.date).getTime();
                const parsedDate = new Date(parsed.date).getTime();
                const dateDiff = Math.abs(txDate - parsedDate) / (1000 * 60 * 60 * 24);

                const amountMatch = tx.totalAmount === parsed.amount;

                return dateDiff <= options.fuzzyDateRangeDays && amountMatch;
            });

            if (fuzzyMatch) {
                results.push({
                    type: 'fuzzy',
                    parsedTx: parsed,
                    existingTxId: fuzzyMatch.id,
                    confidence: 0.8
                });
                continue;
            }

            // 3. No match found
            results.push({
                type: 'none',
                parsedTx: parsed,
                confidence: 0
            });
        }

        return results;
    }
}

app/src/app/core/engine/RecurringEngine..defaultValue:
{
    /**
     * Calculates the next due date after the provided target date.
     */
    calculateNextDueDate(
        startDate: ISODateString,
        frequency: Frequency,
        lastDueDate?: ISODateString
    ): ISODateString {
        const baseDateString = lastDueDate || startDate;
        const baseDate = new Date(baseDateString + 'T00:00:00Z');

        switch (frequency) {
            case Frequency.Daily:
                return this.addDays(baseDate, 1);
            case Frequency.Weekly:
                return this.addDays(baseDate, 7);
            case Frequency.Biweekly:
                return this.addDays(baseDate, 14);
            case Frequency.EveryFourWeeks:
                return this.addDays(baseDate, 28);
            case Frequency.Monthly:
                return this.addMonths(baseDate, 1);
            case Frequency.TwiceAMonth:
                return this.calculateNextSemiMonthly(baseDate);
            case Frequency.Bimonthly:
                return this.addMonths(baseDate, 2);
            case Frequency.Quarterly:
                return this.addMonths(baseDate, 3);
            case Frequency.Yearly:
                return this.addMonths(baseDate, 12);
            default:
                return baseDateString;
        }
    },

    /**
     * Determines if a schedule is due on a specific date.
     */
    isDueOnDate(schedule: IRecurringSchedule, targetDate: ISODateString): boolean {
        if (!schedule.isActive) return false;
        // Ensure frequency is supported
        if (!Object.values(Frequency).includes(schedule.frequency as Frequency)) return false;
        if (targetDate < schedule.startDate) return false;
        if (schedule.endDate && targetDate > schedule.endDate) return false;

        // For simple implementations, we check if targetDate is reachable from startDate via frequency
        // In a real system, we'd iterate or use more complex modulus math across month boundaries
        let checkDate = schedule.startDate;
        while (checkDate <= targetDate) {
            if (checkDate === targetDate) return true;
            const next = this.calculateNextDueDate(
                schedule.startDate,
                schedule.frequency,
                checkDate
            );
            if (next === checkDate) break; // Prevent infinite loop
            checkDate = next;
        }

        return false;
    },

    /**
     * Calculates how many occurrences are between nextDueDate and today.
     */
    getOverdueCount(schedule: IRecurringSchedule, today: ISODateString): number {
        if (!schedule.isActive || schedule.nextDueDate > today) return 0;

        let count = 0;
        let checkDate = schedule.nextDueDate;

        while (checkDate <= today) {
            count++;
            const next = this.calculateNextDueDate(
                schedule.startDate,
                schedule.frequency,
                checkDate
            );
            if (next <= checkDate) break;
            checkDate = next;

            // Safety break to prevent infinite loops in tests
            if (count > 1000) break;
        }

        return count;
    },

    addDays(date: Date, days: number): ISODateString {
        const result = new Date(date);
        result.setUTCDate(result.getUTCDate() + days);
        return result.toISOString().split('T')[0] as ISODateString;
    },

    addMonths(date: Date, months: number): ISODateString {
        const result = new Date(date);
        const dayOfMonth = result.getUTCDate();
        result.setUTCMonth(result.getUTCMonth() + months);

        // Handle month-end issues (e.g., Jan 31 -> Feb 28)
        if (result.getUTCDate() !== dayOfMonth) {
            result.setUTCDate(0);
        }
        return result.toISOString().split('T')[0] as ISODateString;
    },

    calculateNextSemiMonthly(date: Date): ISODateString {
        const day = date.getUTCDate();
        const result = new Date(date);

        if (day < 15) {
            // If before 15th, next is 15th
            result.setUTCDate(15);
        } else {
            // If 15th or later, next is 1st of next month
            result.setUTCMonth(result.getUTCMonth() + 1);
            result.setUTCDate(1);
        }

        return result.toISOString().split('T')[0] as ISODateString;
    }
}
